window.__Q=window.__Q||{};window.__Q["tcm/2/A1"]=[{"q":"可辨为“里邪出表”的项是","o":["脘腹冷痛1周，昨起恶寒发热流清涕","头痛多年，今起口眼歪斜","聚餐后腹痛腹泻3日","发热3天，今日疹出热渐退去","咳喘多日，今起咯血"],"a":3,"e":"里邪出表指病邪由里向外透达，麻疹郁热内闭、疹出而热势渐退即其典型，提示正气驱邪外出、病势转轻。B项头痛多年骤见口眼歪斜为风痰阻络之中风；C项聚餐后腹痛腹泻为饮食伤中；A项脘腹冷痛复添恶寒流涕为外感引动伏寒，均非里邪出表"},{"q":"下列哪项不属于心阴虚证的常见症状","o":["心悸","心烦","失眠多梦","口燥咽干","满面通红"],"a":4,"e":"心阴虚证以心悸、心烦、失眠多梦、口燥咽干、舌红少苔、脉细数为常见，由心阴亏少、虚火内扰所致。满面通红为实热证或阴虚阳亢之面色，非本证所有。心烦、心悸定位于心，口燥咽干虽属阴虚，却多见于肺胃阴虚，须与心系症状相区分"},{"q":"肝胃郁热多见","o":["口中酸馊","口中泛酸","口甜","口苦","口黏腻"],"a":1,"e":"肝胃郁热，肝气犯胃、郁而化热，胃气上逆则口中泛酸，常伴嘈杂吞酸、胁胀口苦。口中酸馊为食积胃脘、腐浊上泛；口甜多属脾胃湿热或脾虚；口苦主肝胆火旺；口黏腻为湿浊中阻，皆非肝胃郁热之泛酸"},{"q":"以下不是一息五至以上的脉象的是","o":["动脉","促脉","数脉","滑脉","疾脉"],"a":3,"e":"数脉一息五至以上，疾脉更至七至以上；促脉为数而时止、止无定数；动脉数而滑利、关部如豆，三者均属一息五至以上。滑脉仅言往来流利、如盘走珠，脉率如常，不属数类，故本题为滑脉"},{"q":"下列何项不是导致便秘的常见原因","o":["热结","阴虚","寒凝","湿热","血虚"],"a":3,"e":"便秘多因热结、阴虚血虚肠燥、寒凝气滞等致大肠传导失司。湿热下注多见泄泻、痢疾，湿热蕴结大肠反而迫注，非便秘常见原因。热结肠胃则大便干结，阴虚血虚则肠燥，寒凝则传导迟滞，皆为便秘之常"},{"q":"肺阴虚证的辨证要点是以阴虚证与下列何项共见","o":["干咳少痰","咳痰清稀","咳嗽少气","咳痰黄稠","咳痰量多"],"a":0,"e":"肺阴虚证以阴虚内热与肺失宣降并见为要点，干咳少痰、痰黏难咯或痰中带血、声音嘶哑为其典型。咳痰清稀属寒饮，咳痰黄稠属痰热，咳痰量多属痰湿，咳嗽少气为肺气虚，均非肺阴虚"},{"q":"下列除哪项外均属于麻疹的表现","o":["疹色桃红","形似麻粒","先见于耳后发际","按出疹顺序依次消退","细小稀疏"],"a":4,"e":"麻疹为外感麻毒，疹色桃红、形似麻粒、先见耳后发际、按出疹顺序依次消退，疹点密集均匀。细小稀疏为风疹或隐疹特点，非麻疹表现。麻疹以疹出透彻、分布均匀为顺，稀疏细小提示正气不足或邪郁"},{"q":"望色十法中的“抟”是","o":["浅淡","疏离","壅滞","暗浊","浮露"],"a":2,"e":"望色十法中散与抟相对，抟为面色壅滞聚结、久而不散，多主邪气方盛、病气聚集，病势虽重而邪未散。疏离为散，主邪气解散、病势将退；浮露为浮，主病在表；暗浊为浊，主阴证；浅淡为微，主正虚，皆非抟之义"},{"q":"不属于青色主病的是","o":["寒证","气滞","疼痛","惊风","血虚"],"a":4,"e":"青色主寒证、气滞、疼痛、惊风、瘀血，由寒凝、气滞、血瘀致脉络拘急、血行不畅。血虚面色多淡白或萎黄，不主青。惊风（尤其小儿）眉间鼻柱发青，寒凝血瘀亦青，均属青色所主"},{"q":"下列哪项不属表证的表现","o":["恶寒发热","鼻塞喷嚏","脉浮苔薄","咳吐黄痰","头身疼痛"],"a":3,"e":"表证以恶寒发热并见、鼻塞喷嚏、头身疼痛、脉浮苔薄为特征，为外邪袭表、正邪相争。咳吐黄痰为里热壅肺、痰热内结，属里证。鼻塞喷嚏、头身疼痛、脉浮苔薄皆表证常见"},{"q":"下列哪项不是阳水证的临床表现","o":["起病急，病程短","水肿先从头面肿起","上半身肿甚","水肿皮薄光亮","肢冷，腰酸痛"],"a":4,"e":"阳水起病急、病程短，水肿先从头面、上半身肿甚，皮薄光亮，多由风水、湿热所致。肢冷、腰酸痛为阴水（脾肾阳虚）表现，属寒水内停。起病急、头面先肿、上半身肿甚、皮薄光亮皆阳水特征"},{"q":"以寒热往来，胁肋灼痛，大便不调，小便短赤，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","肝血虚证"],"a":1,"e":"肝胆湿热证见寒热往来、胁肋灼痛、口苦、大便不调、小便短赤、舌红苔黄腻、脉弦滑数，由湿热蕴结肝胆、疏泄失常。寒滞肝脉以少腹冷痛遇寒加重为主；肝郁气滞无湿热之象；热极生风以抽搐为主"},{"q":"肾气不固证的临床特征，不包括","o":["月经淋漓不尽","男子滑精早泄","小便余沥不尽","男子精少不育","女子胎动易滑"],"a":3,"e":"肾气不固以肾气亏虚、封藏失职为核心，见小便余沥、滑精早泄、月经淋漓、胎动易滑。男子精少不育多属肾精不足、生殖功能减退，非固摄失司。滑精早泄、小便余沥、胎动易滑皆封藏不固之象"},{"q":"主肾虚、寒证、水饮、血瘀、疼痛的是","o":["白色","黄色","黑色","青色","红色"],"a":2,"e":"黑色主肾虚、寒证、水饮、血瘀、疼痛，缘肾阳不足、寒水内停或瘀血久滞，面色黧黑晦暗。青色虽主寒痛，兼气滞惊风；白色主虚寒失血；黄色主脾虚湿困；红色主热证，皆非黑色之所主"},{"q":"火淫证的临床表现有","o":["发热恶寒","斑疹","头胀痛","渴不多饮","脉细数"],"a":1,"e":"火淫证见壮热、烦渴、面红目赤、咽喉肿痛、吐衄、发斑发疹、舌红苔黄、脉数有力。斑疹为热入营血、迫血妄行而外发肌肤，属火淫。发热恶寒为表证；渴不多饮主湿热或阴虚；脉细数主阴虚"},{"q":"面色黄而枯槁无光是","o":["萎黄","黄胖","阳黄","阴黄","虚黄"],"a":0,"e":"萎黄为面色淡黄、枯槁无光泽，多由脾胃气虚、气血生化不足、面部失养。黄胖为黄而虚浮，属脾虚湿蕴；阳黄黄而鲜明如橘；阴黄黄而晦暗如烟熏；虚黄多指血虚萎黄之类，与萎黄近义"},{"q":"下列叙述中，正确的一项是","o":["脉来一息七至以上为数脉","动脉与代脉均可由情志刺激引起","浮大无根，应指散漫的脉主诸虚劳损","弱脉是举之无力，按之空虚的脉","细脉必为虚脉"],"a":1,"e":"动脉多由情志刺激、气血逆乱，脉短滑如豆、厥厥动摇；代脉可因惊恐等情志因素致脉气不续、止有定数。七至以上为疾脉非数脉；浮大无根、应指散漫为散脉主元气离散；弱脉沉细而软；细脉亦可见于湿阻，非必虚"},{"q":"苔黑而滑润者多属","o":["阴虚阳亢","饮食停滞","瘀血内停","寒湿内阻","湿热内蕴"],"a":3,"e":"黑苔主热极或寒极，苔黑而滑润、舌质淡者属寒湿内阻、阳虚寒盛；苔黑燥裂生芒刺则属热极津枯。阴虚阳亢见舌红少苔；饮食停滞见厚腻苔；瘀血内停见舌紫暗；湿热内蕴见黄腻苔"},{"q":"伤寒证的临床表现有","o":["腹冷痛","肠鸣腹泻","恶寒发热","恶风汗出","脉沉紧"],"a":2,"e":"伤寒为寒邪袭表、卫阳被遏，以恶寒发热、无汗、头身疼痛、脉浮紧为特征。腹冷痛、肠鸣腹泻为寒邪直中脾胃；恶风汗出为太阳中风；脉沉紧主里寒。恶寒发热是表实证典型"},{"q":"循衣摸床、撮空理线的表现属于","o":["少神","神乱","失神","假神","得神"],"a":2,"e":"循衣摸床、撮空理线为神志昏迷中的无意识动作，属失神，提示正气大伤、病情危重。少神为精神不振但意识清楚；神乱指癫狂痫等精神错乱；假神为久病突然精神好转的回光返照；得神为神志清楚、目光有神"},{"q":"舌体局部出现青紫色斑点，大小不等，不高于舌面，为","o":["紫红舌","紫黑舌","绛紫舌","淡青紫舌","瘀斑舌、瘀点舌"],"a":4,"e":"舌面局部青紫斑点、大小不等、不高于舌面者为瘀斑舌、瘀点舌，主瘀血内停，多因情志、跌仆、寒凝致血行不畅。紫红舌、绛紫舌为舌体整体紫红，主热盛；淡青紫舌为舌淡泛青紫，主阳虚寒凝；皆非局限斑点之瘀斑瘀点"},{"q":"辨别虚实真假的关键是","o":["脉沉取之有力无力","舌质的红与白","病情的轻重程度","病人体质的强弱","腹痛喜冷或喜暖"],"a":0,"e":"辨别虚实真假的关键在脉象沉取之有力无力：沉取有力虽见虚象仍属真实，沉取无力虽见实象多属真虚，当舍症从脉。舌质红白、病情轻重、体质强弱、腹痛喜冷喜暖皆非判别真假之核心依据"},{"q":"皮肤变红，如染脂涂丹，称为","o":["漆疮","丹毒","类丹毒","痈","膏药风"],"a":1,"e":"丹毒为风热火毒或湿热火毒袭表，皮肤突然发红、色如涂丹、边界清楚、灼热肿痛。漆疮为接触漆等所致皮炎；膏药风为膏药过敏；痈为红肿热痛、范围较大的化脓；类丹毒为猪丹毒杆菌感染"},{"q":"肾气竭绝可出现","o":["弹石脉","雀啄脉","虾游脉","屋漏脉","釜沸脉"],"a":0,"e":"弹石脉为十怪脉之一，脉来急促坚硬、如指弹石，主肾气竭绝，真脏脉现、胃气已无。雀啄脉如雀啄食、止而复作，主脾气将绝；虾游脉如虾游水、时隐时现，主孤阳无依；屋漏脉良久一滴，主胃气将绝；釜沸脉浮泛无根，主三阳热极、阴液枯竭"},{"q":"戴阳证的面色为","o":["颧颊嫩红如妆","满面通红","两颧潮红","面色青紫","面色苍白"],"a":0,"e":"戴阳证为下元虚寒、虚阳上浮，面色苍白中见颧颊嫩红如妆、游移不定，属真寒假热。满面通红为实热；两颧潮红为阴虚阳亢；面色青紫主瘀血或寒；面色苍白为血虚或阳虚"},{"q":"燥淫证易发生于","o":["春季","夏季","长夏","秋季","冬季"],"a":3,"e":"燥邪致病有明显季节性，易发生于秋季，秋令干燥、津液易伤，见口鼻干燥、干咳少痰、皮肤干涩。春季多风、夏季多暑、长夏多湿、冬季多寒，各随其令，非燥淫主时"},{"q":"除哪项外，均可引起舌颤动","o":["阴液耗损","阳衰阴盛","气血虚衰","热极动风","肝阳化风"],"a":1,"e":"舌颤动多因肝风内动、气血亏虚或阴液耗损，舌体失养或风动，见于热极动风、肝阳化风、阴液耗损、气血虚衰。阳衰阴盛多致舌体胖大、淡白而润，无风动之象，不主颤动；舌红绛而颤多为热极或阴虚风动，舌淡而颤多为气血虚"},{"q":"舌苔薄白而润，一般不会见于","o":["正常舌象","表证初起","里证病轻","阳虚内寒","阴虚火旺"],"a":4,"e":"薄白润苔为正常舌象，或见表证初起、里证病轻，阳虚内寒亦见舌淡苔白润，皆津液未伤。阴虚火旺津液受损，舌红少苔或剥苔、苔干，绝不见薄白而润之苔。苔由白转黄为化热，苔厚腻为湿滞，与薄白润苔迥异"},{"q":"脉象细软，浮取可得，重按不显者是","o":["虚脉","细脉","濡脉","微脉","散脉"],"a":2,"e":"濡脉脉象细软，浮取即得、重按不显，主湿证或虚证，湿阻气血、脉道不充。虚脉三部举之无力、按之空虚；细脉脉细如线但重按可得；微脉极细极软、若有若无；散脉浮大无根、散漫不齐，皆非濡脉浮细之象"},{"q":"自汗、盗汗并见与下列哪项有关","o":["阴虚证","血虚证","阳虚证","气阴两虚证","血瘀证"],"a":3,"e":"自汗多属阳气虚、卫外不固，盗汗多属阴虚内热、逼津外泄，二者并见为气阴两虚，气虚卫疏与阴虚内热同存。阴虚证仅盗汗、潮热；阳虚证仅自汗、畏寒；血虚、血瘀皆非自汗盗汗并见之常见，心血虚多伴心悸失眠"},{"q":"胃脘冷痛喜按，泛吐清水，恶食生冷，倦怠乏力，舌质淡嫩，脉沉迟无力，证属","o":["胃阳虚证","脾肾阳虚证","寒滞胃脘证","肝胃不和证","肝郁脾虚证"],"a":0,"e":"胃脘冷痛喜按、泛吐清水、恶食生冷、倦怠乏力、舌淡嫩、脉沉迟无力，为胃阳虚、胃失温养、腐熟无权。寒滞胃脘为实寒、痛剧拒按；脾肾阳虚兼腰膝冷、五更泄；肝胃不和兼胁胀；肝郁脾虚兼情志、便溏"},{"q":"肾气不固所致的小便改变为","o":["小便频数而色黄","小便频数而色清","小便频数而色赤","小便频数而混浊","小便频数而涩痛"],"a":1,"e":"肾气不固，封藏失职、膀胱失约，见小便频数、色清、余沥不尽或遗尿，伴腰膝酸软、神疲。色黄、色赤多属热证；小便混浊多为湿浊下注；涩痛为淋证湿热；尿血为血热或结石，皆非肾气不固"},{"q":"皮肤黄中显黑，黑而晦暗，称","o":["肾虚","萎黄","苍黄","黑疸","失荣"],"a":3,"e":"黑疸为黄疸日久、肾虚血瘀，皮肤黄中显黑、黑而晦暗，多由湿热黄疸迁延、瘀血内停。萎黄为淡黄枯槁无光；苍黄为黄而青灰；肾虚见面色黧黑但非黄中夹黑；失荣为气血衰败、面容枯槁，皆非黑疸"},{"q":"多食易饥，大便溏泄是","o":["食积不化","脾胃虚弱","肝脾不和","胃火亢盛","胃强脾弱"],"a":4,"e":"胃强脾弱，胃火亢盛则消谷善饥，脾运失健则大便溏泄，虚实并见。食积不化见腹胀、嗳腐、厌食；脾胃虚弱见纳呆便溏；胃火亢盛仅多食易饥无溏泄；肝脾不和见胁胀腹痛泄泻"},{"q":"下述哪项不是引起气滞证的常见原因","o":["情志不畅","用力闪挫","病邪阻滞","阴血亏虚","阳虚寒凝"],"a":3,"e":"气滞证多因情志不畅、病邪阻滞、用力闪挫、阳虚寒凝等致气机郁滞、运行不畅，以胀满疼痛为主症。阴血亏虚致脉道失充，多见血虚或阴虚内热之干瘦、潮热，非气滞常见原因；饮食不节则多致食积"},{"q":"卫气营血辨证是哪位医家创立的","o":["吴鞠通","叶天士","陈平伯","薛生白","吴又可"],"a":1,"e":"卫气营血辨证由清代叶天士创立，载于《温热论》，用以辨析温病卫、气、营、血四个阶段。吴鞠通创三焦辨证；陈平伯著《外感温病篇》；薛生白著《湿热条辨》；吴又可著《温疫论》主戾气"},{"q":"目部分属五脏中，两眦血络属","o":["肝","脾","心","肺","肾"],"a":2,"e":"目部分属五脏，两眦血络属心，称血轮，心火上炎则两眦赤痛。白睛属肺为气轮，肺热则白睛红赤；黑睛属肝为风轮，肝火则黑睛赤肿；瞳仁属肾为水轮，肾虚则瞳仁灰暗；眼睑属脾为肉轮，脾虚则眼睑浮肿"},{"q":"肝经风热上攻，多见哪种目色异常改变","o":["白睛色红","两眦红肿赤痛","睑缘赤烂","全目赤肿","黑睛赤肿"],"a":3,"e":"肝开窍于目，肝经风热或肝火上攻，气血壅滞于目，致全目赤肿、灼痛羞明。两眦赤痛属心火；白睛红赤属肺热或外感风热；睑缘赤烂属脾经湿热；黑睛赤肿多属肝经风热但局限于黑睛，非全目"},{"q":"不属于外伤病因的是","o":["寄生虫","跌仆损伤","冻伤","烫伤","溺水"],"a":0,"e":"外伤病因包括跌仆损伤、冻伤、烫伤、溺水、金刃、虫兽咬伤等，皆由外力或物理因素直接致病。寄生虫为生物性致病因素，多因饮食不洁侵入人体，属其他病因，非外伤；情志、劳逸亦非外伤"},{"q":"脉来缓而时一止，止无定数的脉象是","o":["代脉","促脉","涩脉","结脉","散脉"],"a":3,"e":"结脉脉来缓慢、时有一止、止无定数，主阴盛气结、寒痰血瘀，止无定数为其要点。代脉止有定数、良久方还，主脏气衰微；促脉数而时止、止无定数，主阳盛实热；涩脉往来艰涩不畅；散脉浮大无根、至数不齐"},{"q":"温病热入营分“口干反不甚渴”的机理是","o":["津液耗伤不甚","津液逐渐恢复","热蒸营阴上潮","邪热迫血妄行","邪热逐渐衰退"],"a":2,"e":"热入营分，邪热蒸腾营阴、津液上潮于口，故口干而不甚渴，伴身热夜甚、舌红绛、脉细数。津液耗伤不甚非其机理；邪热迫血妄行则致斑疹；津液恢复、邪热衰退皆非"},{"q":"继入院记录之后，对患者病情和诊疗过程所进行的连续性记录。内容包括患者的病情变化情况、重要的辅助检查结果及临床意义、上级医师查房意见、会诊意见、医师分析讨论意见、所采取的诊疗措施及效果、医嘱更改及理由、向患者及其近亲属告知的重要事项等。记录书写以上内容的是","o":["门诊病历初诊记录","门诊病历复诊记录","住院病历初诊记录","住院病历复诊记录","病程记录"],"a":4,"e":"病程记录是继入院记录之后对病情和诊疗过程的连续性记录，含病情变化、辅助检查、上级查房、会诊、诊疗措施及效果、医嘱更改、告知事项等。门诊初复诊记录仅记门诊就诊；住院病历初诊为入院时全面记录，皆非连续性病程"},{"q":"下列各项，不属头晕常见原因的是","o":["气血两虚","痰湿内阻","肺阴不足","肝阳上亢","肝火上炎"],"a":2,"e":"头晕多由气血两虚、痰湿中阻、肝阳上亢、肝火上炎等致清窍失养或被扰动，虚者眩晕空乏、实者胀眩。肺阴不足以干咳、咽干、潮热盗汗为主，不直接上扰清窍致头晕。肾精不足、瘀血阻窍亦可头晕，须有别"},{"q":"腹痛作泻，泻后痛减，或大便时干时稀排便不爽，此证属于","o":["肝郁脾虚","肾阳虚","脾阳虚","湿热","食积"],"a":0,"e":"腹痛作泻、泻后痛减，或大便时干时稀、排便不爽，为肝郁脾虚、肝失疏泄、脾失健运、气机紊乱。肾阳虚为五更泄；脾阳虚见腹部冷痛喜温；湿热见泻下黄臭；食积泻后痛减但伴嗳腐腹胀"},{"q":"以视力减退，肢麻震颤，关节拘急，月经量少、色淡，甚则闭经，面白，舌淡，脉细为主要表现的证是","o":["肝阴虚证","肝阳上亢证","肝气郁结证","肝血虚证","血虚生风证"],"a":4,"e":"血虚生风证由肝血亏虚、筋脉失养、虚风内动，见肢麻震颤、关节拘急、视力减退、月经量少色淡甚则闭经、面白舌淡脉细。肝血虚证以血虚失养为主而无明显震颤；肝阴虚伴潮热目涩；肝阳上亢见头胀眩晕；肝气郁结见胁胀抑郁"},{"q":"外感秽浊不正之气，热毒内盛的舌象是","o":["白腻苔","黄腻苔","灰黑苔","腐苔","积粉苔"],"a":4,"e":"积粉苔为舌上白苔如积粉、扪之不燥，由外感秽浊不正之气与热毒相结，多见瘟疫或内痈、热毒内盛。白腻苔主寒湿痰湿；黄腻苔主湿热；灰黑苔主热极或寒极；腐苔为阳热有余、蒸腾胃浊"},{"q":"夜卧不安，伴见脘闷腹胀，嗳气酸馊，舌苔厚腻者，属于","o":["心脾两虚","肝胃不和","脾胃气虚","胆郁痰扰","食积胃脘"],"a":4,"e":"食积胃脘，宿食停滞、胃失和降，见夜卧不安、脘闷腹胀、嗳气酸馊、苔厚腻。心脾两虚见心悸健忘、面白；肝胃不和见胁胀、嗳气吞酸；脾胃气虚见纳呆乏力；胆郁痰扰见惊悸不寐、口苦"},{"q":"下列哪项不是假神之征","o":["形体消瘦","真寒假热证","目光晦滞，浮光外露","食量突然增加","突然精神转佳"],"a":0,"e":"假神为久病危重之人突然精神转佳、目光浮光外露、食量骤增、言语增多，属回光返照、残阳欲绝。形体消瘦为久病消耗常态，非假神。真寒假热是病机；目光晦滞浮光外露、食量增、精神转佳皆假神之征"},{"q":"血虚证必有的特征性表现是","o":["心悸失眠","经少经闭","肢体麻木","头晕眼花","颜色淡白"],"a":4,"e":"血虚证以面色、口唇、爪甲、舌质颜色淡白为必有特征，由血液不足、濡养失职。心悸失眠为心血虚见症；经少经闭为肝血虚；肢体麻木为血虚失养；头晕眼花为清窍失养，皆非共有必见"},{"q":"举之浮大中空，如按葱管，为","o":["濡脉","芤脉","革脉","散脉","洪脉"],"a":1,"e":"芤脉举之浮大、按之中空、如按葱管，主失血、伤阴，血容量骤减、脉管空虚。濡脉浮细而软；革脉浮而搏指、中空外坚如按鼓皮；散脉浮大无根、散漫不齐；洪脉来盛去衰、充实有力"},{"q":"花剥苔多见于","o":["脾虚伤食","湿遏热郁","痰浊未化","胃气阴两伤","脾胃阳虚"],"a":3,"e":"花剥苔为舌苔部分剥落、剥处光滑、余处有苔，主胃气阴两伤、正气渐虚。脾虚伤食见厚腻或剥苔兼腻；湿遏热郁见白腻或黄腻；痰浊未化见腻苔；脾胃阳虚见舌淡苔白润"},{"q":"心脾两虚是指","o":["心脾气血虚","心脾气阴虚","心脾阴阳虚","心脾阳气虚","心脾阴血虚"],"a":0,"e":"心脾两虚即心脾气血两虚，心血不足则心悸失眠健忘，脾气虚则食少乏力、面色萎黄、月经量多色淡、舌淡脉细弱。非气阴虚之潮热盗汗、阴阳虚之寒热并见、阳气虚之形寒肢冷、阴血虚之无脾虚运化失司"},{"q":"虚热证区别于实热证的典型特点有","o":["颧红盗汗","大便干结","小便短黄","舌红","脉数"],"a":0,"e":"虚热证由阴虚内热，见颧红、盗汗、五心烦热、潮热、舌红少苔、脉细数，起病缓、病程长。大便干结、小便短黄、舌红、脉数亦可见于实热，非虚热独有；颧红盗汗是阴虚内热典型"},{"q":"热渐盛而津渐伤的舌象是","o":["舌苔由白转黄","舌苔由厚变薄","舌苔由润变燥","舌光无苔","舌苔黑而燥裂"],"a":2,"e":"苔之润燥反映津液盛衰，热渐盛、津渐伤则舌苔由润转燥，提示津液受损、病势进展。由白转黄主寒化热；由厚变薄主病退；舌光无苔主胃阴大伤；苔黑燥裂主热极津枯"},{"q":"身热不扬，汗出热不解，见于下列何证","o":["脾气虚证","脾阳虚证","脾虚气陷证","寒湿困脾证","湿热蕴脾证"],"a":4,"e":"湿热蕴脾，湿热郁蒸、热被湿遏，故身热不扬、汗出而热不解，伴脘腹痞闷、口黏、苔黄腻、脉濡数。脾气虚见乏力纳差；脾阳虚见寒象；脾虚气陷见下坠脱垂；寒湿困脾见寒象、苔白腻"},{"q":"积粉苔多见于","o":["秽浊湿邪与热毒相结","燥热伤津","痰饮内停","湿浊中阻，津气不化","外感寒湿"],"a":0,"e":"积粉苔白如积粉、满布舌面，由秽浊湿邪与热毒相结，多见瘟疫或内痈。燥热伤津见苔黄燥；痰饮内停见白腻或滑苔；湿浊中阻、津气不化见白腻苔；外感寒湿见薄白腻苔"},{"q":"疮疡漫肿无头，肤色晦黯，局部麻木，不热少痛为","o":["痈","疽","疔","疖","丹毒"],"a":1,"e":"疽为阴证疮疡，气血亏虚、寒凝滞络，见漫肿无头、肤色晦黯、不热少痛、局部麻木，难溃难敛。痈为阳证，红肿热痛、范围大；疔小而坚硬、根脚坚硬；疖小而局限、红肿热痛；丹毒色红如丹"},{"q":"虚脉的脉象特征是","o":["脉细如线，软弱无力","极细极软，若有若无","沉细而软，应指无力","三部脉举之均无力，按之空虚","浮细而软，应指无力"],"a":3,"e":"虚脉三部举之无力、按之空虚，主虚证，气血不足、脉道失充。脉细如线软弱无力为细脉，主血虚湿证；极细极软若有若无为微脉；沉细而软应指无力为弱脉；浮细而软为濡脉，皆非虚脉三部皆空虚之象"},{"q":"主元气离散，脏腑之气将绝的脉象是","o":["弱脉","散脉","虚脉","微脉","细脉"],"a":1,"e":"散脉浮大无根、应指散漫、至数不齐、按之消失，主元气离散、脏腑之气将绝，为危候。弱脉沉细而软，主血虚阳虚；虚脉三部无力而按之空虚；微脉极细极软、若有若无；细脉脉细如线但应指明显，皆非散脉"},{"q":"下列除哪项外，均为疹的临床表现","o":["色红","点小如粟","压之不退色","高出皮肤","抚之碍手"],"a":2,"e":"疹为红色小点、高出皮肤、抚之碍手、点小如粟、色红，压之褪色，多由外感风热或疫疹，麻疹、风疹皆然。压之不退色为斑之特征，斑点大成片、平摊于皮面、抚之不碍手，多由热入营血、迫血妄行"},{"q":"下列哪项不是寒证与热证的鉴别要点","o":["脉迟与脉数","尿清长与尿短黄","口渴与不渴","头痛与不痛","苔黄与苔白"],"a":3,"e":"寒热鉴别要点有脉迟与脉数、尿清长与尿短黄、口渴与不渴、苔白与苔黄、恶寒与恶热、四肢温凉等，皆反映阴阳偏盛偏衰。头痛与不痛为疼痛有无，可见于寒热各类，不区分寒热属性，故非鉴别要点"},{"q":"以下不属于浮脉类的是","o":["浮脉","濡脉","洪脉","长脉","芤脉"],"a":3,"e":"浮脉类包括浮、洪、濡、散、芤、革等，脉位偏浮、轻取即得，主表证或虚阳外浮。长脉脉体超过寸关尺、首尾端直，位置不属浮类，主阳气有余或热证；沉脉类脉位深在，须重按始得，与浮脉类相对"},{"q":"脾有湿热可出现","o":["睑缘赤烂","全目赤肿","目眦淡红","目窠浮肿","白睛红赤"],"a":0,"e":"脾开窍于口、眼睑属脾为肉轮，脾经湿热上攻则睑缘赤烂、生疮、眵多黏结。全目赤肿属肝火上攻；目眦淡红属心血不足；目窠浮肿为水肿或脾虚湿盛；白睛红赤属肺热或外感风热，皆非脾湿热之睑缘赤烂"},{"q":"区别病邪性质的主要依据是","o":["舌体的颜色","舌苔的厚薄","舌体的动态","舌苔的颜色","舌下络脉"],"a":3,"e":"舌苔颜色可辨病邪性质：白苔主寒、表；黄苔主热、里；灰黑苔主热极或寒极。苔之厚薄辨邪正盛衰与病位深浅；舌体颜色辨脏腑气血；舌体动态辨风与虚；舌下络脉辨瘀血"},{"q":"舌中部所候的脏腑一般是","o":["脾胃","肝胆","心肺","肾","三焦"],"a":0,"e":"舌面分候脏腑，舌尖候心肺，心肺居上焦；舌中候脾胃，脾胃居中焦；舌根候肾与下焦，肾居下焦；舌边候肝胆，肝居右胁。三焦多候于舌根或分部，非舌中部所主，各脏腑分候井然"},{"q":"胸背彻痛剧烈，主要是由于","o":["痰浊阻肺","痰热蕴肺","心血不足","心脉闭塞","心阳亏虚"],"a":3,"e":"胸背彻痛剧烈、卒然发作，为心脉闭塞、瘀血阻络、心血运行中断之真心痛，属危急重症。痰浊阻肺见胸闷咳喘；痰热蕴肺见咳黄痰；心血不足见心悸头晕隐痛；心阳亏虚见胸闷心悸、畏寒"},{"q":"满面通红者多属于","o":["阴虚阳亢","真寒假热","实热证","戴阳证","虚热证"],"a":2,"e":"满面通红为实热证，邪热亢盛、气血上涌，面红目赤、口渴喜冷、脉洪数。阴虚阳亢仅两颧潮红；真寒假热之戴阳颧颊嫩红如妆；虚热证颧红盗汗；戴阳属假热，非满面通红"},{"q":"泻下黄臭秽稀便，排便不爽者，其病机是","o":["暑热内蕴","脾气虚弱","湿热","肝郁脾虚","肺热移肠"],"a":2,"e":"泻下黄臭秽稀便、排便不爽、肛门灼热为湿热下注大肠、传导失司。暑热内蕴兼明显暑象；脾气虚弱见便溏纳差；肝郁脾虚见腹痛即泻、泻后痛减；肺热移肠多见泄泻伴咳喘"},{"q":"肝经风火上扰不会导致","o":["目痒","目痛","雀盲","目眩","目赤"],"a":2,"e":"肝经风火上扰，风火循经上攻于目，见目赤、目痛、目眩、目痒、羞明流泪，起病急、疼痛剧。雀盲（夜盲）为肝血不足、精血亏虚、目失所养，起病缓、夜间视物不清，非风火实证所致。目干涩亦属阴虚血亏"},{"q":"中医诊断学的基本原理与近代控制论的“黑箱”理论相似之处的是","o":["以常衡变","见微知著","司外揣内","四诊合参","整体审察"],"a":2,"e":"司外揣内是通过观察外在表现推测体内变化，与近代控制论黑箱理论相似，不打开机体而由输出推知内部。以常衡变是以正常衡异常；见微知著是由局部测整体；四诊合参强调诸诊并用；整体审察强调人与环境统一"},{"q":"按痰饮停积的部位分类，饮留胃肠的是","o":["痰饮","支饮","溢饮","悬饮","伏饮"],"a":0,"e":"痰饮（狭义）为饮邪停于胃肠，见脘腹痞满、呕吐清水、肠鸣漉漉、口干不欲多饮。支饮为饮停胸膈、咳逆倚息；溢饮为饮溢四肢肌肤、身肿无汗；悬饮为饮停胸胁、咳唾引痛；伏饮为饮邪伏留、遇感即发"},{"q":"苔黑燥裂，甚则生芒刺，多为","o":["热入营血","热极津枯","肾阴亏虚","寒极","湿热"],"a":1,"e":"苔黑燥裂、甚生芒刺为热极津枯、邪热伤津耗液，多属实热重证，伴高热、烦渴、便秘、尿黄。热入营血见舌红绛而干；肾阴亏虚见舌红少苔；寒极见苔黑滑润、舌淡；湿热见黄腻苔，皆非燥裂芒刺"},{"q":"脉体宽大，充实有力，状若波涛汹涌，来盛去衰，是","o":["浮脉","散脉","实脉","大脉","洪脉"],"a":4,"e":"洪脉脉体宽大、充实有力、状若波涛汹涌、来盛去衰，主气分热盛。浮脉轻取即得、按之稍减；散脉浮大无根；实脉三部举按均有力、来去俱盛；大脉仅脉体宽大而无汹涌之势"},{"q":"口气酸臭，多属","o":["疮疡溃腐","食积胃肠","口腔不洁","脏腑败坏","湿热久蕴"],"a":1,"e":"口气酸臭、嗳气酸腐为食积胃肠、宿食停滞、胃气上逆，伴脘腹胀满、厌食、苔厚腻。疮疡溃腐致口气腐臭；口腔不洁致口气秽浊；脏腑败坏致口气腥臭难闻；湿热久蕴致口中黏腻或口苦，皆非酸臭"},{"q":"胃气虚证与脾气虚证的鉴别，最有意义的症状是","o":["是否面色萎黄","有无少气懒言","有无神疲肢倦","是否大便稀溏","是否舌淡脉弱"],"a":3,"e":"胃气虚与脾气虚均见食少、神疲、少气懒言、舌淡脉弱，但脾气虚健运失职必见大便稀溏，胃气虚则无，故有无便溏为鉴别关键。面色萎黄、肢倦懒言、舌淡脉弱为二者共有"},{"q":"下列哪项不属于黑色的主病","o":["肾虚","寒证","水饮","血瘀","失血"],"a":4,"e":"黑色主肾虚、寒证、水饮、血瘀、疼痛，面黑黯淡或黧黑因肾阳虚衰、寒水内停或瘀血阻滞。失血后面色多苍白或萎黄，血不上荣，不主黑。肾虚见面黑；寒证、水饮见面色黧黑或眼眶黑；血瘀见面色晦暗"},{"q":"小腿青筋暴露，久立后更明显，多因","o":["寒湿久留","寒湿内侵、瘀血阻络","气血亏虚","痰瘀阻络","风湿久蕴"],"a":1,"e":"小腿青筋暴露、久立更甚为下肢络脉瘀曲，因寒湿内侵、瘀血阻络、气血运行不畅。寒湿久留偏重关节冷痛；气血亏虚无青筋；痰瘀阻络多见结节肿块；风湿久蕴见关节痹痛"},{"q":"口苦而黏腻多属","o":["伤食","肝胆火旺","肝胆湿热","脾胃湿热","肝胃不和"],"a":2,"e":"口苦而黏腻为肝胆湿热，湿热蕴结肝胆、胆气上溢则口苦，湿浊内阻则黏腻不爽，伴胁胀、尿黄、苔黄腻。伤食见口气酸腐；肝胆火旺仅口苦而无黏腻；脾胃湿热见口甜或口黏；肝胃不和见嗳气吞酸"},{"q":"小便混浊如米泔，见于下列何证","o":["脾气虚证","脾阳虚证","脾不统血证","脾虚气陷证","寒湿困脾证"],"a":3,"e":"小便混浊如米泔为脾虚气陷、清阳不升、清浊混淆、精微外泄，伴久泻脱肛、神疲。脾气虚证仅见纳呆乏力；脾阳虚兼寒象；脾不统血见出血；寒湿困脾见苔白腻、脘闷"},{"q":"齿痕舌常与下列哪种舌象并见","o":["胖大舌","瘦薄舌","裂纹舌","芒刺舌","歪斜舌"],"a":0,"e":"齿痕舌为舌体胖大、受齿缘压迫形成齿痕，多因脾虚湿盛、水湿不化，故常与胖大舌并见。瘦薄舌主气血阴亏；裂纹舌主阴亏或血虚；芒刺舌主热盛；歪斜舌主中风或风中经络"},{"q":"下列各项，属于“症状”的是","o":["心烦失眠","喉中痰鸣","腹如舟状","脉细无力","舌苔薄黄"],"a":0,"e":"症状是患者主观不适，心烦失眠属自觉症状，病人可自述。喉中痰鸣为听诊所及之体征；腹如舟状为望诊体征；脉细无力为切诊脉象；舌苔薄黄为望诊舌象，皆医者察知，非患者主观感觉"},{"q":"下列各项，属于脾气虚证与脾阳虚证的鉴别要点的是","o":["形寒肢冷","食少纳呆","腹胀便溏","肢倦懒言","舌淡苔白"],"a":0,"e":"脾气虚与脾阳虚均见食少纳呆、腹胀便溏、肢倦懒言、舌淡苔白，皆脾失健运。但脾阳虚兼寒象，见形寒肢冷、腹部冷痛喜温、小便清长，故形寒肢冷为鉴别要点；脉迟缓无力亦有助于辨寒"},{"q":"突发片状脱发，显露圆形或椭圆形的光亮头皮而无自觉症状，称为斑秃，多为","o":["精血不足","血虚受风","血热化燥","劳神伤血","疳积"],"a":1,"e":"斑秃为突发片状脱发、圆形或椭圆形光亮头皮、无自觉症状，多因血虚受风、风邪乘虚袭入、发失所养。精血不足见发黄干枯稀疏；血热化燥见脱发伴热象；劳神伤血见渐进脱发；疳积见小儿发稀"},{"q":"语声重浊多为","o":["外感风燥","外感风寒","外感风热","寒邪客肺","热邪壅盛"],"a":1,"e":"语声重浊为外感风寒、肺气壅遏、气道不利，鼻塞声重，伴恶寒发热、无汗。外感风燥见干咳声哑；外感风热见声音嘶哑咽痛；寒邪客肺见咳喘痰稀；热邪壅盛见声高气粗、谵语，皆非重浊"},{"q":"属于舌象生理变异的是","o":["光线影响","年龄因素","染苔","喝牛奶","长期服用某些抗生素"],"a":1,"e":"舌象生理变异包括年龄、体质、性别等因素，如小儿舌嫩红、老人舌偏暗、女性经期舌象变化。光线影响、染苔、喝牛奶、长期服抗生素均为外界因素造成的舌象改变，属非生理变异，须与之区分"},{"q":"釜沸脉的脉象是","o":["短小坚搏，如循薏苡子","如釜中沸水，浮泛无根","脉来乍疏乍密，如解乱绳状","急促坚硬如弹石","如屋漏残滴，良久一滴"],"a":1,"e":"釜沸脉脉如釜中沸水、浮泛无根、数极无序，主三阳热极、阴液将竭。短小坚搏如循薏苡子为雀啄脉；乍疏乍密如解乱绳为解索脉；急促坚硬如弹石为弹石脉；良久一滴如屋漏残滴为屋漏脉"},{"q":"下列哪项不是面色白的主病","o":["虚寒","气血不足","失血","热证","阳气虚弱"],"a":3,"e":"白色主虚寒、气血不足、失血、阳气虚弱，因气血亏虚、阳气不足、面部失养或血不上荣，见淡白㿠白。热证面色多红赤、目赤，不主白。失血后亦见面白，仍属血虚失荣，与热证赤色迥异"},{"q":"虫积肠道证所致饮食异常最易表现为","o":["嗜食异物","多食易饥","饥不欲食","偏食酸辣","厌食油腻"],"a":0,"e":"虫积肠道，寄生虫扰动、脾胃运化失常，见嗜食异物如泥土纸张、面黄肌瘦、腹痛。多食易饥属胃火或胃强脾弱；饥不欲食属胃阴不足；偏食酸辣无特异性；厌食油腻属肝胆湿热或脾虚"},{"q":"下列哪项不见消谷善饥","o":["胃火亢盛","胃阴不足","胃强脾弱","消渴","瘿病"],"a":1,"e":"消谷善饥为胃火亢盛、腐熟太过，食入即饥，见于胃火、胃强脾弱、消渴、瘿病等。胃阴不足、虚火内扰则饥不欲食、口干咽燥、舌红少苔，不出现消谷善饥，二者一实一虚，截然不同"},{"q":"濡脉与弱脉的不同点主要表现在","o":["脉位","脉力","脉宽","脉长","脉律"],"a":0,"e":"濡脉与弱脉均细软无力，主虚或湿，但濡脉浮取即得、脉位浮，弱脉沉取始得、脉位沉，二者主要区别在脉位。脉力均软弱非区别点；脉宽、脉长、脉律二者相近，非主要不同，临证以指力轻重辨之"},{"q":"判断胃气渐复可见","o":["舌苔剥落部位时时转移","舌苔从全到剥","舌苔剥落后复生薄白之苔","剥落处全无舌苔","未剥落处似有腻苔或滑苔"],"a":2,"e":"舌苔剥落后复生薄白苔，提示胃气渐复、正气来复。苔剥落部位时时转移为气阴两伤、病势进展；苔从全到剥为胃阴渐伤；剥落处无苔为胃阴大伤；未剥处腻苔为湿浊未尽"},{"q":"脘腹痞闷，腹痛便溏，纳呆口腻，头身困重，苔白腻，脉濡缓，证属","o":["湿热蕴脾证","饮停胃肠证","脾阳虚证","寒湿困脾证","肝胃不和证"],"a":3,"e":"寒湿困脾，寒湿内盛、困阻脾阳、运化失司，见脘腹痞闷、腹痛便溏、纳呆口腻、头身困重、苔白腻、脉濡缓。湿热蕴脾见苔黄腻、身热；饮停胃肠见肠鸣、呕吐清水；脾阳虚见寒象；肝胃不和见胁胀"},{"q":"由于气候影响，平脉在冬天可见","o":["浮","沉","洪","弦","迟"],"a":1,"e":"平脉随四季气候而变，春弦、夏洪、秋浮、冬沉，阳气随季节浮沉。冬令寒凝、阳气内藏，脉象偏沉，重按始得。浮为秋令轻虚之脉；洪为夏令盛大之脉；弦为春令端直之脉；迟脉主寒，非四季平脉常规"},{"q":"舌红绛，苔少而干，多见于","o":["寒邪直中","痰饮内停","湿热困脾","营血热盛","瘀血内停"],"a":3,"e":"舌红绛、苔少而干为热入营血、营阴受损、津液耗伤，伴身热夜甚、神昏谵语、斑疹隐隐。寒邪直中见舌淡苔白；痰饮内停见舌淡胖苔滑；湿热困脾见舌红苔黄腻；瘀血内停见舌紫暗"},{"q":"巅顶痛属","o":["太阳经头痛","阳明经头痛","少阳经头痛","少阴经头痛","厥阴经头痛"],"a":4,"e":"巅顶痛属厥阴经头痛，足厥阴肝经连目系、上出额、与督脉会于巅，肝经病变循经上逆。太阳经头痛在头后部连项；阳明经在前额眉棱骨；少阳经在头两侧耳后；少阴经头痛伴齿痛、脉细"},{"q":"短脉的主病是","o":["虚证","实证","气病","血病","寒证"],"a":2,"e":"短脉脉短不及本部、首尾俱短，主气病：有力为气郁气滞，无力为气虚，气不足以充脉道。虚证、实证范围过泛，非短脉所独主；血病多见涩细脉；寒证多见迟紧脉，皆非短脉之主病"},{"q":"下列何项不属对婴儿问诊的内容","o":["喂养的方法","预防接种情况","胸腹有无胀痛","坐爬立走的时间","出牙学语的迟早"],"a":2,"e":"婴儿问诊主要包括喂养方法、预防接种、生长发育如坐爬立走时间、出牙学语迟早等，由家长代述。胸腹有无胀痛属按诊内容，婴儿亦难自述，非问诊项目；哭闹、睡卧姿态可旁参，但非直接问诊"},{"q":"舌痿软而淡白无华者，多属于","o":["热极伤阴","气血俱虚","阴虚火旺","肝肾阴虚","风痰阻滞"],"a":1,"e":"舌痿软而淡白无华为气血俱虚、舌体失养、筋脉无力，不能伸缩，伴面色淡白、气短乏力。热极伤阴见舌红绛痿软；阴虚火旺见舌红少苔；肝肾阴虚见舌红少津；风痰阻滞见舌歪斜或强硬不灵"},{"q":"气滞证的特征表现是","o":["头昏眼花","胀满疼痛","绞痛","脘腹坠胀","手足发麻"],"a":1,"e":"气滞证以胀满疼痛为特征，气机郁滞、不通则痛，痛处走窜、时轻时重、随情绪或排气变化。头昏眼花属血虚或肝阳；绞痛为实邪骤阻；脘腹坠胀为气陷；手足发麻为血虚失养"},{"q":"发黄干枯，稀疏易落，多为","o":["精血不足","血虚受风","气血亏虚","先天不足","疳积"],"a":0,"e":"发黄干枯、稀疏易落多为精血不足、发失所养，见于久病虚劳、肾精亏虚，伴面色晦暗、腰膝酸软。血虚受风见斑秃片状脱落；气血亏虚见发淡黄细软；先天不足见小儿发迟；疳积见小儿发枯如穗"},{"q":"辨别寒热真假的重要依据是","o":["脉象沉取的有力与无力","满面通红与颧浮红如妆","语声的洪亮与低怯","舌质的苍老与娇嫩","胀痛是否拒按"],"a":1,"e":"辨别寒热真假的重要依据是面色：满面通红、持续不退为实热，颧浮红如妆、游移不定为戴阳（真寒假热）。脉沉取有力无力辨虚实真假；语声洪亮低怯、舌质苍老娇嫩、胀痛拒按为辅助，非寒热真假之核心"},{"q":"心气虚的面色表现为下列哪项","o":["面色淡白","面色㿠白","面色萎黄","面色青紫","面色黧黑"],"a":0,"e":"心气虚，心气不足、推动无力、面色失养，见面色淡白、心悸气短、自汗、舌淡脉虚，动则加重。面色㿠白多属阳虚水泛；萎黄属脾虚血弱；青紫主瘀血或寒凝；黧黑主肾虚，皆非心气虚本色"},{"q":"对里证的描述不正确的是","o":["多见于内伤杂病之中","外感病无里证","外邪可直中脏腑","情志致病发即里证","厥阴病证"],"a":1,"e":"里证可因病邪直中脏腑、表邪入里或情志饮食内伤而成，外感病传变入里即有里证，如阳明腑实、热入营血，故外感病无里证之说错误。外感病初起多见表证，但非始终无里证"},{"q":"不属于佝偻病患儿常见表现的是","o":["方颅","鸡胸","肋如串珠","梭状指","项软"],"a":3,"e":"佝偻病患儿常见方颅、鸡胸、肋如串珠、项软、下肢弯曲等，由维生素D缺乏、骨骼钙化障碍，兼夜惊、多汗。梭状指为类风湿关节炎等关节病变表现，手指关节梭形肿胀，非佝偻病"},{"q":"脉来缓而时止，止无定数，为","o":["代脉","促脉","涩脉","结脉","濡脉"],"a":3,"e":"结脉脉来缓慢、时有一止、止无定数，主阴盛气结、寒痰瘀血。代脉止有定数、良久方还；促脉数而时止、止无定数；涩脉往来涩滞不畅；濡脉浮细而软，皆非结脉缓中止无定数之象。结与促皆止无定数，惟结脉来缓、促脉来数"},{"q":"以下哪项不属脉体宽大的脉象","o":["洪脉","大脉","芤脉","革脉","牢脉"],"a":3,"e":"脉体宽大者如洪脉宽大有力、大脉宽大、芤脉浮大中空、牢脉沉大实长，皆形阔大。革脉浮而搏指、中空外坚、如按鼓皮，脉体不宽大，主精血亏虚、亡血失精；细脉脉细如线，与宽大相反"},{"q":"举之无力，按之空虚，为","o":["弱脉","虚脉","涩脉","微脉","濡脉"],"a":1,"e":"虚脉三部举之无力、按之空虚，主虚证，气血不足、脉道失充。弱脉沉细而软；涩脉往来艰涩如轻刀刮竹；微脉极细极软、若有若无；濡脉浮细而软，皆非虚脉三部举按皆无力空虚之象"},{"q":"弦脉的脉象是","o":["脉气紧张，端直而长","脉来绷急，状如牵绳","浮而搏指，滑数有力","沉按实大，弦长有力","状如波涛，来盛去衰"],"a":0,"e":"弦脉端直以长、脉气紧张、如按琴弦，主肝胆病、痛证、痰饮。脉来绷急如牵绳为紧脉；浮而搏指、滑数有力非弦；沉按实大、弦长有力为牢脉；来盛去衰如波涛为洪脉"},{"q":"以肢体震颤，手足拘急，爪甲不荣，面白无华，舌质淡白，脉细或弱为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","肝胆湿热证"],"a":0,"e":"血虚生风证由肝血不足、筋脉失养、虚风内动，见肢体震颤、手足拘急、爪甲不荣、面白无华、舌淡、脉细弱。肝阳化风见头胀眩晕、抽搐；阴虚风动见潮热、舌红少苔；热极生风见高热抽搐；肝胆湿热见湿热象"},{"q":"三部脉举之无力，按之空虚的脉象，属于","o":["芤脉","虚脉","浮脉","散脉","绝脉"],"a":1,"e":"三部举之无力、按之空虚为虚脉，主气血俱虚，气不足以鼓、血不足以充。芤脉浮大中空如葱管，主失血；浮脉轻取即得、按之稍减；散脉浮大无根、散漫不齐；绝脉为危重之象，均非虚脉"},{"q":"肝阳上亢证与肝火炽盛证均可见","o":["吐血衄血","头重脚轻","头晕耳鸣","腰膝酸软","五心烦热"],"a":2,"e":"肝阳上亢与肝火炽盛均有肝气上逆、上扰清窍，见头晕耳鸣、头胀、面红、急躁易怒。吐血衄血多属肝火犯肺或血热；头重脚轻、腰膝酸软为肝阳上亢独有之上实下虚；五心烦热属阴虚"},{"q":"厚苔不见于哪项","o":["胃肠食滞","痰浊停滞","病位在里","外感风寒","肠热腑实"],"a":3,"e":"厚苔主邪盛入里、胃肠积滞、痰湿内停，见于食滞、痰浊、里热腑实，苔厚为邪气盛。外感风寒邪轻在表，多见薄白苔；病位在里则苔厚；薄苔主病轻或表证，故厚苔不见于外感风寒初起"},{"q":"肝郁气滞证与肝火炽盛证均可见","o":["情志抑郁","面红目赤","舌体淡白","月经后期","胁肋疼痛"],"a":4,"e":"肝郁气滞与肝火炽盛均病在肝、肝气失疏，故均见胁肋疼痛，但一为气郁、一为火盛。情志抑郁为肝郁气滞；面红目赤、口苦为肝火炽盛；舌淡白非二者共有；月经后期多为肝郁或血虚，非肝火"},{"q":"心阴虚证的脉象是","o":["脉细数","脉细弦","脉细弱","脉细迟","脉沉细"],"a":0,"e":"心阴虚证阴液亏少、虚火内扰，脉细数，伴心悸、心烦、失眠多梦、舌红少苔、盗汗。细弦主气滞或肝郁；细弱主气血虚；细迟主寒；沉细主里虚血少，皆非心阴虚阴虚火旺之脉"},{"q":"以头目胀痛，眩晕耳鸣，面红目赤，急躁易怒，失眠多梦，头重脚轻，腰膝酸软，舌红少津，脉弦或弦细数为主要表现的证候是","o":["肝胆湿热证","肝风内动证","肝阳上亢证","肝火炽盛证","寒滞肝脉证"],"a":2,"e":"肝阳上亢为肝肾阴虚、肝阳偏亢、上实下虚，见头目胀痛、眩晕耳鸣、面红目赤、急躁易怒、头重脚轻、腰膝酸软、舌红少津、脉弦或细数。肝火炽盛为实火、无腰膝酸软；肝风内动见抽搐震颤；肝胆湿热见苔黄腻；寒滞肝脉见寒象"},{"q":"温病化热，津液暴伤可见","o":["苔白而湿润","薄白苔","积粉苔","苔白糙裂","白腻苔"],"a":3,"e":"温病化热、津液暴伤，舌苔白而干燥糙裂，甚至燥裂如锯，为津伤之象，伴身热、烦渴。苔白湿润为正常或寒湿；薄白苔为表证；积粉苔为秽浊热毒；白腻苔为寒湿或痰湿，皆非糙裂"},{"q":"咳吐脓血腥臭痰，多属","o":["肺热","肺痨","肺胀","肺痿","肺痈"],"a":4,"e":"肺痈为热毒壅肺、血肉腐败，见发热、胸痛、咳吐脓血腥臭痰、舌红苔黄腻。肺热见咳黄稠痰；肺痨见干咳咯血、潮热盗汗；肺胀见咳喘、胸部膨满；肺痿见咳吐浊唾涎沫"},{"q":"临床提示正气不足，精气轻度损伤，脏腑功能减弱，此属于","o":["得神","少神","失神","假神","神乱"],"a":1,"e":"少神为正气不足、精气轻度损伤、脏腑功能减弱，见精神不振、懒言、动作迟缓、目光少彩，介于得神与失神之间。得神为精充气足；失神为精亏神衰、病情危重；假神为回光返照；神乱为精神错乱"},{"q":"由于气候影响，平脉在秋天可见","o":["浮","沉","洪","弦","迟"],"a":0,"e":"秋令清凉、阳气渐收，平脉偏浮、轻虚而浮如毛，故秋季可见浮脉，重按稍减。冬沉主寒凝内藏；夏洪主热盛脉大；春弦主肝气条达；迟脉主寒证，非秋季平脉特征。浮脉主表亦主秋，须结合时令辨之"},{"q":"痰湿困脾所致嗜睡的表现是","o":["困倦嗜睡，头脑昏沉","精神疲惫，似睡非睡","饭后嗜睡，神疲倦怠","高热神迷，昏昏欲睡","昏睡伴有鼾声，痰鸣"],"a":0,"e":"痰湿困脾，湿浊困阻、清阳不升，见困倦嗜睡、头脑昏沉、头重如裹、苔腻、脉濡。精神疲惫似睡非睡为心脾两虚或气血不足；饭后嗜睡属脾气虚；高热神迷为热入心包；昏睡伴鼾声痰鸣为痰迷心窍"},{"q":"寒证的典型舌象是","o":["舌红苔黄而干","舌淡白苔白腻","舌青紫苔黄腻","舌绛苔干","舌绛紫无苔"],"a":1,"e":"寒证舌象见舌淡白、苔白或白腻、舌体胖嫩润泽，因寒凝、阳气不足、气血不荣。舌红苔黄干为热证；舌青紫苔黄腻为瘀血湿热；舌绛苔干为热入营血；舌绛紫无苔为阴虚或瘀血"},{"q":"气滞类证不包括下列哪项","o":["气滞证","气逆证","气郁证","气闭证","气陷证"],"a":4,"e":"气滞类证包括气滞、气郁、气逆、气闭等，以气机郁滞、升降失常为主，见胀满疼痛。气陷证为气虚升举无力、清阳下陷，见久泻脱肛、内脏下垂，属气虚类证，非气滞类"},{"q":"小儿食指络脉诊法始见于","o":["《内经》","《察病指南》","《伤寒论》","《景岳全书》","《水镜图诀》"],"a":4,"e":"小儿食指络脉诊法首载于唐代《水镜图诀》，后经《小儿药证直诀》等发扬。《内经》为医籍之祖；《察病指南》为宋代诊断著作；《伤寒论》主伤寒辨证；《景岳全书》为明代张景岳所著"},{"q":"下列哪项可导致尿后余沥不尽","o":["结石阻塞","肾阳虚","肾阴虚","瘀血内阻","肾气不固"],"a":4,"e":"尿后余沥不尽为肾气不固、封藏失职、膀胱失约，排尿后点滴不尽，伴腰膝酸软、小便频数。结石阻塞见排尿中断涩痛；肾阳虚见畏寒、五更泄；瘀血内阻见刺痛；肾阴虚见潮热尿黄"},{"q":"弦细脉的主病为","o":["血虚肝郁","肝郁气滞","肝胆湿热","水饮内停","气血不足"],"a":0,"e":"弦细脉主血虚肝郁，弦主肝郁气滞、细主血虚，二者并见为肝郁血虚，见胁胀、月经不调、头晕。肝郁气滞脉弦不细；肝胆湿热脉弦滑数；水饮内停脉弦滑；气血不足脉细弱"},{"q":"根据五轮学说，白睛属","o":["心","肺","脾","肝","肾"],"a":1,"e":"五轮学说中白睛属肺，称气轮，肺热则白睛红赤；两眦属心为血轮，心火则两眦赤痛；眼睑属脾为肉轮，脾虚则眼睑浮肿、湿热则睑缘赤烂；黑睛属肝为风轮，肝火则黑睛赤肿；瞳仁属肾为水轮，肾虚则瞳仁灰暗"},{"q":"寒证的典型临床表现有","o":["恶热喜冷","口渴欲饮","痰、涕黄稠","小便短黄","舌淡苔白"],"a":4,"e":"寒证见恶寒喜暖、口淡不渴、肢冷蜷卧、小便清长、大便稀溏、舌淡苔白、脉迟或紧，因阳气不足、阴寒内盛。恶热喜冷、口渴欲饮、痰涕黄稠、小便短黄皆为热证表现，与寒证相反"},{"q":"下列何项与肝郁化火失眠无关","o":["心悸健忘","烦躁失眠","面目红赤","脉象弦数","性急易怒"],"a":0,"e":"肝郁化火失眠见烦躁易怒、面目红赤、脉弦数、性急易怒、口苦咽干，由肝火上扰心神。心悸健忘为心脾两虚或心血不足、心神失养，非肝郁化火；头晕目眩、便秘尿黄可伴见于肝火"},{"q":"下列除哪项外，均可导致便秘","o":["阳虚","气虚","血虚","阴虚","湿热"],"a":4,"e":"便秘多因阳虚寒凝、气虚推动无力、血虚肠燥、阴虚津亏致大肠传导失司，粪便干结难下。湿热下注大肠多致泄泻、痢疾或便溏不爽、肛门灼热，非便秘常见原因；热结腑实则属便秘之实证"},{"q":"暑邪的致病特点有","o":["干涩伤津","多夹湿","易生风动血","易扰神明","易致肿疡"],"a":1,"e":"暑邪致病有明显季节性，其性炎热升散、耗气伤津，且多夹湿，见身热、口渴、乏力、胸闷、苔腻。干涩伤津属燥邪；易生风动血属火热之邪；易扰神明属火热；易致肿疡属火邪"},{"q":"脉“有胃气”主要是指","o":["不浮不沉，不大不小","柔和有力，节律一致","从容流利，和缓律齐","尺脉有力，沉取不绝","一息四至，闰以五至"],"a":2,"e":"脉有胃气表现为从容流利、和缓律齐、不浮不沉、不大不小、柔和有力，说明脾胃功能正常、气血有源。不浮不沉等为平脉特征；柔和有力节律一致侧重有神；尺脉有力沉取不绝为有根；一息四至为平脉"},{"q":"脉形浮大而软，按之中空，属于","o":["散脉","虚脉","芤脉","革脉","濡脉"],"a":2,"e":"芤脉浮大而软、按之中空、如按葱管，主失血伤阴，营血暴脱、脉管空虚。散脉浮大无根、散漫不齐；虚脉三部举按无力、按之空虚；革脉浮而搏指、中空外坚；濡脉浮细而软，皆非芤脉"},{"q":"微脉、弱脉和濡脉共有的特征是","o":["脉细如线","细小无力","浮取即得","沉取始得","紧涩不畅"],"a":1,"e":"微脉极细极软、若有若无；弱脉沉细而软；濡脉浮细而软，三者均细小无力。浮取即得仅濡脉；沉取始得仅弱脉；脉细如线为细脉，重按可得；紧涩不畅为涩紧之脉，皆非三者共有"},{"q":"痰湿困脾所致嗜睡的特点是","o":["精神疲惫，似睡非睡","饭后嗜睡，神疲倦怠","昏睡伴有鼾声、痰鸣","困倦嗜睡，头脑昏沉","困倦嗜睡，睡后易醒"],"a":3,"e":"痰湿困脾，湿重困遏清阳，见困倦嗜睡、头脑昏沉、肢体困重、苔腻。精神疲惫似睡非睡为气血不足；饭后嗜睡属脾虚；昏睡伴鼾声痰鸣为痰迷心窍；睡后易醒为心脾两虚"},{"q":"下列哪种情况中不会出现滑脉","o":["实热","妊娠","疼痛","宿食","痰湿"],"a":2,"e":"滑脉往来流利、如盘走珠、应指圆滑，主痰湿、食积、实热、妊娠气血充盛，脉道充盈、气血流畅。疼痛多见弦脉或紧脉，因痛则气滞、脉气紧张，非滑脉主病；涩脉往来艰涩，与滑脉相反"},{"q":"肺热炽盛证的辨证要点是以咳喘、胸痛与下列何项共见","o":["里实热证","表实热证","里虚热证","风热表证","痰热里证"],"a":0,"e":"肺热炽盛证以咳喘、胸痛、口渴、便秘、尿黄与里实热证之壮热、苔黄、脉数有力共见为辨证要点。表实热证兼恶寒；里虚热证见潮热盗汗；风热表证见咽痛脉浮数；痰热里证以痰多黄稠为主"},{"q":"属于血分证病位的是","o":["肺","胸膈","肝肾","胃","胆"],"a":2,"e":"血分证为温病最深阶段，热入血分、耗血动血，病位在肝肾，见身热夜甚、神昏谵语、斑疹、出血、舌深绛。卫分在肺卫；气分在肺胃胸膈；营分在心包，皆非血分病位"},{"q":"三部脉举按均有力，来去俱盛的脉象，属于","o":["洪脉","滑脉","紧脉","实脉","弦脉"],"a":3,"e":"实脉三部举按均有力、来去俱盛、脉大有力，主实证，邪盛正实、脉道充盈。洪脉来盛去衰如波涛，但按之稍减；滑脉往来流利；紧脉绷急有力如牵绳；弦脉端直而长如按琴弦"},{"q":"下列哪项不会导致泄泻","o":["脾胃虚弱","肾阴亏虚","肾阳不足","大肠湿热","肠胃积滞"],"a":1,"e":"泄泻多因脾胃虚弱、肾阳不足之五更泄、大肠湿热、肠胃积滞、肝郁脾虚等致运化失常、传导失司，粪质稀溏。肾阴亏虚以潮热、口干、大便干结为主，津亏肠燥，不导致泄泻"},{"q":"下述哪项不是导致口气秽臭的原因","o":["口腔不洁","龋齿","消化不良","胃热","脾胃虚寒"],"a":4,"e":"口气秽臭多因口腔不洁、龋齿、消化不良、胃热、脏腑积热等，浊气上蒸于口，伴口渴、牙龈肿痛。脾胃虚寒无热浊上蒸，多见口淡不渴、畏寒便溏、舌淡，不致口气秽臭。口气酸腐为食积，可资区别"},{"q":"湿邪困阻气机所致疼痛的特点是","o":["胀痛","冷痛","隐痛","重痛","绞痛"],"a":3,"e":"湿性重浊黏滞，困阻气机、遏抑清阳，疼痛以沉重感为主，称重痛，伴头重如裹、肢体困重、苔腻、脉濡。胀痛属气滞，痛处走窜；冷痛属寒，遇温则减；隐痛属虚，喜按；绞痛为实邪骤阻"},{"q":"阴虚风动证与血虚生风证均可见到的症状是","o":["四肢颤动","面红目赤","舌体淡白","角弓反张","腰膝酸软"],"a":0,"e":"阴虚风动与血虚生风均属虚风内动，皆见四肢颤动、手足蠕动等动风表现。面红目赤属实热或阴虚火旺；舌体淡白为血虚；角弓反张为热极生风或破伤风；腰膝酸软为阴虚"},{"q":"月经推迟7天以上，量少、色淡而质稀者，属于","o":["血虚","血寒","血热","血瘀","气滞"],"a":0,"e":"月经后期、量少、色淡质稀为血虚，血液不足、冲任失充，兼面色淡白、头晕心悸。血寒见经色暗红有块、小腹冷痛；血热见经色鲜红量多；血瘀见色暗有块刺痛；气滞见色暗、胀痛"},{"q":"鱼翔脉的主病是","o":["肾与命门之气皆亡","三阴寒极，阳亡于外","三阳热极，阴液枯竭","孤阳无依，躁动不安","胃气营卫将绝"],"a":1,"e":"鱼翔脉为十怪脉之一，脉浮数、如鱼游翔、时隐时现，主三阴寒极、阳气外亡。肾与命门之气皆亡为弹石脉；三阳热极阴液枯竭为釜沸脉；孤阳无依躁动不安为虾游脉；胃气营卫将绝为屋漏脉"},{"q":"口干，但欲漱水不欲咽，多为","o":["外感风热","外感温热","湿热内蕴","里热炽盛","瘀血内阻"],"a":4,"e":"口干但欲漱水不欲咽为瘀血内阻，瘀血内停、津液不能上承，故口干而不欲咽，伴舌紫暗、肌肤甲错。外感风热见口渴；外感温热见烦渴；湿热内蕴见口黏不渴；里热炽盛见大渴喜冷饮"},{"q":"下列哪项是面色黑的主病","o":["虚寒、瘀血、水饮","肾虚、寒证、水饮及血瘀","肾虚、痛证","肾虚、水饮","寒湿、痰饮"],"a":1,"e":"黑色主肾虚、寒证、水饮、血瘀、疼痛，面黑黯淡因肾阳虚衰、寒水内停或瘀血阻滞。虚寒、水饮概括不全；肾虚、痛证不全面；肾虚、水饮缺寒瘀；寒湿、痰饮非黑色所主"},{"q":"以少腹冷痛，牵引阴部坠胀作痛，遇寒痛甚，畏寒肢冷，舌淡苔白，脉沉紧或弦紧为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","肝阴虚证"],"a":0,"e":"寒滞肝脉证为寒邪侵袭肝经、凝滞气血，见少腹冷痛、牵引阴部坠胀、遇寒加重、畏寒肢冷、舌淡苔白、脉沉紧或弦紧。肝胆湿热见苔黄腻、阴部瘙痒；肝郁气滞见胀痛、情志相关；热极生风见高热抽搐；肝阴虚见潮热、舌红少苔"},{"q":"舌尖所候的脏腑一般是","o":["脾胃","肝胆","心肺","肾","三焦"],"a":2,"e":"舌面分候脏腑：舌尖候心肺，心肺居上焦；舌中候脾胃，脾胃居中焦；舌根候肾与下焦，肾居下焦；舌边候肝胆，肝居右胁。脾胃候舌中；肝胆候舌边；肾候舌根；三焦多候于舌根"},{"q":"面色青黄者，多属","o":["阴寒内生","寒邪凝滞","心脉痹阻","热盛动风","肝郁脾虚"],"a":4,"e":"面色青黄相兼为肝郁脾虚，肝失疏泄则面色青，脾失健运则面黄，伴胁胀、纳差、便溏。阴寒内生见面色青白；寒邪凝滞见面青或青紫；心脉痹阻见面色青紫；热盛动风见面红或青，伴高热抽搐"},{"q":"下列各项，不属寒湿困脾证的临床表现的是","o":["面黄鲜明","腹胀便溏","口腻纳呆","肢体困重","脉象濡缓"],"a":0,"e":"寒湿困脾见腹胀便溏、口腻纳呆、肢体困重、苔白腻、脉濡缓、面黄晦暗，因寒湿困阻脾阳、运化失司。面黄鲜明如橘为阳黄、湿热蕴结之象，非寒湿；寒湿困脾面色多黄而晦暗，兼畏寒肢冷"},{"q":"以两目干涩，胁肋灼痛，两颧潮红，五心烦热，舌红少苔，脉弦细数为主要表现的证是","o":["肝阴虚证","肝血虚证","肝阳上亢证","肝气郁结证","血虚生风证"],"a":0,"e":"两目干涩、胁肋灼痛为肝阴不足、虚火内灼，两颧潮红、五心烦热、舌红少苔、脉弦细数均属阴虚内热。肝血虚证以视物昏花、肢体麻木、面色无华为主，绝无潮热。肝阳上亢证见头胀痛、面红目赤、脉弦有力，非细数。血虚生风证以肢体震颤、肌肤瘙痒为特征"},{"q":"产后大出血，继则冷汗淋漓，甚则晕厥。其病机是","o":["气滞血瘀","气不摄血","气随血脱","气血两虚","气血失和"],"a":2,"e":"产后大出血致气随血外脱，气脱则卫外不固、神机失养，故冷汗淋漓、晕厥。气不摄血证以慢性出血伴气虚为主，无暴脱之象。气血两虚证起病缓慢，见面白神疲、心悸气短，不呈冷汗晕厥。气滞血瘀证以刺痛、肿块为要，与出血脱证无涉"},{"q":"紧脉的主病是","o":["邪闭","厥证","肿痈","湿证","宿食"],"a":4,"e":"紧脉绷急有力、状如转索，主寒、痛、宿食，宿食停滞中焦、气机壅塞故见紧。湿证脉濡缓，与紧之绷急迳庭。肿痈属热壅血聚，脉见滑数。厥证为气机逆乱、阳气衰微，脉多沉微欲绝，皆非紧脉所主"},{"q":"《诊家正眼》在《濒湖脉学》的基础上又增加一种脉象是","o":["疾脉","结脉","紧脉","牢脉","数脉"],"a":0,"e":"《濒湖脉学》载脉二十七种，《诊家正眼》在其基础上增补疾脉，合为二十八种。结脉、紧脉、数脉、牢脉均已在《濒湖脉学》之中，并非新增。疾脉脉率一息七八至，主阳极阴竭、元气将脱"},{"q":"表现为神志清楚，而吐字困难不清，语言不流畅的是","o":["狂言","错语","呓语","言謇","谵语"],"a":3,"e":"言謇指神志清楚而吐字困难、语言不流畅，多因风痰阻络、舌强不灵，常见于中风先兆或后遗症。谵语为神昏时胡言乱语，属热扰心神。狂言为妄语狂躁，多见癫狂。错语是语后自知言错，呓语为睡中梦话，均与舌强语謇不同"},{"q":"脉率迟缓，时见一止，止无定数，是指","o":["代脉","促脉","结脉","动脉","涩脉"],"a":2,"e":"结脉为脉率迟缓、时见一止、止无定数，主阴盛气结、寒痰血瘀。代脉亦时一止，但止有定数、良久方还，主脏气衰微。促脉为数而时止、止无定数，属阳盛热结。动脉滑数有力、如豆厥厥动摇，涩脉往来艰涩不畅，皆非缓中一止"},{"q":"手指关节呈梭状畸形，活动受限者，多因","o":["寒湿内侵","瘀血阻络","寒湿久留","风湿久蕴、痰瘀阻络","气血亏虚"],"a":3,"e":"手指关节梭状畸形、活动受限为痹证日久，风湿之邪久蕴，痰瘀互结、阻滞关节经络所致。寒湿内侵或寒湿久留多见关节冷痛、遇寒加重，无明显梭状畸形。瘀血阻络以刺痛固定为主，气血亏虚则关节酸软无力"},{"q":"下列哪项不属于舌态的变化","o":["痿软","强硬","歪斜","胖大","短缩"],"a":3,"e":"舌态指舌体动态变化，包括痿软、强硬、歪斜、颤动、吐弄、短缩等。胖大属舌形异常，为舌体体积增大，多因脾肾阳虚、水湿内停。痿软、强硬、歪斜、短缩皆为舌态改变，与胖大分属不同望诊范畴"},{"q":"引起阳黄的主要病机是","o":["痰热","寒湿","脾虚","肝失疏泄","湿热"],"a":4,"e":"阳黄因湿热之邪蕴结脾胃、熏蒸肝胆，胆汁外溢肌肤，故身目鲜黄如橘、色泽鲜明。寒湿困脾致阴黄，黄色晦暗如烟熏。脾虚黄疸多见萎黄，无鲜明之色。肝失疏泄可致黄疸但非阳黄主要病机，痰热与黄疸关系较远"},{"q":"属于证候错杂关系的是","o":["表实寒证、表实热证、里实寒证","表实热证、里实寒证、里实热证","里实寒证、里实热证、里虚寒证","表寒里热证、上热下寒证、里虚表实证","里实热证、里虚寒证、里虚热证"],"a":3,"e":"证候错杂指同一患者同时存在性质相反的两组证候，如表寒里热、上热下寒、里虚表实，分属表里、寒热、虚实相兼。表实寒证、表实热证、里实寒证等仅为单一证候并列，非错杂。里实热证、里虚寒证、里虚热证亦属单纯证候组合，不构成错杂关系"},{"q":"胸闷心悸，咳嗽气喘，牵引疼痛，属","o":["饮停胸胁","饮停肠间","饮停于胃","水饮凌心","痰湿阻肺"],"a":0,"e":"饮停胸胁即悬饮，水饮停于胸胁、气机阻滞，故胸闷、咳嗽气喘、牵引胸胁作痛。饮停于胃为痰饮，见脘闷、呕吐清涎。饮停肠间致肠间沥沥有声、腹满。水饮凌心则心悸、胸闷、下肢水肿，无胸胁牵引痛。痰湿阻肺以咳嗽痰多为主"},{"q":"下列哪项对诊断脾肺气虚证最有意义","o":["咳喘短气、食少便溏","咯痰清稀、面白神疲","肢体浮肿、舌淡脉弱","气短而喘、声低懒言","纳少腹胀、身倦乏力"],"a":0,"e":"脾肺气虚证辨证须肺脾气虚并见，咳喘短气属肺气亏虚，食少便溏属脾气虚弱，二者合见最具诊断意义。咯痰清稀、面白神疲仅示肺气虚。纳少腹胀、身倦乏力仅为脾虚。肢体浮肿、舌淡脉弱为气虚水停，均不及肺脾同病指向明确"},{"q":"下列各项，不属“证名”的是","o":["肝阳化风","烂喉丹痧","脾肾阳虚","痰热壅肺","膀胱湿热"],"a":1,"e":"证名是对疾病当前病理本质的概括，肝阳化风、脾肾阳虚、痰热壅肺、膀胱湿热皆为证候诊断。烂喉丹痧是具体病名，为感受痧毒疫疠之邪所致的急性传染病，不属证候名称"},{"q":"根据五轮学说，风轮是指目的哪个部位","o":["瞳仁","黑睛","两眦","白睛","眼睑"],"a":1,"e":"五轮学说将目分属五脏，风轮为黑睛，属肝，肝主风故名。瞳仁为水轮属肾，两眦为血轮属心，白睛为气轮属肺，眼睑为肉轮属脾。黑睛与肝风、肝火病变关系密切，余者各归其脏"},{"q":"表现为语言低微，气短不续，欲言不能复言的是","o":["少气","夺气","气粗","短气","气微"],"a":1,"e":"夺气指语言低微、气短不续、欲言不能复言，为元气大虚、气不接续之象。少气为呼吸微弱、气短不足以息，声低而无欲言不能复言。短气为呼吸短促、似喘非喘。气微、气粗分别指气息微弱与粗重，均无欲言难续之特征"},{"q":"下列哪项不属于心血虚证的常见症状","o":["心悸","头晕眼花","失眠多梦","面色㿠白","健忘"],"a":3,"e":"心血虚证以心悸、失眠多梦、头晕眼花、健忘、面色淡白或萎黄为主，由心血不足、心神失养所致。面色㿠白多属阳气亏虚、水寒上泛，非心血虚常见之色。心悸、头晕眼花、失眠多梦、健忘皆为心血虚辨证要点"},{"q":"现病史的时间界限是","o":["医生认为最恰当的时间","无明确的时间界限","当前所有症状出现的时间","既往史涉及病痛的时间","主诉所述症状所定的时间"],"a":4,"e":"现病史围绕主诉展开，记述主诉所述症状从发生到就诊的演变过程，其时间界限即主诉症状所定之时。既往史所述病痛时间归属既往史。医生主观划定或笼统的当前症状时间均不合规范，现病史不取此类界限"},{"q":"心阳暴脱证与心脉痹阻证不同的症状是","o":["心胸憋闷","痛引肩背","气短乏力","冷汗淋漓","脉沉无力"],"a":3,"e":"心阳暴脱为心阳骤然衰亡、阳气外脱，故见冷汗淋漓、四肢厥冷、脉微欲绝，属危候。心脉痹阻以心胸憋闷疼痛、痛引肩背为主，虽可有气短乏力、脉沉无力，但无冷汗淋漓之亡阳表现。冷汗淋漓是二者鉴别关键"},{"q":"肠热腑实证发热的特点是","o":["骨蒸潮热","身热不扬","暮热早凉","身热夜甚","日晡潮热"],"a":4,"e":"肠热腑实证因燥热与糟粕搏结于大肠，阳明经气旺于日晡，故发热于申时前后加剧，称日晡潮热。骨蒸潮热属阴虚内热，暮热早凉为温病后期邪伏阴分，身热夜甚入营分，身热不扬为湿温郁遏，均非阳明腑实之热型"},{"q":"下列各项，不属胃热炽盛证的临床表现的是","o":["胃脘灼痛","消谷善饥","龈肿齿衄","舌红少苔","便秘尿黄"],"a":3,"e":"胃热炽盛证见胃脘灼痛、消谷善饥、龈肿齿衄、便秘尿黄、舌红苔黄，为胃中实热。舌红少苔是胃阴虚、虚热内生的舌象，与实热之黄苔不同。胃脘灼痛、消谷善饥、龈肿齿衄、便秘尿黄皆属胃热炽盛常见表现"},{"q":"两颧潮红多见于","o":["阴虚阳亢","外感发热","真寒假热","气虚发热","火热炽盛"],"a":0,"e":"两颧潮红为阴虚火旺、虚火上炎之征，多见阴虚阳亢、肺肾阴虚等证。外感发热、火热炽盛多见满面通红。真寒假热见面色浮红如妆、游移不定。气虚发热见面白或萎黄、身热而颧不红"},{"q":"表现为咳声重浊紧闷，痰多色白易咯的是","o":["风寒束表","寒邪客肺","痰湿阻肺","阴虚肺燥","热邪壅肺"],"a":2,"e":"咳声重浊紧闷、痰多色白易咯为痰湿壅肺、肺气失宣之象。风寒束表、寒邪客肺多见咳嗽声重、痰稀色白，兼表证或寒象明显，痰量不似此多。阴虚肺燥为干咳少痰，热邪壅肺见痰黄稠、咳声洪亮"},{"q":"饮停胸胁证属饮证中之","o":["支饮","悬饮","痰饮","溢饮","淡饮"],"a":1,"e":"饮停胸胁、咳唾引痛者为悬饮，水饮流注胸胁、络脉受阻。支饮为饮停胸膈、喘满倚息，溢饮为饮溢四肢、身体疼重，痰饮为饮停胃肠、脘闷呕涎。淡饮非四饮之一，悬饮与其余诸饮停聚部位迥异"},{"q":"舌下络脉粗胀，或呈青紫、紫红、绛紫、紫黑色，多见于","o":["血瘀","寒凝","热极","痰阻","气滞"],"a":0,"e":"舌下络脉粗胀、青紫或紫黑为血行瘀滞、脉络不畅之象，是血瘀证的局部征象。寒凝多见舌淡紫、苔白，热极见舌绛紫、苔黄燥，痰阻见舌苔厚腻，气滞虽可致血行不畅但舌下络脉改变不及血瘀显著"},{"q":"大便溏泄黄糜，多为","o":["脾胃虚寒","胃热炽盛","食积大肠","胃腑气滞","大肠湿热"],"a":4,"e":"大便溏泄黄糜、色黄质稀如糜，为大肠湿热下注、传导失司。脾胃虚寒见便溏清稀、腹部冷痛。胃热炽盛多见便秘、口渴。食积大肠见大便酸腐、夹不化物。胃腑气滞以脘胀嗳气为主，均无黄糜之湿热特征"},{"q":"判断正气渐衰，可见","o":["舌苔从全到剥","舌苔剥落处复生薄白之苔","未剥落处似有腻苔或滑苔","剥落处似存新生颗粒","舌苔剥落部位时时转移"],"a":0,"e":"舌苔由全苔渐次剥落，示胃气、胃阴受损，正气渐衰。剥落处复生薄白之苔、似存新生颗粒为胃气渐复、正气来复。未剥处腻苔或滑苔提示湿浊未尽，剥落部位时时转移为地图舌，多属气阴两虚而非单纯正衰"},{"q":"脉“有根”主要是指","o":["不浮不沉，不大不小","柔和有力，节律一致","不快不慢，和缓有力","尺脉有力，沉取不绝","一息四至，闰以五至"],"a":3,"e":"脉之有根以尺脉为凭，尺脉有力、沉取不绝示肾气充足、元气未损，虽病亦易复。不浮不沉、不大不小为有胃气，柔和有力、节律一致为有神，一息四至、闰以五至描述平脉至数，均非有根之谓"},{"q":"渴喜热饮，但饮水不多，多属","o":["湿热证","水逆证","瘀血","痰饮内停","阳明经证"],"a":3,"e":"渴喜热饮而饮水不多，为痰饮内停、津液不布，虽渴而不欲多饮，饮入易停。水逆证见水入即吐。湿热证口渴喜冷饮，阳明经证见大渴喜冷饮、汗多脉洪，瘀血见但欲漱水不欲咽，皆非渴喜热饮而少饮"},{"q":"惊风常见面色是","o":["赤色","黄色","黑色","青色","白色"],"a":3,"e":"青色主寒、痛、气滞、血瘀、小儿惊风，惊风肝风内动、筋脉拘急，故面色青，尤以眉间、鼻柱、唇周为著。赤色主热，黄色主湿、脾虚，黑色主寒、痛、肾虚，白色主虚、寒、失血，均非惊风常色"},{"q":"小儿发结如穗，枯黄无泽，伴见面黄肌瘦者，多为","o":["疳积","精血不足","脾胃虚弱","劳神伤血","血虚受风"],"a":0,"e":"小儿发结如穗、枯黄无泽、面黄肌瘦为疳积，因喂养不当、脾胃受损、气血亏虚，毛发失养。精血不足、脾胃虚弱虽可见发枯，但无发结如穗之典型疳积貌。劳神伤血、血虚受风多见脱发，非疳积发枯"},{"q":"目部五脏分属中的水轮是","o":["目眦","瞳仁","白睛","眼睑","黑睛"],"a":1,"e":"五轮学说中水轮为瞳仁，属肾，肾主水故名，瞳仁病变多从肾论治。目眦为血轮属心，白睛为气轮属肺，眼睑为肉轮属脾，黑睛为风轮属肝。瞳仁属水轮，余者分属他脏"},{"q":"实证的络脉异常有","o":["络色深浓而黯滞","络色浅谈而枯槁不泽","络脉淡白纤细","络脉沉隐","络脉鲜红"],"a":0,"e":"小儿指纹诊法中，络色深浓而黯滞为实证，邪气壅滞、气血不畅。络色浅谈而枯槁不泽、淡白纤细、沉隐均为虚证，示正气不足、气血亏虚。络脉鲜红多属外感风寒或表热初起，非实证之黯滞"},{"q":"缓脉常见于","o":["水饮内停","湿邪困阻","气滞血瘀","食积停滞","虚阳浮越"],"a":1,"e":"缓脉脉来和缓、一息四至，主湿证，因湿性黏滞、阻遏气机，脉见怠缓。水饮内停多见弦脉或滑脉，气滞血瘀见涩脉或弦脉，食积停滞见滑脉或紧脉，虚阳浮越见浮大无根之脉，皆非缓脉所主"},{"q":"外感热病，邪热深入营分，多见","o":["淡舌","红舌","绛舌","青舌","紫舌"],"a":2,"e":"绛舌为深红色舌，邪热深入营分、营阴受损、血液浓缩，故舌质绛红，多见外感热病热入营血。淡舌主虚寒、气血不足，红舌主热但较浅，青舌主寒凝血瘀，紫舌主血瘀或热极，均非热入营分之典型舌象"},{"q":"煤气中毒的患者可见","o":["口唇樱桃红色","口唇淡白","口唇红赤","口唇青紫","口唇青黑"],"a":0,"e":"煤气中毒即一氧化碳中毒，碳氧血红蛋白形成致口唇、面颊呈樱桃红色，具特征性。口唇淡白为血虚，红赤为热盛，青紫为缺氧或血瘀，青黑为寒极、痛证，均非煤气中毒之樱桃红"},{"q":"《濒湖脉学》中记载的脉象有","o":["24种","27种","28种","33种","32种"],"a":1,"e":"《濒湖脉学》为李时珍所撰，记载脉象二十七种，为后世脉学之基础。二十八种为《诊家正眼》增疾脉后之数，另有医籍载二十四脉、三十二脉、三十三脉者，皆非《濒湖脉学》之数"},{"q":"下列哪项不是肾阴虚证与肾精不足的共同表现","o":["腰膝酸软","遗精","女子经少","经闭","男子精少"],"a":1,"e":"肾阴虚证与肾精不足证均见腰膝酸软、女子经少、经闭、男子精少，皆本于肾精亏虚。遗精为肾阴虚、相火妄动、精关不固所独有，肾精不足以精少、生育功能减退为主，无遗精。故遗精非二者共有"},{"q":"厌食油腻厚味，胁肋胀痛，苔黄腻者，多为","o":["伤食","气滞","肝胆病","妊娠","脾胃病"],"a":2,"e":"厌食油腻厚味、胁肋胀痛、苔黄腻为肝胆湿热、疏泄失常、胆汁外溢之象，病在肝胆。伤食见嗳腐吞酸、脘胀，气滞以胀痛走窜为主，妊娠有停经史，脾胃病以纳呆腹胀、便溏为主，均不若肝胆病之胁痛、厌油、黄腻苔典型"},{"q":"半表半里证的典型表现为","o":["腹痛喜按","口渴喜饮","胸胁苦满","鼻塞流涕","小便清长"],"a":2,"e":"半表半里证即少阳证，邪郁枢机，见往来寒热、胸胁苦满、口苦咽干目眩、脉弦。腹痛喜按属里虚寒，口渴喜饮属里热伤津，鼻塞流涕为表证，小便清长为里寒，皆非半表半里之特征"},{"q":"脉极细极软，按之欲绝，似有若无属，称为","o":["散脉","虚脉","濡脉","微脉","数脉"],"a":3,"e":"微脉极细极软、按之欲绝、似有若无，为阳气衰微、气血大虚之象。散脉浮散无根、至数不齐，虚脉三部举按无力，濡脉浮细而软，数脉仅言至数快，均与微脉之细软欲绝不同"},{"q":"湿浊内蕴，阳气被遏，湿浊痰饮停聚舌面，可见","o":["燥苔","腐苔","剥苔","润苔","腻苔"],"a":4,"e":"腻苔苔质致密、颗粒细小、如涂油腻，为湿浊内蕴、阳气被遏、痰饮停聚舌面。燥苔津液不足、苔干，腐苔苔质疏松如豆腐渣，剥苔苔层脱落，润苔仅为津液未伤之正常表现，均非湿浊痰饮之腻苔"},{"q":"气滞心脉之心脉痹阻证心胸疼痛的特点是","o":["刺痛","胀痛","冷痛","灼痛","闷痛"],"a":1,"e":"气滞心脉之心脉痹阻，因气机郁滞、血脉不畅，心胸疼痛以胀痛为特点，伴胸闷、脉弦。刺痛为瘀血阻络，冷痛为寒凝心脉，灼痛为热邪或阴虚火旺，闷痛为痰浊闭阻，各随病机而异"},{"q":"面色青黑主病为","o":["痛","热","湿","虚","燥"],"a":0,"e":"青色、黑色均主寒、痛、气滞、血瘀，面色青黑多因寒邪凝滞、气血不通，不通则痛。热证见面赤，湿证见面黄而垢，虚证见面白或萎黄，燥证见面干，均非青黑所主之痛证"},{"q":"鉴别表证与里证主要审察","o":["寒热","头痛","腹痛","咳嗽","脉象"],"a":0,"e":"表证与里证鉴别重在寒热：表证恶寒发热并见，里证但热不寒或但寒不热。头痛、咳嗽可表里皆有，腹痛多属里，脉象浮沉虽可佐证但非首要，故寒热之有无与形式是辨别表里的关键"},{"q":"患部形小而圆，突起根浅，红肿热痛不甚，易于成脓，脓出即愈，为","o":["疽","痈","疔","疖","丹毒"],"a":3,"e":"疖形小而圆、突起根浅、红肿热痛不甚、易成脓、脓出即愈，为火热毒邪壅聚局部、气血凝滞。痈红肿范围较大、根脚坚硬、疼痛剧烈，疽为阴证、漫肿不红、少痛，疔根脚坚硬如钉、病情凶险，丹毒为皮肤焮红灼热、边界清楚"},{"q":"面色黧黑，肌肤甲错者，多为","o":["肾虚水饮","肾阴虚火旺","瘀血久停","寒湿带下","肾阳虚衰，血失温养"],"a":2,"e":"面色黧黑、肌肤甲错为瘀血久停、肌肤失养之征，瘀阻脉络、血不荣肤。肾虚水饮见面黑而暗、下肢水肿，肾阴虚火旺见两颧潮红、五心烦热，寒湿带下见面白或晦暗、带下清稀，肾阳虚衰、血失温养见面白㿠白，均非瘀血之黧黑甲错"},{"q":"以男性阴囊瘙痒、潮湿，女性外阴湿疹或阴器肿痛、带下黄臭，舌红，苔黄腻，脉弦滑数为主要表现的证候是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","胆郁痰扰证"],"a":1,"e":"阴囊瘙痒潮湿、外阴湿疹、带下黄臭、舌红苔黄腻、脉弦滑数为肝胆湿热下注，湿热循经外溢。寒滞肝脉见少腹冷痛、阴囊冷缩，肝郁气滞见胁肋胀痛、脉弦，热极生风见抽搐，胆郁痰扰见惊悸失眠，均无湿热下注之征"},{"q":"下列选项中，均具有脉搏有力特点的脉象是","o":["牢脉，实脉，洪脉，弦脉","洪脉，实脉，弦脉，芤脉","牢脉，革脉，弦脉，弱脉","弱脉，革脉，伏脉，牢脉","牢脉，弱脉，沉脉，伏脉"],"a":0,"e":"牢脉沉实大弦长、坚牢不移，实脉三部有力，洪脉来盛去衰、脉体阔大，弦脉端直以长、如按琴弦，四者皆脉搏有力。芤脉浮大中空、革脉外坚中空、弱脉沉细无力、伏脉沉伏不出，均非有力之脉"},{"q":"神疲乏力，面色萎黄，食少，便溏，皮下紫斑，证属","o":["脾气虚证","脾虚气陷证","脾不统血证","脾阳虚证","寒湿困脾证"],"a":2,"e":"神疲乏力、面色萎黄、食少便溏为脾气虚弱，皮下紫斑为脾不统血、血溢脉外，故属脾不统血证。脾气虚证无出血，脾虚气陷证以脱垂、久泻为主，脾阳虚证见腹部冷痛、畏寒，寒湿困脾证见苔白腻、口黏，均无紫斑"},{"q":"与忧伤证无关的是","o":["烦躁多怒","情绪忧虑","抑郁寡欢","表情淡漠","善太息"],"a":0,"e":"忧伤证以情绪忧虑、抑郁寡欢、表情淡漠、善太息为主，因忧悲伤肺、气机郁滞。烦躁多怒属怒志，为肝气郁结化火或肝阳上亢之情志表现，与忧伤证之悲忧低沉相反，故与忧伤证无关"},{"q":"肠热腑实证与肠燥津亏证均可见","o":["神昏谵语","脉数有力","热结旁流","大便秘结","腹痛拒按"],"a":3,"e":"肠热腑实证与肠燥津亏证皆因大肠传导失司，故均见大便秘结。神昏谵语、热结旁流、腹痛拒按、脉数有力为肠热腑实之实热征，肠燥津亏以津枯肠燥为主，无此热实之象，便秘是其共有"},{"q":"属于温病中焦病证的症状是","o":["恶寒","耳聋","手足蠕动","鼻塞","腹满"],"a":4,"e":"温病中焦病证病在脾胃，见腹满、便秘、口干咽燥、潮热，为邪热结肠。恶寒、鼻塞属上焦肺卫，耳聋、手足蠕动属下焦肝肾，非中焦所主，故腹满为中焦病证之症状"},{"q":"以下症状表现为牙关紧急的是","o":["口张","口噤","口撮","口振","口动"],"a":1,"e":"口噤指牙关紧急、口不能张，多因肝风内动、破伤风或热盛动风，筋脉拘急。口张为口开不闭、虚证，口撮为上下唇紧聚如鱼口，口振为口唇颤动，口动为口唇频繁抽动，均与牙关紧急之口噤不同"},{"q":"医生用指掌稍用力寻抚胸腹、腧穴、肿胀等部位，称为","o":["按法","摸法","触法","压法","叩法"],"a":1,"e":"摸法为医生以指掌稍用力寻抚胸腹、腧穴、肿胀等部位，探查局部形态、温度、硬度。触法仅轻手触按感知冷热，按法为重手按压以探深部，压法侧重深压，叩法以手指叩击听声，用力与方式均与摸法有别"},{"q":"下列脉象中不主虚证的是","o":["浮脉","牢脉","微脉","细脉","濡脉"],"a":1,"e":"牢脉沉按实大弦长、坚牢不移，主实寒、积聚、癥瘕，为邪实内结，不主虚证。浮脉主表，亦可见虚阳浮越；微脉、细脉、濡脉皆体细力弱，主气血亏虚、湿困，与牢脉之实大有力相反"},{"q":"下列各项，不属血瘀证的临床表现的是","o":["痛如针刺","腹内肿块","出血反复不止","头晕胀痛","面色黧黑"],"a":3,"e":"血瘀证以痛如针刺、痛处固定、腹内肿块、出血反复不止、面色黧黑、肌肤甲错、舌紫暗瘀点为主。头晕胀痛多因肝阳上亢、肝火上炎或痰火上扰，非血瘀之典型表现，余项皆属血瘀"},{"q":"与湿证有关的脉象是","o":["迟脉，弱脉，濡脉","弱脉，细脉，散脉","细脉，濡脉，缓脉","涩脉，微脉，濡脉","弱脉，濡脉，涩脉"],"a":2,"e":"湿证脉象以细、濡、缓为常见：湿阻脉道则细，湿邪困表则濡，湿遏气机则缓。迟脉主寒，弱脉主虚，散脉主元气离散，涩脉主气滞血瘀，微脉主阳气衰微，均非湿证所主之脉"},{"q":"黄糙苔主","o":["里热炽盛，阴津耗竭","风寒入里，化热伤津","邪热伤津，燥结腑实","气血亏虚，复感湿热","痰热内蕴，食积化腐"],"a":2,"e":"黄糙苔苔色黄、质粗糙少津，为邪热伤津、燥结腑实，热盛津伤、腑气不通。里热炽盛、阴津耗竭见焦黄或黑燥苔，风寒入里化热非苔黄糙之典型，气血亏虚复感湿热、痰热食积化腐各有其苔，非黄糙所主"},{"q":"沉迟脉的主病多为","o":["里寒证","肝郁气滞","水饮内停","气滞血瘀","阴血亏虚"],"a":0,"e":"沉脉主里，迟脉主寒，沉迟相兼为里寒证，阳虚内寒、气血运行迟缓。肝郁气滞脉弦，水饮内停脉滑或弦，气滞血瘀脉涩，阴血亏虚脉细数或细弱，均非沉迟所主之里寒"},{"q":"只有通过问诊可知的症状是","o":["苔黄","耳鸣","水肿","汗出","面赤"],"a":1,"e":"耳鸣属自觉症状，他人无法察知，唯有通过问诊方可获知。苔黄可望诊得见，水肿、面赤望诊可见，汗出亦可望闻而知，唯耳鸣深藏耳内，非望闻切所能察，故须问诊"},{"q":"下列哪项是少阴病的主要脉症","o":["脉沉细，四肢厥","脉微细，但欲寐","脉弦细，面色赤","脉沉迟，但恶寒","脉细数，不得眠"],"a":1,"e":"少阴病为心肾阳虚、阴寒内盛，阳气衰微故脉微细，神疲欲寐故但欲寐，为少阴病提纲。脉沉细、四肢厥为少阴寒化重证，脉弦细面赤为阴虚阳亢，脉沉迟恶寒为里寒，脉细数不得眠为阴虚火旺"},{"q":"下列哪项对诊断肾虚水泛证最无意义","o":["心悸气短","小便清长","畏寒肢冷","腰膝酸冷","咳喘痰鸣"],"a":1,"e":"肾虚水泛证见畏寒肢冷、腰膝酸冷、心悸气短、咳喘痰鸣、小便短少、水肿，为肾阳虚、水气内停。小便清长是肾阳虚、肾气不固、津液不化之表现，与水泛之小便短少相反，对诊断肾虚水泛最无意义"},{"q":"动脉见于","o":["热证","痛、惊","阳盛实热","阳极阴竭","气滞血瘀"],"a":1,"e":"动脉脉形如豆、厥厥动摇、滑数有力，主痛、惊，因痛则气机阻滞、惊则气乱，脉见动摇。热证、阳盛实热多见数脉、洪脉，阳极阴竭见脉数疾无力，气滞血瘀见涩脉，均非动脉所主"},{"q":"缓脉的主病为","o":["水饮","痰证","湿证","食积","气滞"],"a":2,"e":"缓脉脉来和缓、一息四至，主湿证，湿性黏滞阻遏气机则脉缓。水饮内停脉弦滑，痰证脉滑，食积脉滑紧，气滞脉弦涩，皆非缓脉所主。缓脉亦可见于平人，但作为主病以湿证为要"},{"q":"下列选项中，均具有脉搏无力特点的脉象是","o":["散脉，弱脉，微脉","濡脉，结脉，浮脉","结脉，代脉，紧脉","沉脉，伏脉，革脉","牢脉，短脉，弦脉"],"a":0,"e":"散脉浮散无根、至数不齐，弱脉沉细而软，微脉极细极软、似有若无，三者皆脉搏无力。结脉、代脉主气血瘀阻或脏气衰微，紧脉绷急有力，浮脉主表，牢脉、弦脉皆非无力之脉"},{"q":"对诊断肾阳虚证最有意义的症状是","o":["形寒肢冷，面白神疲","滑精早泄，小便频数","精冷不育，腰膝酸软","下肢水肿，按之凹陷","大便稀溏，排便不爽"],"a":2,"e":"肾阳虚证以腰膝酸软、畏寒肢冷、性功能减退为核心，精冷不育、腰膝酸软直指肾阳不足、命门火衰。形寒肢冷、面白神疲虽属阳虚但非肾所独有，滑精早泄、小便频数多属肾气不固，下肢水肿为肾虚水泛，大便稀溏为脾肾阳虚"},{"q":"下列各项，不属脾病常见症状的是","o":["腹胀","嗳气","便溏","浮肿","便血"],"a":1,"e":"嗳气为胃气上逆、胃失和降，属胃病常见症状。脾主运化，脾病常见腹胀、便溏、浮肿、便血，皆与脾失健运或统摄无权相关。嗳气病位在胃，不属脾病常见症状"},{"q":"寒痰阻肺证最易见到的舌苔是","o":["薄白苔","白燥苔","积粉苔","白腻苔","白腐苔"],"a":3,"e":"寒痰阻肺证为寒邪与痰浊壅肺，苔白腻示寒湿痰浊内盛，为最易见之舌苔。薄白苔多正常或表证初起，白燥苔为津伤，积粉苔主瘟疫或内痈，白腐苔为湿浊上泛、胃气衰败，均非寒痰阻肺之苔"},{"q":"寒热转化的关键因素是","o":["邪气的性质","气候的冷热","脏腑的盛衰","阴液的盈亏","阳气的盛衰"],"a":4,"e":"寒热转化取决于机体阳气的盛衰：阳盛则热化，阳虚则寒化，同一病邪可随阳气状态而寒热互转。邪气性质影响病证性质但非转化关键，气候冷热为外因，脏腑盛衰、阴液盈亏虽相关，然阳气盛衰起决定作用"},{"q":"舌苔薄白不见于下列哪项","o":["正常人","外感初起","气血亏虚","痰浊内阻","里邪不甚"],"a":3,"e":"薄白苔见于正常人、外感初起邪未入里、里邪不甚及气血亏虚等，苔薄白示邪轻或胃气未伤。痰浊内阻、湿邪内停则苔腻、苔厚，非薄白所见，故痰浊内阻不见薄白苔"},{"q":"语言异常与下列何脏关系最密切","o":["心","肝","脾","肺","肾"],"a":0,"e":"心开窍于舌，语言为心神所主，心气充足则语言清晰，故语言异常与心关系最密切。肝主疏泄、脾主运化、肺主气司呼吸、肾藏精，虽可间接影响发音，但语言謇涩、谵语、错语等皆责之心神"},{"q":"下列除哪项外，均为膀胱湿热证的特征表现","o":["尿频","尿急","尿痛","遗尿","尿黄"],"a":3,"e":"膀胱湿热证见尿频、尿急、尿痛、尿黄、尿道灼热，为湿热下注膀胱、气化不利。遗尿为睡中不自主排尿，多因肾气不固、膀胱失约，与湿热之尿频尿急尿痛性质不同，故遗尿非膀胱湿热特征"},{"q":"细小如线，应指明显的脉象是","o":["虚脉","涩脉","细脉","微脉","濡脉"],"a":2,"e":"细脉脉细如线、应指明显、往来流利，为气血两虚或湿邪阻脉。虚脉三部举之无力、按之空虚，涩脉往来艰涩，微脉极细极软、似有若无，濡脉浮细而软，皆非细如线而应指明显之细脉"},{"q":"舌苔黏腻而厚，口中发甜，多因","o":["食积","脾虚湿困","痰浊内阻","脾胃湿热","胃气衰败"],"a":3,"e":"舌苔黏腻而厚、口中发甜为脾胃湿热，湿热蕴脾、上蒸于口，甘味属脾。食积见嗳腐吞酸、苔厚腻，脾虚湿困见口淡、苔白腻，痰浊内阻见口黏、苔腻，胃气衰败见苔腐或剥，均无口甜之湿热特征"},{"q":"发结如穗，枯黄无泽，伴见面黄肌瘦的小儿，多见于","o":["肾精亏损","气血亏虚","疳积病","血虚受风","先天遗传"],"a":2,"e":"发结如穗、枯黄无泽、面黄肌瘦为疳积病，脾胃受损、气血生化不足，毛发失养。肾精亏损见发枯早白、小儿五迟，气血亏虚见面白无华但无发结如穗，血虚受风见脱发，先天遗传非疳积之由"},{"q":"脉形超过本部，长而不急为","o":["弦脉","紧脉","长脉","革脉","牢脉"],"a":2,"e":"长脉脉形超过本部、长而不急、首尾端直，主阳气有余或平和。弦脉端直以长但紧张有力如按琴弦，紧脉绷急转索，革脉浮而搏指、中空外坚，牢脉沉实大弦长，皆非长而不急之长脉"},{"q":"邪实为主，正虚为次的是","o":["实证","虚证","虚证夹实","实证夹虚","虚实并重"],"a":3,"e":"实证夹虚指以邪实为主、正虚为次，邪盛正虚但实象居先。实证纯为邪实无虚，虚证纯为正虚，虚证夹实以正虚为主、邪实为次，虚实并重则二者均著，均非邪实为主、正虚为次之实证夹虚"},{"q":"气血两虚证的常见脉象","o":["弦脉","涩脉","浮脉","虚脉","紧脉"],"a":3,"e":"气血两虚证常见虚脉，虚脉三部举之无力、按之空虚，为气血不足、脉道不充。弦脉主肝胆病、痛、痰饮，涩脉主气滞血瘀，浮脉主表，紧脉主寒、痛、宿食，皆非气血两虚之脉"},{"q":"下列哪项不属于心血虚证的辨证要点","o":["心悸","失眠","多梦","血虚症状","烦躁"],"a":4,"e":"心血虚证辨证要点为心悸、失眠、多梦及血虚症状，因心血不足、心神失养。烦躁为热扰心神或阴虚火旺之象，非心血虚辨证要点，余项皆属心血虚核心表现"},{"q":"长期精神紧张，最容易出现的头发病变为","o":["白发","发黄干枯","斑秃","顶秃","发结如穗"],"a":2,"e":"长期精神紧张、情志内伤致肝气郁结、气血失和，毛发骤然成片脱落，形成斑秃，与精神因素关系最密。发黄干枯多气血亏虚，顶秃多与遗传、肾虚相关，发结如穗为疳积，白发多与肝肾、血热相关"},{"q":"舌上有糜点如饭粒，揩之即去，旋即复生，揩去处舌面光剥无苔，称为","o":["垢腻苔","黏腻苔","霉苔","脓腐苔","腐苔"],"a":2,"e":"霉苔为舌面糜点如饭粒、揩之即去、旋即复生、揩处光剥无苔，因湿热秽浊、气阴大伤。垢腻苔、黏腻苔为苔质厚腻，脓腐苔苔如脓腐、较厚，腐苔疏松如豆腐渣，均无糜点旋生、揩后光剥之特征"},{"q":"属风热表证发热特点的是","o":["发热重恶寒轻","恶寒重发热轻","发热轻而恶风","但寒不热","但热不寒"],"a":0,"e":"风热表证因风热阳邪、热重于风，故发热重、恶寒轻，伴咽痛、脉浮数。恶寒重发热轻为风寒表证，发热轻而恶风为伤风表证，但寒不热为里寒，但热不寒为里热，均与风热表证之热重寒轻不同"},{"q":"胃热者，呕吐物多表现为","o":["清稀无气味","腐臭而秽浊","气味酸腐","无酸腐气味","吐脓血腥臭"],"a":2,"e":"胃热者胃中热盛、腐熟太过，呕吐物多气味酸腐，伴口臭、牙龈肿痛。清稀无气味或吐清水为胃寒，腐臭而秽浊多属热毒内蕴、内痈成脓，无酸腐气味与胃热不符，吐脓血腥臭为肺痈、胃痈，均非胃热呕吐之常见表现"},{"q":"阴虚证临床表现有","o":["口淡不渴","两颧潮红","无汗或自汗","小便清长或尿少不利","大便稀薄"],"a":1,"e":"阴虚证因阴液亏少、虚火内扰，见两颧潮红、五心烦热、口燥咽干、舌红少苔、脉细数。口淡不渴、小便清长、大便稀薄为寒证，无汗或自汗分属表证与气虚，均非阴虚内热之象"},{"q":"下列何项是导致嗜睡的机理","o":["阳虚阴盛","阴虚阳盛","阳不入阴","心胆气虚","心脾两虚"],"a":0,"e":"嗜睡为神疲欲睡、叫醒复睡，因阳虚阴盛、阳气不足、阴寒内盛，神机失养。阴虚阳盛见失眠，阳不入阴见不寐，心胆气虚见惊悸失眠，心脾两虚见心悸健忘、失眠，均无嗜睡之机理"},{"q":"下列哪项不属“心脾两虚”的病理改变","o":["脾气亏虚，不能统血","生化不足，血液亏少","心阳气虚，血行不畅","心血不足，心神失养","脾失健运，营气不足"],"a":2,"e":"心脾两虚为心血不足、脾气虚弱：脾气亏虚则不能统血、生化不足、营气不足，心血不足则心神失养。心阳气虚、血行不畅属心阳虚、心脉痹阻之病理，与心脾两虚之气血亏虚不同，故不属其病理改变"},{"q":"沉按实大弦长，坚牢不移，为","o":["长脉","弦脉","伏脉","牢脉","紧脉"],"a":3,"e":"牢脉沉按实大弦长、坚牢不移、位深有力，主实寒、癥瘕积聚。长脉长而不急，弦脉端直以长但非沉实不移，伏脉推筋着骨始得、脉形隐伏，紧脉绷急转索，皆非沉按实大弦长之牢脉"},{"q":"脉“有神”主要是指","o":["不浮不沉，不大不小","柔和有力，节律一致","不快不慢，和缓有力","尺脉有力，沉取不绝","一息四至，闰以五至"],"a":1,"e":"脉之有神指柔和有力、节律一致，示心神充盈、气血调和。不浮不沉、不大不小为有胃气，不快不慢、和缓有力亦属胃气范畴，尺脉有力、沉取不绝为有根，一息四至、闰以五至言至数，均非有神之谓"},{"q":"严重呼吸困难患者，其唇色的变化为","o":["淡白","红润","青紫","青黑","淡紫"],"a":2,"e":"严重呼吸困难致缺氧、血脉瘀滞，口唇青紫，为血中缺氧之象。淡白为血虚，红润为正常，青黑为寒极、痛证或肾虚，淡紫介于淡白与青紫之间、程度较轻，均非严重呼吸困难之青紫"},{"q":"尿频、尿急、尿痛之症，属于","o":["尿失禁","淋证","癃闭","肾阳虚","肾阴虚"],"a":1,"e":"尿频、尿急、尿痛合称尿路刺激征，属淋证，因湿热下注膀胱、气化不利。尿失禁为尿液不自主流出，癃闭为排尿困难、尿量减少甚至无尿，肾阳虚、肾阴虚为虚证辨证，均非尿频尿急尿痛所主之淋证"},{"q":"亡阳证汗出的特点是","o":["冷汗淋漓","汗冷味咸","汗热而黏","汗出如油","汗出恶风"],"a":0,"e":"亡阳证因阳气暴脱、卫外不固、津液外泄，故冷汗淋漓、汗出如珠、四肢厥冷、脉微欲绝。汗热而黏、汗出如油为亡阴，汗冷味咸多属阳虚，汗出恶风为表虚卫弱，均非亡阳之冷汗淋漓"},{"q":"舌苔白厚腻而干，多见于","o":["秽浊湿邪与热毒相结","燥热伤津","痰饮内停","湿浊中阻，津气不化","外感寒湿"],"a":3,"e":"舌苔白厚腻而干为湿浊中阻、津气不化，湿浊内盛则苔白厚腻，气不化津则苔干。秽浊湿邪与热毒相结见苔白厚腻而燥或黄腻，燥热伤津见苔黄燥，痰饮内停见苔白滑，外感寒湿见苔薄白腻，均非此白厚腻而干之苔"},{"q":"下列何项不属排尿感异常","o":["小便涩痛","小便频数","尿后余沥","小便失禁","小便灼热"],"a":1,"e":"排尿感异常指排尿过程中的异常感觉与控制失常，包括小便涩痛、尿后余沥、小便失禁、小便灼热等。小便频数仅指排尿次数增多，属频次异常而非感觉异常，故不属排尿感异常"},{"q":"胃阴虚者常出现下列何症","o":["不饥少食","厌食油腻","消谷善饥","饥不欲食","突然食多"],"a":3,"e":"胃阴虚证因胃阴亏虚、虚热内生，胃有虚火则知饥，阴虚不纳则不想食，故饥不欲食。不饥少食为脾胃虚弱，厌食油腻属肝胆湿热，消谷善饥为胃热炽盛，突然食多可见于胃热或寄生虫，均非胃阴虚之饥不欲食"},{"q":"小便频数、量少、色赤而痛，伴腰痛，属于","o":["膀胱湿热","下焦虚寒","肾气不固","心火亢盛","肾阴不足"],"a":0,"e":"小便频数、量少、色赤而痛、伴腰痛为湿热下注膀胱、气化不利，属膀胱湿热证。下焦虚寒见小便清长、畏寒，肾气不固见尿频、遗尿、尿后余沥，心火亢盛见心烦、口舌生疮、小便短赤，肾阴不足见尿少、潮热，均非此湿热之证"},{"q":"消渴病的特点是","o":["尿急尿频尿痛","小便余沥不尽","多饮多食多尿","夜尿频多","小便失禁"],"a":2,"e":"消渴病以多饮、多食、多尿、形体消瘦为特征，因阴虚燥热、津液耗损。尿急尿频尿痛为淋证，小便余沥不尽为肾气不固，夜尿频多属肾阳虚或老年肾虚，小便失禁为肾气不固，均非消渴之三多"},{"q":"下列哪项非白色所主病证","o":["寒证","夺气","脾虚","虚证","脱血"],"a":2,"e":"白色主虚、寒、失血、夺气，见面色淡白或㿠白，如寒证、夺气、虚证、脱血。脾虚面色多黄，见面色萎黄或黄胖，非白色所主，故脾虚非白色主病"},{"q":"不属于正常舌质表现的是","o":["淡红鲜明","滋润光泽","活动自如","舌体柔软","舌体胖大"],"a":4,"e":"正常舌质为淡红鲜明、滋润光泽、舌体柔软、活动自如。舌体胖大属病理舌形，多因脾肾阳虚、水湿内停或湿热痰浊壅滞，舌体较正常增大，不属正常舌质表现"},{"q":"突发耳鸣，声大如潮，按之不减，伴有口苦、胁肋灼痛，属于","o":["阴虚火旺","肝胆火旺","肝肾阴虚","肾精亏损","肾气虚弱"],"a":1,"e":"突发耳鸣、声大如潮、按之不减为实证耳鸣，伴口苦、胁肋灼痛，因肝胆火旺、循经上扰清窍。阴虚火旺、肝肾阴虚、肾精亏损、肾气虚弱所致耳鸣多渐起、声细、按之减轻，属虚证，均非此肝胆火旺之突发重听"},{"q":"以抑郁不乐，胸胁少腹走窜疼痛，病情轻重与情绪变化关系密切为主要表现的证是","o":["肝阴虚证","肝风内动证","肝气郁结证","寒滞肝脉证","肝胆湿热证"],"a":2,"e":"抑郁不乐、胸胁少腹走窜疼痛、病情随情绪波动，为肝失疏泄、气机郁滞，属肝气郁结证。肝阴虚证见两目干涩、潮热，肝风内动见震颤抽搐，寒滞肝脉见少腹冷痛，肝胆湿热见口苦、苔黄腻，均非气郁之走窜痛"},{"q":"望色十法中，面色清明，多主阳证的是","o":["浮","清","散","微","泽"],"a":1,"e":"望色十法中，清浊辨阴阳，面色清明者多主阳证，浊暗者多主阴证。浮沉分表里，微甚分虚实，散抟分新久，泽夭分轻重善恶，清明之清专指色泽清朗，故主阳证者为清"},{"q":"气滞血瘀或伤精血少常见于以下哪一项脉象","o":["迟脉","细脉","涩脉","短脉","浮脉"],"a":2,"e":"涩脉往来艰涩、如轻刀刮竹，主气滞血瘀、伤精血少，因血脉不畅、精血亏少。迟脉主寒，细脉主气血虚、湿，短脉主气郁或气虚，浮脉主表，均非气滞血瘀或伤精血少之涩脉"},{"q":"对诊断肾阳虚证最无意义的是","o":["经少崩漏","五更泄泻","形寒肢冷","早泄精冷","性欲减退"],"a":0,"e":"肾阳虚证见形寒肢冷、五更泄泻、早泄精冷、性欲减退，皆命门火衰、温煦失职。经少崩漏多属肾精不足、冲任亏虚或血热、脾不统血，非肾阳虚之典型表现，对诊断肾阳虚最无意义"},{"q":"在《灵枢•五色》中，青为","o":["心","肝","脾","肺","肾"],"a":1,"e":"《灵枢·五色》以五色配五脏，青为肝，赤为心，黄为脾，白为肺，黑为肾。青色主肝病、寒、痛、气滞、血瘀，故青归属于肝，余色各配其脏"},{"q":"以干咳无痰、或痰少而黏为主要表现的证是","o":["肺气虚证","风热犯肺证","肺阴虚证","痰热壅肺证","肺热炽盛证"],"a":2,"e":"干咳无痰、痰少而黏为肺阴虚证，肺阴亏虚、虚热内扰、肺失濡润、气机上逆。肺气虚证见咳喘无力、痰清稀，风热犯肺见咳嗽痰黄、发热，痰热壅肺见痰多黄稠，肺热炽盛见咳喘气粗、痰黄，均非干咳少痰之肺阴虚"},{"q":"判断病情的轻重和预后，更重要的是皮肤的","o":["色","泽","形","态","润"],"a":1,"e":"望皮肤以色泽为先，泽指皮肤润泽光明，泽之有无直接反映脏腑精气盛衰，故判断病情轻重与预后以泽为要。色言颜色，形、态言形态，润与泽相近，但泽更能示精气之存亡与预后吉凶"},{"q":"暴病见下列何项，属脉症不相应","o":["浮脉","沉脉","洪脉","数脉","实脉"],"a":1,"e":"暴病新病、邪盛正实，脉当浮、数、洪、实与证相符，见沉脉则脉症不相应，主邪气内陷或阳气被遏。浮脉、洪脉、数脉、实脉皆与暴病邪盛之实证相应，不属脉症不相应"},{"q":"热证通常不见","o":["数脉","滑脉","洪脉","促脉","结脉"],"a":4,"e":"热证见数脉、滑脉、洪脉、促脉，皆因热盛血行加速或热结。结脉为缓而时止、止无定数，主阴盛气结、寒痰血瘀，属寒证、实证，非热证所见，故热证通常不见结脉"},{"q":"湿浊上泛而胃气衰败，多见哪种舌象","o":["苔薄白而干","苔厚白而滑","苔厚白而干","苔白如积粉","苔白而腐"],"a":4,"e":"湿浊上泛、胃气衰败见苔白而腐，苔质疏松如豆腐渣、白而厚，为胃气衰微、湿浊腐败上泛。苔薄白而干为津伤，苔厚白而滑为湿盛，苔厚白而干为湿盛津伤，苔白如积粉主瘟疫或内痈，均非胃气衰败之腐苔"},{"q":"以胁下肿块，或妇女乳房胀痛，月经不调，痛经；舌苔薄白，脉弦为主要表现的证是","o":["肝阴虚证","肝风内动证","肝郁气滞证","寒滞肝脉证","肝胆湿热证"],"a":2,"e":"胁下肿块、乳房胀痛、月经不调、痛经、苔薄白、脉弦为肝失疏泄、气机郁滞，气血瘀阻冲任，属肝郁气滞证。肝阴虚证见潮热、两目干涩，肝风内动见抽搐，寒滞肝脉见少腹冷痛，肝胆湿热见苔黄腻，均非气滞之胀痛脉弦"},{"q":"下列选项中，不属于个人生活史内容的是","o":["平素健康状况","生活经历","精神情志","饮食嗜好","婚姻产育"],"a":0,"e":"个人生活史包括生活经历、精神情志、饮食嗜好、婚姻产育等，反映个人生活习惯与经历。平素健康状况属既往史内容，记述既往身体健康与患病情况，不属个人生活史"},{"q":"下列各项，属于胃气虚证与脾气虚证的鉴别要点的是","o":["面色萎黄","少气懒言","神疲肢倦","大便稀溏","舌淡脉弱"],"a":3,"e":"胃气虚证与脾气虚证均见少气懒言、神疲肢倦、面色萎黄、舌淡脉弱，为气虚共性。大便稀溏是脾气虚、运化失司之特征，胃气虚以胃脘痞闷、纳差、嗳气为主，无便溏，故大便稀溏为二者鉴别要点"},{"q":"牙龈红肿疼痛，多为","o":["胃火亢盛","心脾积热","血络瘀阻","阴虚火旺","燥热伤津"],"a":0,"e":"牙龈红肿疼痛为胃火亢盛，胃经循龈、火热上灼。心脾积热多见口舌生疮，血络瘀阻见齿龈紫暗、刺痛固定，阴虚火旺见牙龈隐隐作痛、颧红，燥热伤津见牙龈干痛、口燥，均非胃火之红肿疼痛"},{"q":"若见眉间、鼻柱、唇周色青者，多属于","o":["虚寒证","实寒证、剧痛","肝病迁延日久","惊风或惊风先兆","脾虚湿盛"],"a":3,"e":"眉间、鼻柱、唇周色青为小儿惊风或惊风先兆，肝风内动、筋脉拘急、气血凝滞。虚寒证、实寒证剧痛见面色青白，肝病迁延日久见面色青暗，脾虚湿盛见面黄而垢，均非小儿眉间鼻柱唇周青之惊风特征"},{"q":"久病见何脉为逆","o":["沉脉","细脉","浮脉","微脉","伏脉"],"a":2,"e":"久病正气亏虚，脉宜沉细虚弱，与病相符。若久病反见浮脉，浮主表、主虚阳外越，为正气衰微、虚阳浮越，脉症不相应，故为逆证。沉脉、细脉、微脉皆与久病正虚相应，不为逆"},{"q":"胃气虚证与胃阳虚证的鉴别要点是","o":["有无嗳气呃逆","有无食少纳差","有无乏力倦怠","有无胃脘冷痛","有无消谷善饥"],"a":3,"e":"胃气虚证与胃阳虚证均见食少纳差、乏力倦怠、嗳气呃逆。胃阳虚证因阳气不足、胃寒内盛，见胃脘冷痛、喜温喜按，胃气虚证无冷痛。有无胃脘冷痛是二者鉴别要点，消谷善饥属胃热，非二者所有"},{"q":"下列哪项对诊断脾肺气虚证最无意义","o":["食少腹胀","面白神疲","面浮肢肿","咳喘短气","痰黏难咯"],"a":4,"e":"脾肺气虚证见食少腹胀、面白神疲、面浮肢肿、咳喘短气，为肺脾气虚、水液不化。痰黏难咯为阴虚肺燥或燥邪伤肺，津液不足、痰黏难出，与脾肺气虚之痰清稀易咯相反，对诊断最无意义"},{"q":"舌体软弱无力，不能随意伸缩回旋者，称为","o":["短缩舌","痿软舌","吐弄舌","强硬舌","颤动舌"],"a":1,"e":"痿软舌为舌体软弱无力、不能随意伸缩回旋，因气血亏虚、阴液亏损、舌体失养。短缩舌为舌体紧缩不伸，吐弄舌为舌伸出口外或舐口唇，强硬舌板硬不灵，颤动舌不自主抖动，皆非痿软无力之态"},{"q":"下列属于望苔质的是","o":["青紫","裂纹","老嫩","剥落","点刺"],"a":3,"e":"望苔质包括厚薄、润燥、腐腻、剥落、偏全、真假等，剥落属苔质变化。青紫属舌色，裂纹、点刺属舌形，老嫩属舌质，均非苔质范畴，故剥落为望苔质内容"},{"q":"均主饮食积滞的脉象是","o":["散脉，弱脉，代脉","滑脉，紧脉，促脉","结脉，代脉，促脉","沉脉，伏脉，革脉","牢脉，短脉，弦脉"],"a":1,"e":"滑脉主痰食，紧脉主宿食，促脉主食积、热结，三者均可因饮食积滞、气机壅塞而见。散脉、弱脉、代脉主虚衰，结脉主寒凝血瘀，沉脉、伏脉、革脉、牢脉、短脉、弦脉各主里、闭、寒、痛，非饮食积滞之脉"},{"q":"语言错乱，语后自知言错者称为","o":["错语","独语","谵语","呓语","郑声"],"a":0,"e":"错语为语言错乱、语后自知言错，因心气不足、神志失养或痰浊蒙心。独语为自言自语、喃喃不休、见人便止，谵语为神昏胡言，呓语为睡中梦话，郑声为神昏时语言重复、声音低弱，均非错语之语后自知"},{"q":"对失眠诊断为心肾不交证最有意义的依据是","o":["心烦多梦，颧红盗汗","心悸怔忡，肢肿尿少","心烦健忘，脉象细数","心烦遗精，腰酸潮热","心烦而悸，舌红少苔"],"a":3,"e":"心肾不交证为心火亢于上、肾阴亏于下，心烦失眠、遗精、腰酸潮热兼具心火与肾阴虚，最具诊断意义。心悸怔忡、肢肿尿少为水气凌心，心烦健忘、脉细数仅示阴虚，眩晕耳鸣、腰膝酸软为肾虚，均不及心肾同病之依据明确"},{"q":"属风寒表证发热特点的是","o":["恶寒发热俱轻","恶寒发热俱重","恶寒发热交替","发热重恶寒轻","恶寒重发热轻"],"a":4,"e":"风寒表证因风寒阴邪、寒重于风，卫阳被遏，故恶寒重、发热轻，伴无汗、脉浮紧。恶寒发热俱轻邪轻，俱重邪盛，交替为半表半里，发热重恶寒轻为风热表证，均非风寒表证之寒重热轻"},{"q":"舌红而肿胀满口，伴有齿痕者，为","o":["寒湿壅盛","脾虚","湿热痰浊壅滞","气虚","阳虚水湿内停"],"a":2,"e":"舌红而肿胀满口、伴齿痕为湿热痰浊壅滞，湿热上泛则舌红肿胀，痰浊内盛则现齿痕。寒湿壅盛、阳虚水湿内停多见舌淡胖大，脾虚、气虚见舌淡胖嫩有齿痕，均非舌红肿胀满口之湿热痰浊"},{"q":"大便夹有不消化的食物，酸腐臭秽者，多因","o":["大肠湿热","寒湿内盛","伤食积滞","脾胃虚弱","肝胃不和"],"a":2,"e":"大便夹不消化食物、酸腐臭秽为伤食积滞，食积胃肠、腐熟失常、浊气下注。大肠湿热见便溏黄糜、里急后重，寒湿内盛见便溏清稀，脾胃虚弱见便溏夹完谷不化但无酸腐，肝胃不和见便溏与情志相关，均无酸腐臭秽"},{"q":"结脉的脉象是","o":["数而时一止，止无定数","缓而时一止，止有定数","缓而时一止，止无定数","时止有定数，良久方来","数而时一止，止有定数"],"a":2,"e":"结脉为脉来缓慢、时见一止、止无定数，主阴盛气结、寒痰血瘀。数而时一止、止无定数为促脉，止有定数、良久方还为代脉，数而时一止、止有定数亦非结脉，缓而时一止、止有定数亦非结脉之缓中止无定数"},{"q":"下列何项可致小儿生长发育迟缓","o":["肾阴不足证","肾精不足证","肾阳虚证","脾肾亏虚证","肾气不足证"],"a":1,"e":"肾精不足证因先天禀赋不足或后天耗损，精血亏虚，小儿见生长发育迟缓、囟门迟闭、智力低下、身材矮小。肾阴不足见潮热、五心烦热，肾阳虚见畏寒肢冷，脾肾亏虚见便溏、水肿，肾气不足见遗尿、尿频，均非发育迟缓之主因"},{"q":"两经或三经证候同时出现的是","o":["循经传","直中","合病","表里传","并病"],"a":2,"e":"合病为两经或三经证候同时出现，如太阳阳明合病。循经传为按经络次序传变，直中为病邪直入三阴，表里传为表里经相传，并病为一经证候未罢又见另一经证候，先后出现，均非同时并见之合病"},{"q":"脾气虚证与寒湿困脾证鉴别的要点症状是","o":["食欲不振","口淡不渴","便溏腹胀","苔白厚腻","脉缓"],"a":3,"e":"寒湿困脾证为寒湿内盛、困遏脾运，见苔白厚腻、口淡不渴、脘腹胀满。脾气虚证见食欲不振、便溏腹胀、舌淡苔白，无厚腻之苔。苔白厚腻示湿浊内盛，是脾气虚与寒湿困脾鉴别之要点症状"},{"q":"大肠湿热证泻下的特点是","o":["里急后重","泻下酸腐","溏结不调","五更泄泻","大便腥臭"],"a":0,"e":"大肠湿热证湿热下注大肠、气机阻滞，泻下见里急后重、便黄稠或脓血、肛门灼热。泻下酸腐为伤食积滞，溏结不调为肝郁脾虚，五更泄泻为脾肾阳虚，大便腥臭可见寒湿或湿热，均非大肠湿热之里急后重特征"},{"q":"根据点刺所在部位推测邪热所在脏腑，如舌边有点刺，多为","o":["心火亢盛","胃肠热盛","肝胆火盛","气血壅滞","肺热炽盛"],"a":2,"e":"点刺主热盛，舌边属肝胆，舌边有点刺为肝胆火盛，因肝胆火热上炎。舌尖点刺为心火亢盛，舌中点刺为胃肠热盛，舌根点刺为下焦热，气血壅滞见瘀点瘀斑，肺热炽盛多见舌尖红赤，均非舌边肝胆火盛"},{"q":"水逆证的呕吐特点是","o":["饮后即吐","吐利并作","朝食暮吐","吐物酸腐","呕吐如喷"],"a":0,"e":"水逆证为水饮内停、胃气上逆，渴欲饮水、水入即吐，故呕吐特点为饮后即吐。吐利并作为霍乱，朝食暮吐为反胃，吐物酸腐为食积，呕吐如喷为胃热或肝气犯胃，均非水逆之水入即吐"},{"q":"两颧潮红多属于","o":["肝火盛","心火盛","阳明热盛","阴虚内热","气虚发热"],"a":3,"e":"两颧潮红为阴虚内热、虚火上炎，午后或入夜加重，伴五心烦热、盗汗、舌红少苔。肝火盛、心火盛、阳明热盛多见满面通红，气虚发热见面白、发热而颧不红，均非两颧潮红之阴虚内热"},{"q":"腰脊疼痛连及下肢者，多属","o":["风湿痹病","肾气亏虚","痰湿内阻","经络阻滞","带脉损伤"],"a":3,"e":"腰脊疼痛连及下肢为经络阻滞、气血不通，痹阻腰府及下肢经络，痛处固定、活动受限。风湿痹病以关节游走疼痛为主，肾气亏虚见腰膝酸软、隐痛，痰湿内阻见腰部重痛，带脉损伤见腰部坠胀、带下异常，均非经络阻滞之下肢放射痛"},{"q":"大便灰白呈陶土色，多见于","o":["湿热或暑湿伤及胃肠","黄疸","热盛伤津","外感寒湿","饮食生冷"],"a":1,"e":"大便灰白呈陶土色为黄疸，尤其阻塞性黄疸，胆汁不能下注肠道，故大便色白。湿热或暑湿伤及胃肠见便溏黄糜、黏腻不爽，热盛伤津见大便干结，外感寒湿、饮食生冷见便溏清稀，均非陶土色便"},{"q":"下列各项，属于湿热蕴脾证与寒湿困脾证共有的表现是","o":["面黄晦暗","便溏不爽","面黄鲜明","身热不扬","口苦口黏"],"a":1,"e":"湿热蕴脾证与寒湿困脾证均属湿邪困脾、运化失司，故共有便溏不爽。面黄晦暗为寒湿困脾，面黄鲜明为湿热蕴脾，身热不扬、口苦口黏为湿热蕴脾，寒热属性不同，便溏不爽是二者共有之脾失健运表现"},{"q":"病室散发烂苹果味，多属","o":["脏腑败坏","水肿晚期","消渴病晚期","瘟疫病","失血症"],"a":2,"e":"病室散发烂苹果味为消渴病晚期，阴虚燥热、气阴两伤、酮体生成，呼气及病室有烂苹果样气味。脏腑败坏见尸臭或腐臭，水肿晚期见尿臊味，瘟疫病见霉秽气，失血症见血腥气，均非消渴之烂苹果味"},{"q":"代脉的主病是","o":["元气离散","气血两虚","诸虚劳损","失精亡血","脏气衰微"],"a":4,"e":"代脉为脉来时止、止有定数、良久方还，主脏气衰微、元气不足、心脉受损。元气离散见脉散乱无根，气血两虚见虚脉，诸虚劳损见虚弱之脉，失精亡血见涩脉或芤脉，均非代脉所主之脏气衰微"},{"q":"与气虚兼并的虚证，哪项少见","o":["气虚髓亏","津气亏虚","气阴两虚","气血两虚","阳气亏虚"],"a":0,"e":"气虚常与阴、阳、血、津液相兼，见气阴两虚、阳气亏虚、气血两虚、津气亏虚，临床常见。气虚髓亏指气虚兼骨髓亏虚，髓亏多责之肾精不足，非气虚常见之兼夹，故与气虚兼并的虚证中少见"},{"q":"颤动舌的临床意义为","o":["中风先兆","心脾有热","肝风内动","热入心包","风痰阻络"],"a":2,"e":"颤动舌为舌体不自主颤动，因肝风内动、筋脉失养，或热盛、阴虚动风。中风先兆见口舌歪斜、言语謇涩，心脾有热见舌红生疮，热入心包见舌绛神昏，风痰阻络见舌强不灵，均非颤动舌之肝风内动"},{"q":"肛门气坠，常于劳累或排便后加重，多属","o":["湿热下注","肝气郁结","脾虚气陷","寒滞肝脉","大肠湿热"],"a":2,"e":"肛门气坠、劳累或排便后加重为脾虚气陷，脾虚升提无力、中气下陷。湿热下注见肛门灼热、便黏，肝气郁结见胸胁胀痛，寒滞肝脉见少腹冷痛，大肠湿热见里急后重、便脓血，均非脾虚气陷之肛门坠胀"},{"q":"咳声轻清低微证属","o":["风寒束表","风热犯肺","肺气亏损","肺阴不足","燥邪犯肺"],"a":2,"e":"咳声轻清低微为肺气亏损，肺气不足、宣降无力，咳嗽声音低微无力。风寒束表见咳声重、鼻塞，风热犯肺见咳声洪亮、痰黄，肺阴不足见干咳少痰，燥邪犯肺见干咳无痰、口鼻干燥，均非肺气亏损之咳声低微"},{"q":"本已极度衰竭，突然出现神气暂时“好转”的是","o":["得神","少神","失神","假神","神乱"],"a":3,"e":"假神为久病、重病极度衰竭时突然出现神气暂时好转，如言语增多、面色转红、欲食，是精气衰竭、虚阳外越之危象，俗称回光返照。得神为正常，少神为轻度不足，失神为精气大伤、神志昏迷，神乱为癫狂痫等神志错乱，均非假神"},{"q":"芤脉的脉象特征是","o":["轻按搏指，中空外坚","浮大而软，按之中空","脉位表浅，细软无力","三部脉举之无力，按之空虚","沉细无力"],"a":1,"e":"芤脉浮大而软、按之中空、如按葱管，主失血、伤阴，营血亏虚、脉道空虚。轻按搏指、中空外坚为革脉，脉位表浅、细软无力为濡脉，三部举之无力、按之空虚为虚脉，沉细无力为弱脉，均非芤脉之浮大中空"},{"q":"具有神昏谵语，躁扰不宁，或壮热神昏，呼吸气粗，喉中痰鸣等临床表现的属于","o":["神乱","少神","得神","假神","失神"],"a":4,"e":"神昏谵语、躁扰不宁、壮热神昏、呼吸气粗、喉中痰鸣为邪热内陷心包、热盛神昏，属失神之实证表现。神乱为癫狂痫、焦虑恐惧，少神为神气不足，得神为正常，假神为危重时暂时好转，均非此热盛神昏之失神"},{"q":"下列哪项对诊断心肾不交证最有意义","o":["心悸失眠，头晕目眩","心悸怔忡，肢肿尿少","心烦失眠，腰酸盗汗","嗜睡神疲，心悸肢肿","眩晕耳鸣，腰膝酸软"],"a":2,"e":"心肾不交证为心火亢于上、肾阴亏于下，心烦失眠、腰酸盗汗兼具心火扰动与肾阴虚，最具诊断意义。心悸失眠、头晕目眩为心血虚，心悸怔忡、肢肿尿少为水气凌心，嗜睡神疲、心悸肢肿为阳虚水泛，眩晕耳鸣、腰膝酸软为肾虚，均不及心肾同病之依据"},{"q":"外邪最易侵袭何经","o":["厥阴经","太阳经","阳明经","太阴经","少阳经"],"a":1,"e":"太阳经为六经之首、主一身之表，外邪自皮毛而入，先犯太阳，故外邪最易侵袭太阳经，见恶寒、发热、头项强痛、脉浮。厥阴、阳明、太阴、少阳各有传变次序与定位，非外邪初袭之首选"},{"q":"下列各项，不属胃气虚证的临床表现的是","o":["胃脘冷痛喜温","胃脘痞闷","恶心呕逆","食后脘胀更甚","舌淡苔白脉弱"],"a":0,"e":"胃气虚证见胃脘痞闷、恶心呕逆、食后脘胀更甚、舌淡苔白脉弱，为胃气不足、和降失司。胃脘冷痛喜温为胃阳虚、寒邪内盛之象，胃气虚证无冷痛喜温，故不属胃气虚证临床表现"},{"q":"下列哪项可视作血寒证","o":["寒凝肠胃证","寒凝胞宫证","寒邪束表证","寒邪客肺证","寒凝关节证"],"a":1,"e":"血寒证为寒邪客于血脉、血行不畅，以手足冷痛、肤色紫暗、月经后期、经色紫暗有块、小腹冷痛为特征，寒凝胞宫证是其典型。寒凝肠胃、寒邪束表、寒邪客肺、寒凝关节虽属寒证，但病在腑、表、肺、关节，非血脉之血寒证"},{"q":"热证的辨证要点有","o":["畏寒","口淡不渴","小便清长","面赤心烦","恶心呕吐"],"a":3,"e":"热证因热邪亢盛、气血上涌，见面赤心烦、口渴喜冷、小便短赤、大便干结、舌红苔黄、脉数。畏寒、口淡不渴、小便清长为寒证表现，恶心呕吐非热证辨证要点，故面赤心烦为热证辨证要点"},{"q":"老人头摇不能自主，最常见的原因是","o":["肝阳上亢","气血两虚","肾精亏损","高热伤津","阴虚火旺"],"a":1,"e":"头摇即头部不自主摇动，老人气血亏虚，气虚推动无力、血虚头部失养，筋脉失养而颤动，故以气血两虚最为常见。肝阳上亢多见头胀眩晕、面红目赤，非老人头摇常见因；肾精亏损常致耳鸣齿摇、健忘；高热伤津多伴抽搐、属急症；阴虚火旺以潮热盗汗、五心烦热为主，均非老人头摇主因"},{"q":"下列除哪项外脉率均较快","o":["促脉","结脉","疾脉","动脉","数脉"],"a":1,"e":"结脉为脉来缓慢而时有一止、止无定数，脉率偏慢，故本题除外结脉。促脉数而一止、止无定数，疾脉一息七八至、脉率极快，动脉数而厥厥动摇，数脉一息五六至，四者脉率均快。结脉与代脉、促脉同属止脉，但结脉迟而促脉数，快慢之别正是辨析要点"},{"q":"呕吐物清稀无臭，或清水者，多因","o":["胃阳不足","寒邪犯胃","食积内停","胃阳不足或寒邪犯胃","胃有积热"],"a":3,"e":"呕吐物清稀无臭、或为清水，是胃中无热、寒饮内停之象，胃阳不足则腐熟无权、寒邪犯胃则胃气上逆，故多因胃阳不足或寒邪犯胃。单纯胃阳不足或寒邪犯胃均只言其一，不够全面；食积内停吐物酸腐夹不消化食物；胃有积热则吐物酸臭或黄稠，均与清稀无臭相悖"},{"q":"对诊断肾精不足证最无意义的是","o":["经闭不孕","耳鸣耳聋","齿摇发脱","烦热盗汗","健忘恍惚"],"a":3,"e":"肾精不足以生长发育迟缓、生殖功能减退、早衰及髓海失养为核心，经闭不孕、耳鸣耳聋、齿摇发脱、健忘恍惚皆由其所致。烦热盗汗是阴虚内热、虚火扰营的表现，属肾阴虚而非肾精不足，对诊断肾精不足最无意义。肾精与肾阴虽同源，但精亏重在形质与生殖，阴虚重在热象，两者不可混同"},{"q":"下列哪个病证不属于痰火扰神证临床表现","o":["失眠","心烦","癫","神昏谵语","狂"],"a":2,"e":"痰火扰神证以痰火互结、上扰心神为特征，轻则失眠心烦、神志狂乱，重则神昏谵语、狂躁妄动，癫证则属痰蒙心神，以沉默痴呆、语无伦次、静而多喜为特征，与痰火扰神的狂躁相反，故不属于本证。失眠、心烦为火扰心神之轻者，神昏谵语为痰火闭窍之重者，狂为痰火扰神之典型，均属本证表现"},{"q":"下列选项中，均具有脉位表浅特点的脉象是","o":["浮脉，洪脉，革脉，濡脉","弱脉，长脉，弦脉，虚脉","浮脉，散脉，弦脉，弱脉","弱脉，革脉，伏脉，芤脉","牢脉，弱脉，浮脉，短脉"],"a":0,"e":"脉位表浅指轻取即得、重按反弱，浮脉轻取即得，洪脉浮大有力，革脉浮而搏指、中空外坚，濡脉浮而细软，四者均居浮位。弱脉沉而细软、牢脉沉实、伏脉深伏，B项含弱脉、长脉、弦脉、虚脉，C项含弦脉弱脉，D项含弱脉伏脉，E项含牢脉弱脉，皆因混入沉位脉而不符"},{"q":"小儿食指络脉色紫红主病","o":["表热","内热","血瘀证","惊风证","气血亏虚"],"a":1,"e":"小儿食指络脉色泽可辨病性，色紫红是里热炽盛、血脉壅滞之象，故主内热。色鲜红多主外感表热，邪在肌表；色青主惊风或疼痛，肝风筋脉拘急；色紫黑或青紫主血瘀；色淡白主气血亏虚，络脉失充。鲜红与紫红仅一色之差，却分表里，是本题最易混淆处"},{"q":"腹部按之肌肤凉而喜温者，为","o":["寒证","热证","虚证","实证","饮证"],"a":0,"e":"腹部肌肤触之凉、喜温熨，是寒邪或阳气不足、腹部失于温煦之象，故为寒证。热证按之灼热、喜凉；虚证虽喜按但未必喜温凉明显；实证拒按、按之痛甚；饮证以脘腹漉漉有声、按之痛为主，均不以凉而喜温为特征。寒热之别重在喜温喜凉与触诊凉热，喜温是寒证的确据"},{"q":"下列除哪项外，均为头晕的常见原因","o":["气血两虚","痰湿内阻","肺阴不足","肝阳上亢","肝火上炎"],"a":2,"e":"头晕多由清窍失养或被邪扰，气血两虚则清阳不升，痰湿内阻则蒙蔽清阳，肝阳上亢、肝火上炎皆循经上扰头目，均为常见原因。肺阴不足以干咳少痰、咽干口燥、潮热盗汗为主，病位在肺，不直接上犯清窍，故不属头晕常见原因。肝阳上亢与肝火上炎虽均上扰，一为阴虚阳亢、一为实火，仍不失为头晕要因"},{"q":"弱脉的脉象是","o":["脉细如线","沉而细软","极细极软","浮而细软","脉微欲绝"],"a":1,"e":"弱脉为沉而细软、应指无力，须重按方得，主气血不足、阳气虚衰。脉细如线是细脉，主气血两虚、湿邪；极细极软、若有若无是微脉，主阳气衰微；浮而细软是濡脉，主虚证湿邪；脉微欲绝为危候，较微脉更弱。弱与濡均细软，但弱沉濡浮，是二者鉴别关键"},{"q":"呕吐物酸腐夹杂不消化食物，多属","o":["痰饮","寒呕","胃痈","热呕","食积"],"a":4,"e":"呕吐物酸腐、夹带不消化食物，是宿食停滞胃脘、腐熟不及、胃气上逆所致，故属食积。痰饮呕吐多为清水痰涎；寒呕吐物清稀无臭、喜温；热呕吐物酸臭或黄稠、伴口渴；胃痈以呕吐脓血、胸痛为主，均与酸腐夹食不符。酸腐与不消化食物是食积的确据，区别于寒呕之清稀无臭"},{"q":"沉而细软，应指无力是","o":["濡脉","微脉","细脉","弱脉","涩脉"],"a":3,"e":"沉而细软、应指无力，重按始得者为弱脉，主气血两虚、阳虚。濡脉浮而细软，位在表；微脉极细极软、似有似无，主阳衰；细脉脉细如线但应指有力、位不专沉；涩脉往来艰涩、如轻刀刮竹，主气滞血瘀。弱脉与濡脉皆细软，鉴别全在脉位沉浮，此处沉而细软故为弱脉"},{"q":"水肿以眼睑头面浮肿，上半身肿甚为特点者属于","o":["心阳不足证","风水搏肺证","脾虚失运证","肾虚水泛证","脾肾阳虚证"],"a":1,"e":"风水搏肺证因风邪袭肺、通调失司、水液泛溢肌肤，起病急骤，以眼睑头面先肿、上半身肿甚，兼恶寒发热、脉浮为特点。心阳不足证水肿以全身或下肢肿、心悸畏寒为主；脾虚失运证肿以四肢、腹部为主，起病缓；肾虚水泛证腰以下肿甚；脾肾阳虚证全身水肿、腰以下尤甚，均与风水上肿特征不符"},{"q":"脉在皮肤，浮数之极，至数不清，浮泛无根，称为","o":["鱼翔脉","虾游脉","釜沸脉","屋漏脉","弹石脉"],"a":2,"e":"釜沸脉浮在皮肤、浮数之极、至数不清、浮泛无根，如釜中沸水，为三阳热极、阴液将竭的死脉。鱼翔脉在皮肤、头定尾摇似有似无；虾游脉在皮肤、时而跃然而去须臾又来；屋漏脉良久一滴、如屋漏残滴；弹石脉在筋骨间、如指弹石，均与浮数无根的釜沸之象不同"},{"q":"肺气虚证的咳喘特点最主要的是","o":["咳喘胸闷，喉中痰鸣","咳喘痰多，色白稀薄","咳喘无力，声低息微","咳喘痰少，不易咳吐","咳嗽痰多，色黄质稠"],"a":2,"e":"肺气虚证因肺气不足、宣降无权，故咳喘无力、声低息微、气短懒言，动则尤甚。咳喘胸闷、喉中痰鸣是痰饮阻肺；咳喘痰多色白稀薄是寒痰或痰湿；痰少不易咳吐是阴虚肺燥或燥痰；痰多色黄质稠是痰热壅肺，皆非气虚无力之本。咳喘无力、声低息微正是肺气亏虚、推动无力的直接体现"},{"q":"循衣摸床属于","o":["得神","少神","失神","假神","神乱"],"a":2,"e":"循衣摸床是病人在神志昏迷中两手无意识地抚摸衣被、床沿，为邪热内陷、元气将脱之危象，属失神。得神目光明亮、神志清楚；少神为精神不振、动作迟缓但未见无意识动作；假神是久病危重者突然精神转佳、颧红如妆的回光返照；神乱指癫狂痫等神志错乱，均不同于循衣摸床的失神表现"},{"q":"釜沸脉的主病是","o":["孤阳无依，躁动不安","三阴寒极，阳亡于外","三阳热极，阴液枯竭","肾与命门之气皆亡","胃气营卫将绝"],"a":2,"e":"釜沸脉浮泛无根、浮数之极，主三阳热极、阴液枯竭，为阳热亢盛至极、阴液将尽的死脉。孤阳无依、躁动不安多见于虾游、鱼翔等脉；三阴寒极、阳亡于外是解索、屋漏等脉主病；肾与命门之气皆亡多见弹石脉；胃气营卫将绝是诸脉胃气已绝的统称，均非釜沸脉所主"},{"q":"热证的形成原因不包括","o":["外感热邪","体内阳盛","阴液亏虚","阳气不足","寒湿郁久"],"a":3,"e":"热证由热邪所致或机体功能亢进、阴液亏虚而生，外感热邪、体内阳盛、阴液亏虚、寒湿郁久化热均可形成。阳气不足则温煦推动无力、寒从中生，是虚寒证的成因，与热证相反，故不包括。阳盛与阴虚虽均致热，一为实热、一为虚热，仍属热证范畴，唯阳气不足专主寒"},{"q":"自汗与盗汗并见的常见原因是","o":["血液亏虚","阳气不足","阴液亏虚","气阴两虚","阴血亏虚"],"a":3,"e":"自汗多发于白天、动则汗出，为气虚卫外不固；盗汗睡后汗出、醒后即止，为阴虚内热逼津外泄，两者并见多是气阴两虚。单纯血液亏虚、阴血亏虚以盗汗或头晕心悸为主，不兼自汗；阳气不足仅自汗；阴液亏虚仅盗汗，皆不能同时解释自汗与盗汗，唯气阴两虚气虚阴虚并具，故最常见"},{"q":"滑脉的脉象特征是","o":["来盛去衰","厥厥动摇","浮大中空","往来流利","如轻刀刮竹"],"a":3,"e":"滑脉往来流利、应指圆滑、如珠走盘，主痰湿、食积、实热及妊娠。来盛去衰是洪脉，主热盛；厥厥动摇是动脉，主痛惊；浮大中空是芤脉，主失血伤阴；如轻刀刮竹是涩脉，主气滞血瘀、精伤血少。涩与滑脉象相反，一滞一利，鉴别最为鲜明，滑脉以流利圆滑为特征"},{"q":"真热假寒与真寒假热证均可见","o":["口渴喜饮","小便清长","下利臭秽","面色浮红如妆","四肢厥冷"],"a":4,"e":"四肢厥冷在真热假寒与真寒假热中均可出现：真热假寒因里热炽盛、阳气郁闭不能外达，热深厥亦深；真寒假热因里寒极盛、阳气虚衰不达四末。口渴喜饮、下利臭秽是真热；小便清长、面色浮红如妆是真寒假热的假象，均只见于一端，唯四肢厥冷为二者共有，须结合胸腹、舌脉辨其真伪"},{"q":"阳气暴脱者多见","o":["面色淡白","面色㿠白","面白虚浮","面色苍白","面色青黑"],"a":3,"e":"阳气暴脱、温煦推动骤然衰竭，面部血脉失充，故见面色苍白，伴冷汗淋漓、四肢厥冷、脉微欲绝。面色淡白多为血虚或气虚；面色㿠白是阳虚水泛；面白虚浮多属阳气虚衰、水湿不化；面色青黑主寒凝血瘀或剧痛，均非阳气暴脱之骤然苍白。苍白突出一个暴字，示阳气突然外脱"},{"q":"舌苔由厚转薄为","o":["由实转虚","邪气入里","胃气暴绝","正气胜邪，病趋好转","热邪伤津而病势加重"],"a":3,"e":"舌苔由厚转薄，是胃气渐复、正气胜邪、病邪消退之象，提示病情趋向好转。邪气入里苔由薄转厚；胃气暴绝表现为苔骤然消退、舌面光剥如镜，并非渐转薄；热邪伤津则苔由润转燥、黄厚而干，病势加重。厚薄反映邪正消长与病位深浅，由厚转薄是邪退正复的佳兆"},{"q":"下述哪项不是血热证的表现","o":["月经量多色淡","身热面赤发斑","肌肤生疔痈疮疖","温病之血分证","迫血妄行而出血"],"a":0,"e":"血热证因热入血分、迫血妄行，见身热面赤发斑、肌肤疔痈疮疖、出血及温病血分证，月经量多而色深红或紫红。月经量多色淡是气虚不摄或血虚、冲任失固之象，血得热则行、其色必深，色淡与血热病机相悖，故不属血热表现。身热发斑、疮疖、迫血出血皆紧扣血分有热，唯色淡提示气血不足"},{"q":"带下臭秽而黄稠者，多属","o":["寒湿","湿热","癌肿","痰饮","气滞"],"a":1,"e":"带下色黄、质稠、气味臭秽，是湿热下注、损伤任带二脉之象，故多属湿热。寒湿带下色白清稀无臭；痰湿带下色白质黏稠、量多；气滞多无明显带下色质改变；癌肿带下多为五色杂下、腥臭异常如米泔血水，与黄稠臭秽的湿热特征不同。黄、稠、臭三字是湿热下注的确据"},{"q":"点刺舌常与哪项并见","o":["青舌","紫舌","红舌","绛舌","淡白舌"],"a":2,"e":"点刺舌是舌面乳头突起如刺、色红或紫，为脏腑热盛、血分有热上荣于舌所致，故常与红舌并见。青舌主寒凝、血瘀；紫舌主血瘀或热极；绛舌为热入营血、阴液大伤，舌色深红，虽亦属热但较红舌更深一层；淡白舌主气血两虚、阳虚，无热象。红舌与点刺同属热盛，点刺尤以舌尖、舌边红赤起刺为著"},{"q":"雀啄脉的脉象是","o":["脉在皮肤，时而跃然而去，须臾又来","短小坚搏，如循薏苡子","如釜中沸水，浮泛无根","如屋漏残滴，良久一滴","脉在筋肉间，连连数急，三五不调，止而复作，如雀啄食状"],"a":4,"e":"雀啄脉脉在筋肉间、连连数急、三五不调、止而复作，如雀啄食，为脾气将绝的死脉。脉在皮肤、时而跃然而去须臾又来是虾游脉；短小坚搏如循薏苡子是弹石类脉；如釜中沸水浮泛无根是釜沸脉；如屋漏残滴良久一滴是屋漏脉，各脉形态迥异，雀啄以数急中止、如雀啄食为特征"},{"q":"肝胆湿热之呕吐物常为","o":["吐物酸腐","吐清稀痰涎","吐黄绿苦水","呕吐鲜血夹食物残渣","呕吐清水痰涎"],"a":2,"e":"肝胆湿热，胆液上泛，故呕吐物多为黄绿苦水，常伴口苦、胁痛、身目发黄。吐物酸腐是食积；吐清稀痰涎或清水痰涎是寒饮、胃阳不足；呕吐鲜血夹食物残渣是胃络损伤、肝胃郁热或溃疡出血，均非肝胆湿热。黄绿而苦是胆汁外溢的标志，为肝胆病变在呕吐物上的特征反映"},{"q":"下列各项，可出现日晡潮热的是","o":["湿遏热伏","热入营血","阳明经证","阳明腑证","阴虚内热"],"a":3,"e":"日晡潮热指午后申时热势加重，为阳明腑实、燥屎内结、腑气不通所致，常伴腹胀硬满、便秘、谵语。湿遏热伏身热不扬、午后热甚但不潮；热入营血身热夜甚、伴神昏斑疹；阳明经证为身大热、大汗、大渴、脉洪大，无潮热；阴虚内热为午后或入夜低热、五心烦热，均非日晡潮热"},{"q":"下列关于小儿食指络脉诊法描述错误的是","o":["小儿食指络脉诊法适用于3岁以下的小孩","食指络脉的显现与分布，可分为风、气、命三关","若络脉透过三关直达指端者，称为“透关射甲”","从风关向气关、命关直推","其络脉色淡为虚，色滞为实"],"a":3,"e":"小儿食指络脉诊法适用于3岁以下小儿，络脉分风、气、命三关，透过三关直达指端称透关射甲，色淡为虚、色滞为实，这些均正确。推按络脉应从命关向风关直推，使络脉显现以辨三关，而非从风关向气关、命关直推，方向颠倒，故该项错误。三关之名虽由风至命依次排列，但推络方向与之相反"},{"q":"“八纲”一词正式提出首见于","o":["《伤寒杂病论》","《景岳全书》","《诸病源候论》","《伤寒质难》","《伤寒六书》"],"a":3,"e":"八纲即表里、寒热、虚实、阴阳，作为辨证纲领，其名称正式提出首见于近代祝味菊《伤寒质难》。《伤寒杂病论》奠定辨证论治基础但未正式提出八纲一词；《景岳全书》创二纲六变说；《诸病源候论》重在病源证候；《伤寒六书》为研究《伤寒论》之作，均非八纲一词首见之处"},{"q":"腹部肿块推之不移，痛有定处，为","o":["癥积","瘕聚","痞满","结胸","肠痈"],"a":0,"e":"腹部肿块推之不移、痛有定处，是瘀血内停、有形癥块结于腹中，属癥积（血分）。瘕聚为气机郁滞、聚散无常，肿块推之可移、痛无定处，属气分；痞满为自觉脘腹痞塞胀满而无有形肿块；结胸为痰水结于胸腹、按之硬痛；肠痈为右下腹局限性肿痛、发热，均与固定不移的癥积不同"},{"q":"带下夹杂有血液，黏稠臭秽者，属于","o":["脾虚湿困","脾胃阳虚","寒湿下注","肝经湿热","阴虚火旺"],"a":3,"e":"带中夹血、黏稠臭秽，是湿热之邪循肝经下注、损伤任带、灼伤血络所致，属肝经湿热。脾虚湿困带下色白清稀；脾胃阳虚带下清稀量多、无臭；寒湿下注带下色白质稀；阴虚火旺带下量少色黄或夹血、质稠但多伴潮热盗汗、无明显臭秽，黏稠臭秽更突出肝经湿热实证"},{"q":"两眦赤痛，多属","o":["肺火","外感风热","心火上炎","脾有湿热","肝经风热"],"a":2,"e":"两眦即内眦、外眦，五轮学说属血轮、归心，两眦赤痛多因心火上炎、循经上攻目眦。肺火（气轮）多见白睛红赤；外感风热起病急、白睛红赤伴流泪；脾有湿热（肉轮）多见眼睑红肿、眵多；肝经风热（风轮）多见黑睛、目赤伴头痛，均与两眦属心的定位不符"},{"q":"下列不属于麻疹逆症的表现是","o":["疹点依出疹的先后逐渐回隐","壮热无汗","疹点不能透发","疹点色淡红而黯，或赤紫黯滞，或白而不红","疹点突然隐没，神昏喘息"],"a":0,"e":"麻疹顺证疹点透发后，依出疹先后顺序逐渐回隐、热退身安，故疹点依出疹的先后逐渐回隐是顺证表现，不属于逆证。壮热无汗、疹点不能透发是邪毒内陷、疹毒不透；疹色淡红而黯或赤紫黯滞、白而不红是血热毒盛或正气不足；疹点突然隐没、神昏喘息是邪毒内陷心包的险逆之象，均属逆证"},{"q":"可辨为“表热里寒”的是","o":["恶寒发热，舌淡苔白","恶寒发热，咳喘痰黄","恶寒发热，神疲气短","恶寒发热，脘腹冷痛","发热重恶寒轻，便溏尿清"],"a":4,"e":"表热里寒是表有热、里有寒，发热重恶寒轻为风热在表，便溏尿清为脾肾里寒、运化失司，二者并见即表热里寒。恶寒发热舌淡苔白是表寒；恶寒发热咳喘痰黄是表寒里热或表邪入里化热；恶寒发热神疲气短是表里同病、气虚外感；恶寒发热脘腹冷痛是表里皆寒，均非表热里寒组合"},{"q":"虫积肠道证最不易见到的症状是","o":["嗜食异物","大便秘结","大便排虫","面黄体瘦","面见白斑"],"a":1,"e":"虫积肠道以蛔虫等寄生虫内扰胃肠为特征，常见嗜食异物、面黄体瘦、面部虫斑、大便排虫、脐周腹痛。大便秘结多因热结、津亏或气滞，虫积肠道多见大便不调或排虫、腹泻，便秘并非其常见表现。嗜食异物、面见白斑是虫积的特异性指征，据此可与其他原因的消瘦、腹痛相区别"},{"q":"左少腹作痛，按之累累有硬块者为","o":["虫积","肠痈","宿粪","癥积","痞满"],"a":2,"e":"左少腹为乙状结肠、降结肠所在，燥屎宿积于此，故左下腹作痛、按之累累有硬块。虫积多见脐周疼痛、可触及条索状虫团；肠痈为右下腹阑尾处疼痛、拒按、发热；癥积为有形肿块、推之不移、痛有定处；痞满为脘腹痞胀无硬块，部位与形态均不合。左下腹硬块、累累可及是宿粪的特点"},{"q":"脏腑病变反映于舌面，其中舌两边属","o":["心肺","三焦","脾胃","肝胆","肾"],"a":3,"e":"舌面脏腑分候中，舌尖候心肺，舌中候脾胃，舌根候肾与下焦，舌两边候肝胆。三焦在舌面分候中多分配于舌中或舌根，不专主舌边；心肺在舌尖；脾胃在舌中；肾在舌根，均与舌边定位不符。舌边红赤、起刺或瘀斑，常提示肝胆火热或肝郁血瘀，是临床望舌边的重要依据"},{"q":"风邪的性质和致病特点有","o":["为百病之长","生风动血","性黏滞","易伤津液","性收引"],"a":0,"e":"风邪善行而数变、轻扬开泄，为六淫之首，常兼他邪侵袭人体，故称为百病之长。生风动血是热（火）邪的致病特点；性黏滞、病程缠绵是湿邪；易伤津液是燥邪（亦火热）；性收引、气机收敛是寒邪，均非风邪所主。风邪的善行数变与为百病之长是其核心特性"},{"q":"面部脏腑分候中，左颊候","o":["心","肝","脾","肺","肾"],"a":1,"e":"面部脏腑分候以左颊候肝、右颊候肺、额候心、鼻候脾、颏候肾，故左颊候肝。心候于额而非颊；脾候于鼻；肺候于右颊；肾候于颏（下巴），均与左颊不符。左颊青赤、右颊苍白等色泽变化，可分别提示肝、肺的病变，是面部望诊脏腑定位的要点"},{"q":"中焦湿热郁蒸所致的异常汗出是","o":["手足心汗","阴部汗出","心胸汗多","半身汗出","脘腹汗多"],"a":0,"e":"手足心汗可因中焦湿热郁蒸、迫津外泄于四末所致，脾胃湿热内蕴、气机郁滞，故手足心汗出。阴部汗出多属下焦湿热；心胸汗多（心汗）多因心脾两虚或思虑过度；半身汗出多为中风、痿证或营卫不和；脘腹汗多并非中焦湿热的典型局限部位，中焦湿热郁蒸以手足心汗为代表"},{"q":"受气候的影响，平脉在夏季应","o":["稍弦","稍洪","稍浮","稍沉","稍缓"],"a":1,"e":"平脉随四季气候而变，夏季阳气隆盛、气血充盛于外，脉应稍洪（钩），体现夏脉如钩。稍弦是春季平脉；稍浮（毛）是秋季；稍沉（石）是冬季；稍缓多见于长夏或脾气充盛之时。夏洪、春弦、秋浮、冬沉是四时平脉的基本规律，洪脉应夏是其中对应最为明确者"},{"q":"濡脉的主病为","o":["痰证","寒证","水饮","虚证","食滞"],"a":3,"e":"濡脉浮而细软、轻取即得、重按反薄，主虚证与湿邪，以气血两虚、脾胃湿困多见。痰证多见滑脉；寒证多见迟、紧脉；水饮多见弦脉或沉滑；食滞多见滑脉或促脉，均非濡脉所主。濡脉虽主湿，但湿邪困阻常与虚并见，教材以虚证为其主要主病，故本证选虚证"},{"q":"正常络脉的特点不包括","o":["隐现于风关内","淡紫色","形态多为斜形、单支","粗细适中","淡红色"],"a":4,"e":"正常小儿食指络脉色淡紫、隐现于风关之内，形态多斜形单支、粗细适中，是气血调和、脉络通畅之象。淡红色并非正常络脉的色泽描述，络脉色淡红而鲜明多见于表热，临床上以络脉色泽的淡滞、红紫来判别寒热虚实。隐现于风关内、淡紫色、斜形单支、粗细适中四项均为正常，淡红色不属正常特点"},{"q":"肾虚面色为","o":["赤色","黄色","青色","白色","黑色"],"a":4,"e":"黑色入肾，肾阳虚衰、水寒内盛或肾精亏虚、浊阴上泛，皆可见面色发黑，故肾虚面色为黑色。赤色主心火或热证；黄色主脾虚湿蕴；青色主肝郁、寒凝、疼痛、惊风；白色主虚寒、血虚、失血，均不属肾的本色。面黑而干焦多为肾阴虚、虚火灼津，黑而㿠白多为肾阳虚，虽分阴阳，色黑归肾则一"},{"q":"“有根”之脉象是指","o":["不浮不沉","节律一致","不快不慢","和缓有力","尺部沉取有力"],"a":4,"e":"脉之有根，主要指尺部沉取有力、应指不绝，尺为根、寸为苗，肾气充足则尺脉有根，虽有病亦易治。不浮不沉、不快不慢、和缓有力是脉有胃气、有神的表现，分别指脉位、脉率与脉力适中；节律一致亦属有神范畴。有根专指尺脉沉取，是判断肾气盛衰、疾病预后的要点"},{"q":"阳虚证的最典型症状是","o":["面色淡白","口淡不渴","大便稀溏","无汗或少汗","畏寒喜暖"],"a":4,"e":"阳虚证因阳气不足、温煦失职，最典型表现为畏寒喜暖、四肢不温，得温则舒。面色淡白、口淡不渴、大便稀溏、无汗或少汗虽亦可见，但或为血虚共有，或为寒证通见，特异性不如畏寒喜暖。畏寒喜暖直指阳气虚衰、产热不足这一根本，是阳虚与阴虚（五心烦热、潮热）辨析的核心"},{"q":"提示疾病发展转折点的是","o":["自汗","盗汗","蒸汗","冷汗","战汗"],"a":4,"e":"战汗是先全身战栗、继而汗出，为正邪剧烈交争之象，是疾病发展的转折点：汗出热退、脉静身凉则邪去正复向愈，汗后热仍、烦躁脉疾则邪盛正衰恶化。自汗多属气虚卫虚；盗汗多属阴虚；蒸汗（蒸蒸汗出）多为里热炽盛；冷汗多属阳虚或惊恐，均不具正邪相争、病情突变的转折意义"},{"q":"临床少见的证候转化是","o":["寒证转化为热证","热证转化为寒证","实证转化为虚证","表证转化为里证","虚证转化为实证"],"a":4,"e":"证候转化常见寒证化热、热证化寒、表证入里、里证出表及实证转虚，分别反映邪正消长与病位传变。虚证转化为实证临床少见，因正气已虚、机体抗邪与邪实能力不足，通常虚证日久更虚或虚实夹杂，而非纯转为实。实证转虚是邪盛伤正、正气受损的常见转归，与虚转实形成对照"},{"q":"神识不清，语言重复，时断时续，语声低弱者称为","o":["谵语","独语","郑声","错语","呓语"],"a":2,"e":"郑声表现为神识不清、语言重复、时断时续、语声低弱，是心气大伤、精神散乱的虚证，多见于久病危重。谵语神昏而语无伦次、声高有力，属热扰心神的实证；独语喃喃自语、见人即止，多属心气不足或癫证；错语是语言错乱而说后自知；呓语为睡梦中呓语，均与郑声的低弱重复不同"},{"q":"下列哪项不属于舌体强硬的主病","o":["热入心包","高热伤津","风痰阻络","寒凝筋脉","中风或中风先兆"],"a":3,"e":"舌体强硬、转动不灵、语言謇涩，多因热入心包、高热伤津、风痰阻络或中风及先兆，筋脉失养或痰热阻闭所致。寒凝筋脉多致舌体卷缩、短缩、色泽青紫，而非强硬不灵，故不属舌强主病。热入心包与高热伤津虽均属热，一在神明、一在津伤，风痰阻络则兼麻木歪斜，皆可见舌强"},{"q":"三焦病证的传变，其中的“逆传”是指","o":["阳明胃传入太阴肺","太阴脾传人太阴肺","从肺卫而传入心包","阳明胃经传入心包","中焦脾胃传入上焦"],"a":2,"e":"三焦辨证中，温病由上焦肺卫依次传至中焦脾胃、下焦肝肾为顺传；若肺卫之邪不循常道，直接内陷心包、蒙蔽心神，称为逆传心包，病势凶险。阳明胃传太阴肺、太阴脾传太阴肺、阳明胃经传心包、中焦脾胃传上焦均非经典逆传定义，逆传专指肺卫直陷心包这一越级内陷"},{"q":"屋漏脉的脉象是","o":["脉在皮肤，时而跃然而去，须臾又来","短小坚搏，如循薏苡子","如屋漏残滴，良久一滴","如釜中沸水，浮泛无根","脉在皮肤，头定尾摇，似有似无"],"a":2,"e":"屋漏脉如屋漏残滴、良久一滴、溅起无力，是胃气营卫将绝、脉搏极度迟缓无力的死脉。脉在皮肤、时而跃然而去须臾又来是虾游脉；短小坚搏如循薏苡子是弹石类脉；如釜中沸水浮泛无根是釜沸脉；脉在皮肤、头定尾摇似有似无是鱼翔脉，均与屋漏之良久一滴、迟缓无力不同"},{"q":"下列各项，属于湿热蕴脾证的临床表现的是","o":["面色萎黄","面黄虚浮","面色苍黄","面黄鲜明如橘皮色","面黄晦黯如烟熏"],"a":3,"e":"湿热蕴脾，胆汁外溢、湿热熏蒸，故面目肌肤发黄且黄色鲜明如橘皮色，属阳黄，常伴脘腹痞闷、口苦口黏、便溏不爽。面色萎黄多为脾胃气虚、气血生化不足；面黄虚浮是脾虚湿盛的黄胖；面色苍黄多属肝郁脾虚；面黄晦黯如烟熏是寒湿困脾的阴黄，均与鲜明如橘的湿热阳黄有别"},{"q":"下列哪项是少阴热化证中“心烦不得眠”的病机","o":["余热未清，留扰胸膈","阴虚热扰，心神不宁","阴血不足，心失所养","寒郁化热，扰乱心神","心火炽盛，侵扰心神"],"a":1,"e":"少阴热化证因少阴阴液亏虚、虚火内生，热扰心神，故见心烦不得眠，常伴口燥咽干、舌红少苔、脉细数。余热未清、留扰胸膈是栀子豉汤证的病机；阴血不足、心失所养多见心悸失眠、属心血虚；寒郁化热、扰乱心神非少阴热化本义；心火炽盛、侵扰心神属实热，均非少阴阴虚热化的核心病机"},{"q":"面目肌肤俱黄，黄而晦暗如烟熏色属于","o":["萎黄","黄胖","阴黄","阳黄","苍黄"],"a":2,"e":"面目肌肤俱黄、黄色晦暗如烟熏，是寒湿困脾、阳气不宜、胆汁外溢肌肤所致，属阴黄，常伴脘腹痞闷、畏寒、便溏、舌淡苔腻。萎黄为气血不足、面色萎黄无光泽，目睛不黄；黄胖是脾虚湿盛、面黄虚浮；阳黄为湿热熏蒸、黄色鲜明如橘；苍黄为面色青黄相间，均非晦暗如烟熏的阴黄"},{"q":"由里出表提示","o":["机体抗邪能力强盛","里证转化为表证","治疗护理适当","邪有出路，病情有向愈之势","表里同病"],"a":3,"e":"里证迁延，邪气由里达表、从肌表外解，提示邪有出路、正气驱邪外出，病情有向愈之势。机体抗邪能力强盛是由里出表的条件之一，但非该转归本身所提示的核心；里证转化为表证只是现象描述，非意义所在；治疗护理适当是可能的诱因而非转归含义；表里同病是表里证并见，与由里出表的动态转化不同"},{"q":"风疹的病因病机是","o":["外感风热时邪","气分热盛","风寒湿邪侵犯肌表","湿郁汗出不彻","邪热入营"],"a":0,"e":"风疹由外感风热时邪所致，邪郁肌表、与气血相搏，发于肌肤则见淡红色细小皮疹、分布均匀、瘙痒，伴轻微发热、咳嗽流涕。气分热盛多见壮热、大渴、大汗；风寒湿邪侵犯肌表多为痹证、无皮疹；湿郁汗出不彻多致痱子、湿疹；邪热入营则神昏、斑疹隐隐，均非风疹风热时邪、邪浅病轻的病机"},{"q":"病人舌苔厚腻骤然消退，属于","o":["正气渐复病好转","热势加重津液伤","正不胜邪胃气绝","邪气由表入里","病情由虚转实"],"a":2,"e":"舌苔厚腻本主湿浊、食积内盛，若骤然消退、舌面光剥如镜，是胃气暴绝、正不胜邪、舌苔失于胃气上承的危象，并非病退。正气渐复、病好转者苔由厚渐薄、由腻渐净，是一个渐进过程；热势加重津伤则苔由润转燥、黄厚干裂；邪气由表入里苔由薄转厚；病情由虚转实苔由少增多，均与骤然消退不同"},{"q":"面色黑而干焦多属","o":["肾阴亏虚","肾阳亏虚","肾气亏虚","瘀血阻络","水饮内停"],"a":0,"e":"面色发黑而干焦，是肾阴亏虚、虚火上炎、津液被灼不能上荣于面，故多属肾阴亏虚。肾阳亏虚面色黑而㿠白或暗淡、无干焦之象；肾气亏虚以齿摇、耳鸣、腰膝酸软为主，面色改变不显；瘀血阻络见面色黧黑、肌肤甲错；水饮内停见面色黑而虚浮或眼眶周围发黑，均与干焦的肾阴虚不同"},{"q":"后囟门出生很小或已闭合，至迟闭合时间约于出生后","o":["12~18周","5~6周","10~12周","6~8周","12~16周"],"a":3,"e":"后囟门出生时多已很小或已闭合，最迟约于出生后6～8周闭合，是婴儿颅骨发育的正常时限。12～18周、10～12周、12～16周均超过正常闭合时间，提示闭合过迟；5～6周虽在正常范围，但非最迟时限，均不合题意。前囟闭合较晚，约1～1.5岁，常与后囟闭合时间混淆，须加以区别"},{"q":"颈侧颌下有肿块如豆，累累如串珠者，称为","o":["发颐","瘰疬","瘿瘤","痰核","梅核气"],"a":1,"e":"颈侧颌下肿块如豆、累累如串珠，是淋巴结结核，称为瘰疬，多因肺肾阴虚、虚火灼津成痰、凝结于少阳、阳明经络所致。发颐是急性化脓性腮腺炎，耳下漫肿疼痛；瘿瘤是甲状腺肿大，颈前正中、随吞咽上下；痰核为皮下 solitary 肿块、不红不痛；梅核气为咽中如有物阻、咯吐不出、吞咽不下而无实质肿块，均与串珠状瘰疬不同"},{"q":"因情志过极导致的“气闭”，最突出的表现是","o":["突然晕厥","胀闷不舒","神情不宁","胀痛窜痛","脉弦"],"a":0,"e":"情志过极、气机突然闭塞不通，清窍失养，最突出的表现是突然晕厥、不省人事，常伴四肢厥冷、脉沉实或弦。胀闷不舒是气滞的自觉症状，尚未至闭；神情不宁是神志受扰而非气闭；胀痛窜痛属气滞疼痛的特点；脉弦是气滞、肝郁的脉象，均非情志气闭最突出的突然晕厥。气闭与气滞程度不同，闭则窍闭神昏"},{"q":"因痰浊、瘀血、砂石、寄生虫等阻塞所致的“气闭”，最突出的表现是","o":["突然晕厥","胀闷不舒","神情不宁","绞痛阵作","脉弦"],"a":3,"e":"痰浊、瘀血、砂石、寄生虫等有形实邪阻滞气道、血脉或脏腑，气机不通则痛，最突出的表现是绞痛阵作，如胆石、蛔虫所致的剧烈绞痛。突然晕厥是情志气闭的特点；胀闷不舒、神情不宁、脉弦均非有形实邪阻塞气闭的特征性表现。绞痛阵作反映实邪梗阻、气机骤闭，是此类气闭的辨证要点"},{"q":"心血虚证的脉象是","o":["脉细数","脉细弦","脉细弱","脉浮细","脉沉紧"],"a":2,"e":"心血虚证因血液不足、心失所养、脉道不充，脉象多细弱，伴心悸失眠、健忘、面色淡白或萎黄。脉细数主阴虚内热，是心阴虚或阴虚火旺之象；脉细弦多为肝郁血虚或肝郁气滞；脉浮细主外感或虚阳浮越；脉沉紧主里寒、痛证，均与心血虚的细弱无力不同。细弱突出血少、脉动无力，是心血虚的脉象特征"},{"q":"肝郁气滞胁痛的特点是","o":["隐痛","灼痛","胀痛","掣痛","绞痛"],"a":2,"e":"肝郁气滞，肝经气机郁滞、经脉不利，故胁痛以胀痛为主，痛无定处、太息后舒，常伴胸闷、情志抑郁。隐痛多属肝阴（血）不足、络脉失养；灼痛为肝胆湿热或肝火上炎、火热灼络；掣痛多属肝脉拘急或悬饮；绞痛是砂石、蛔虫等实邪梗阻气机，均非肝郁气滞的胀痛特点。胀痛是气滞疼痛的标志"},{"q":"下列哪项不属脉力不足的脉象","o":["弱脉","濡脉","牢脉","微脉","虚脉"],"a":2,"e":"牢脉沉而实大弦长、坚牢不移，脉力充实有力，主阴寒内盛、疝气癥积，不属脉力不足。弱脉沉而细软、濡脉浮而细软、微脉极细极软、虚脉举之无力按之空豁，四者均以脉力不足为特征。牢与革虽皆坚搏指下，但牢沉实、革浮而中空，牢脉以沉实有力见长，故不是力不足之脉"},{"q":"湿温潮热的特点是","o":["午后低热","日晡热甚","身热不扬","骨蒸发热","入夜热甚"],"a":2,"e":"湿温潮热因湿热郁蒸、湿遏热伏，热象被湿邪包裹而不外扬，故特点是身热不扬，初按不热、稍久烫手，伴头身困重、脘闷、苔腻。午后低热多属阴虚或气虚发热；日晡热甚是阳明腑实；骨蒸发热是阴虚火旺、热自骨内向外透发；入夜热甚多属热入营血或阴虚，均非湿温湿遏热伏的身热不扬"},{"q":"望神时观察的要点是神情、气色、体态和","o":["语言","舌象","眼神","呼吸","脉象"],"a":2,"e":"望神通过观察眼神、神情、气色、体态等方面判断，其中眼神是望神的重点，目为心之使、五脏六腑之精气皆上注于目，目光明亮有神则脏腑精气充足。语言、呼吸虽属闻诊与全身表现，舌象属望舌内容，脉象属切诊，均非望神要点中与神情、气色、体态并列的核心，眼神最能反映神之存亡"},{"q":"导致消谷善饥的病机是","o":["肝胆湿热","胃火炽盛","脾胃虚弱","虫积肠道","胃阴不足"],"a":1,"e":"消谷善饥是食欲亢进、食后不久即饥饿，因胃火炽盛、腐熟功能过旺、胃中消食太快所致，常伴口臭、口渴、便秘、牙龈肿痛。肝胆湿热以口苦、胁痛、黄疸为主；脾胃虚弱则食少纳呆；虫积肠道虽可见嗜食异物、多食，但非消谷善饥主因；胃阴不足饥不欲食、干呕，均与胃火炽盛的消谷善饥不同"},{"q":"食少纳呆，消瘦乏力，腹胀便溏，食后胀甚，证属","o":["寒湿困脾证","脾气虚证","胃气虚证","肝胃不和证","肝郁脾虚证"],"a":1,"e":"食少纳呆、消瘦乏力、腹胀便溏、食后胀甚，是脾气虚弱、运化失职、气血生化不足之象，故属脾气虚证。寒湿困脾以脘腹痞闷、口黏不渴、苔白腻、身重为主；胃气虚以胃脘隐痛、食欲减退、嗳气为主而无腹胀便溏；肝胃不和以胃脘胀痛、情志相关、嗳气吞酸为主；肝郁脾虚兼胸胁胀满、情志抑郁，均非单纯脾气虚"},{"q":"谵语的病机是","o":["心气大伤","热扰心神","心气不足","痰蒙心神","瘀阻心窍"],"a":1,"e":"谵语是神识不清、语无伦次、声高有力，因实热内盛、热扰心神、神明昏乱所致，多见于温病高热、热入心包。心气大伤、心气不足多致郑声或独语等虚证表现；痰蒙心神多见神志痴呆、癫证、喉中痰鸣；瘀阻心窍可见神昏、舌紫暗、心痛，均非谵语热扰心神、声高有力的实证病机。谵语郑声一实一虚，是辨证关键"},{"q":"对正常舌象的诊断，下列哪项是错误的","o":["舌体柔软","舌体活动自如","舌淡嫩少苔","舌色淡红","舌苔薄白"],"a":2,"e":"正常舌象为淡红舌、薄白苔，舌体柔软、活动自如、大小适中，舌色淡红而润。舌淡嫩少苔是气血不足或脾胃虚弱、舌失充养的病理舌象，不属于正常。舌体柔软、活动自如、舌色淡红、舌苔薄白均为正常舌象的组成部分，唯淡嫩少苔提示虚证，故为错误描述"},{"q":"青如翠羽是","o":["主色","客色","善色","恶色","常色"],"a":2,"e":"面色青如翠羽、鲜明润泽，是病色虽有异常而光泽尚存、气血未衰之象，属善色，提示病情较轻、预后较好。主色是个体终身不变的基本肤色；客色是因季节、环境而变的正常肤色；常色包括主色与客色，均为正常；恶色是晦暗枯槁、如枯草之色，提示精气衰败、病重，均与青如翠羽的润泽鲜明不同"},{"q":"肝血虚和肝阴虚的共同临床表现是","o":["面色红赤","视力减退","面色淡白","潮热盗汗","舌绛"],"a":1,"e":"肝开窍于目，肝血虚与肝阴虚均致目失所养，故共有视力减退、视物昏花、眼干涩。面色红赤、舌绛、潮热盗汗是肝阴虚、虚火内扰的表现，肝血虚无热象；面色淡白是肝血虚、肌肤失养之象，肝阴虚见面色潮红而非淡白。两者一偏血虚失养、一偏阴虚内热，视力减退是二者共有的眼科特征"},{"q":"结、代、促脉，其脉象的共同特点是","o":["脉来时一止","止有定数","止无定数","脉来缓慢","脉来急促"],"a":0,"e":"结脉、代脉、促脉均属有间歇的脉象，共同特点是脉来时一止。止有定数是代脉，止无定数是结脉、促脉；脉来缓慢是结脉，脉来急促是促脉，均非三者共性。三者鉴别在于：结脉缓而止无定数，代脉止有定数、良久方来，促脉数而止无定数，但脉来时一止是三者区别于其他脉象的共同标志"},{"q":"主气分热盛的脉象是","o":["洪脉","数脉","疾脉","牢脉","动脉"],"a":0,"e":"洪脉脉体阔大、来盛去衰、如波涛汹涌，主气分热盛、邪热亢盛，多伴身大热、大汗、大渴。数脉主热证，但重在至数快、不一定脉体阔大；疾脉主阳极阴竭、元气将脱，脉率极快；牢脉主阴寒内盛、疝气癥积；动脉主痛、惊，均非气分热盛之脉。洪脉以阔大来盛去衰为特征，是气分热盛的典型脉象"},{"q":"病人但卧不能坐，坐则晕眩，多属","o":["肺胀","哮病","肺气壅滞","痰饮停肺","气血俱虚"],"a":4,"e":"病人只宜平卧、不能坐起，坐则晕眩，是气血俱虚、清阳不升、头部失养，改变体位则眩晕加重。肺胀、哮病、肺气壅滞、痰饮停肺所致者多为但坐不能卧，因痰饮壅肺、肺气上逆，平卧则喘促加重，须端坐呼吸，与气血俱虚的但卧不能坐体位喜恶正好相反，是鉴别要点"},{"q":"能够判断疼痛虚实的方法是","o":["痛处喜温或喜凉","痛时姿势","喜按或拒按","疼痛部位","痛处颜色"],"a":2,"e":"疼痛喜按、按之痛减多属虚证，因气血不足、络脉失养；拒按、按之痛甚多属实证，因邪气壅滞、不通则痛，故喜按或拒按是辨别疼痛虚实的主要方法。痛处喜温或喜凉辨寒热；痛时姿势可辅助判断痛证性质与病位；疼痛部位辨病位所属脏腑经络；痛处颜色辨有无瘀血、热毒，均非直接辨别虚实之法"},{"q":"痰色白，质稠量多，滑而易咯出者，多属","o":["寒痰","热痰","燥痰","湿痰","风痰"],"a":3,"e":"痰色白、质稠、量多、滑而易咯出，是脾失健运、湿聚成痰、壅肺所致，属湿痰。寒痰色白清稀、量多易咯但质不稠；热痰色黄质稠、黏结成块；燥痰量少质黏、干咳难咯、口鼻干燥；风痰多泡沫、伴眩晕肢麻或外风表证，均非白稠量多易咯的湿痰特征。滑而易咯是湿痰的典型表现"},{"q":"苔白厚如积粉，多由于","o":["痰湿、食积内阻","表证未罢，内传入里","外感秽浊湿邪与热毒相结合","阴虚火旺，虚火灼津","痰浊湿热内蕴"],"a":2,"e":"苔白厚如积粉、扪之不燥，称积粉苔，由外感秽浊湿邪与热毒相合、郁遏膜原所致，常见于瘟疫或内痈。痰湿、食积内阻多见白厚腻苔，但不如积粉之厚如涂粉；表证未罢内传入里苔由薄转厚；阴虚火旺、虚火灼津见苔少或剥、黄燥；痰浊湿热内蕴多见黄腻苔，均与积粉苔的秽浊热毒成因不同"},{"q":"皮肤干枯粗糙，状若鱼鳞，多因","o":["阴津已伤","营血亏虚","外邪侵袭","气血阻滞","瘀血日久"],"a":4,"e":"皮肤干枯粗糙、状若鱼鳞，即肌肤甲错，是瘀血日久、新血不生、肌肤失于濡养所致，常伴面色黧黑、唇甲青紫、舌紫暗或有瘀斑。阴津已伤虽可致皮肤干燥，但多为全身性、伴口渴咽干，不如甲错之粗糙如鳞；营血亏虚以面色淡白、头晕眼花为主；气血阻滞、外邪侵袭均非肌肤甲错的直接成因。肌肤甲错是瘀血的特征性体征"},{"q":"小便频数，黄赤急迫者，属于","o":["肾阳不足","肾气不固","肾阴亏虚","膀胱湿热","瘀血阻滞"],"a":3,"e":"小便频数、黄赤、排尿急迫灼痛，是湿热下注膀胱、气化不利、水道受热煎熬所致，属膀胱湿热，常伴尿痛、尿血、小腹胀痛。肾阳不足小便清长、夜尿多、畏寒；肾气不固尿频而清、遗尿失禁；肾阴亏虚尿少色黄但无急迫灼痛；瘀血阻滞小便不畅、刺痛有血块，均与黄赤急迫的膀胱湿热不同。黄赤急迫是湿热下注的确据"},{"q":"津液的生成与输布，主要与下列哪一项所示脏腑的关系最密切","o":["脾、胃、肺","肺、脾、肾","肺、三焦、肝","肺、肝、膀胱","三焦、膀胱、肺"],"a":1,"e":"津液的生成依赖脾胃运化水谷，输布依赖肺的宣发肃降、通调水道，排泄与气化依赖肾的气化作用，故与肺、脾、肾关系最密切。脾胃虽主生成，但上输于肺、布散全身仍需肺、肾参与；三焦为水道、膀胱储尿，但为传导之腑而非生成输布之本；肝主疏泄、调气机，间接影响水液，均非最直接相关。肺脾肾三脏分司通调、运化、气化"},{"q":"以腹部硬满疼痛拒按、便秘为主要表现的证是","o":["胃肠气滞证","肠热腑实证","肠燥津亏证","虫积肠道证","胃热炽盛证"],"a":1,"e":"腹部硬满、疼痛拒按、便秘，是邪热入里与肠中糟粕相结、腑气不通、燥屎内停所致，属肠热腑实证，常伴潮热、谵语、舌红苔黄燥。胃肠气滞以胀痛、嗳气矢气后舒为主，无明显硬满便秘；肠燥津亏虽有便秘但腹不硬满拒按、无明显热象；虫积肠道以腹痛、排虫、嗜食异物为主；胃热炽盛以胃脘灼痛、消谷善饥、口臭为主，均非肠热腑实"},{"q":"乳痈多发于女性","o":["青春期","妊娠期","哺乳期","更年期","老年"],"a":2,"e":"乳痈是乳房急性化脓性疾病，多因哺乳期乳汁淤积、肝郁胃热、邪毒入侵所致，故多发于哺乳期妇女，尤以初产妇产后3～4周常见。青春期乳房发育未泌乳；妊娠期乳腺增生但未大量泌乳；更年期、老年期乳腺功能衰退，均非乳痈好发阶段。乳汁淤积是发病关键，故哺乳期最为多见"},{"q":"咳声不扬，痰稠色黄证属","o":["风热袭表","寒邪客肺","痰湿阻肺","痰热壅肺","阴虚肺燥"],"a":3,"e":"咳声不扬、痰稠色黄，是痰热互结、壅肺阻气、肺失宣降所致，属痰热壅肺，常伴胸闷、气促、喉中痰鸣、口渴。风热袭表以发热重、咽痛、咳嗽痰黄但表证为主；寒邪客肺咳痰清稀、恶寒；痰湿阻肺痰多色白质稠；阴虚肺燥干咳少痰、痰黏难咯、口干，均非痰稠色黄的痰热壅肺。痰黄稠是痰热的标志"},{"q":"下列哪项不属影响脉象的生理性因素","o":["四季气候","地理环境","性别","年龄","体位"],"a":4,"e":"影响脉象的生理性因素包括四季气候（春弦夏洪秋浮冬沉）、地理环境（南方脉浮数、北方脉沉迟）、性别（女脉较濡细、妊娠滑数）、年龄（少儿脉数、老年脉弱）等。体位虽可改变血流动力学，但教材未将其列入脉象的生理性影响因素，故不属。四季、地理、性别、年龄均是教材明确列举、随内外环境或体质而变化的生理因素"},{"q":"促脉的脉象是","o":["数而一止，止无定数","数而一止，止有定数","缓而时止，止无定数","缓而时止，止有定数","止有定数，良久方来"],"a":0,"e":"促脉为脉来数疾、时而一止、止无定数，主阳盛实热、气血痰食停滞。数而一止、止有定数近于代脉，非促脉；缓而时止、止无定数是结脉；缓而时止、止有定数近于代脉；止有定数、良久方来是代脉。促与结均止无定数，区别在于促数结缓，数而一止、止无定数正是促脉"},{"q":"小儿食指络脉色青主病","o":["惊风证","热证","血瘀证","表证","气血亏虚"],"a":0,"e":"小儿食指络脉色青，是肝风内动、筋脉拘急、气血郁滞之象，主惊风证，常伴抽搐、项强，亦主痛证。热证（表热）多见络脉色鲜红或紫红；血瘀证色紫暗或青紫；表证络脉浮露、色鲜红，多在风关；气血亏虚色淡白，络脉细弱，均与色青主惊风不同。青色主惊、主痛，是小儿指纹望诊的要点"},{"q":"可见咳吐脓血腥臭痰表现的证是","o":["风水搏肺证","风寒犯肺证","寒痰阻肺证","饮停胸胁证","痰热壅肺证"],"a":4,"e":"咳吐脓血、痰腥臭，是痰热（热毒）壅肺、血肉腐败成脓、肺络损伤所致，属痰热壅肺证，常见于肺痈。风水搏肺以眼睑头面浮肿、恶寒发热为主；风寒犯肺咳嗽痰白清稀；寒痰阻肺痰白清稀、胸闷；饮停胸胁胸胁胀痛、咳唾引痛，均无非脓血腥臭之象。咳吐腥臭脓血是痰热壅肺成痈的确据"},{"q":"午后两颧潮红者属","o":["气虚证","虚热证","血虚证","戴阳证","实热证"],"a":1,"e":"午后两颧潮红、伴潮热盗汗、五心烦热、舌红少苔，是阴液亏虚、虚火上炎之象，属虚热证。气虚证以神疲乏力、少气懒言为主，无颧红潮热；血虚证见面色淡白或萎黄、头晕心悸；戴阳证是虚阳上浮、面红如妆、游移不定、四肢厥冷；实热证高热面赤、满面通红、口渴喜冷，均非午后两颧潮红的虚热特征"},{"q":"气滞血瘀证的疼痛性质","o":["钝痛，持续时间长","刺痛","胀痛","胀闷走窜疼痛，甚或刺痛","空痛"],"a":3,"e":"气滞血瘀证因气机郁滞、血行瘀阻，疼痛特点为胀闷走窜疼痛、痛无定处，继而转为刺痛、痛有定处，故为胀闷走窜疼痛甚或刺痛。单纯钝痛持续时间长多属湿阻或虚证；单纯刺痛是血瘀；单纯胀痛是气滞；空痛多属气血不足、精髓亏虚，均不能概括气滞血瘀先胀后刺、走窜转固定的复合特点"},{"q":"久病、重病患者面色苍白，时而颧赤泛红如妆、游移不定是","o":["实热证","虚热证","阴虚证","戴阳证","虚寒证"],"a":3,"e":"久病重病面色苍白，时而颧赤泛红如妆、游移不定，是下焦虚寒、虚阳被格拒于上、浮越于面，属戴阳证，常伴四肢厥冷、下利清谷、脉微欲绝。实热证满面通红、高热烦渴；虚热证午后两颧潮红、潮热盗汗但面色不苍白；阴虚证亦有颧红但为潮热、固定伴阴虚象；虚寒证面色㿠白无颧红如妆，均非虚阳浮越的戴阳"},{"q":"肾虚水泛的痰饮病，面色多为","o":["眼眶周围黑","面色黧黑","面黑而干焦","面色淡白而胖","面色淡黄而兼虚浮"],"a":0,"e":"肾虚水泛、水饮内停，水气上泛于目窠，故面色多见眼眶周围发黑，常伴全身水肿、腰以下甚、尿少、畏寒。面色黧黑多属瘀血日久、肌肤甲错；面黑而干焦是肾阴亏虚、虚火灼津；面色淡白而胖多为阳气不足、水湿泛溢之全身表现；面色淡黄虚浮是脾虚湿盛，均非肾虚水饮上泛所致的眼眶周围黑"},{"q":"下列哪项一般不会出现腻苔","o":["湿浊","阴虚","痰饮","食积","顽痰"],"a":1,"e":"腻苔苔质致密、颗粒细小、如涂油腻，主湿浊内蕴、阳气被遏，常见于湿浊、痰饮、食积、顽痰等证。阴虚者津液亏少、虚火内生，舌象多为少苔、剥苔、镜面舌或黄燥苔，绝无腻苔，故阴虚一般不会出现腻苔。湿浊、痰饮、食积、顽痰均属湿邪、有形实邪内停，是腻苔的常见主病，与阴虚津亏的舌象形成对照"},{"q":"表寒证的典型临床表现不包括","o":["恶寒发热","头身疼痛","鼻塞流清涕","咽喉肿痛","无汗"],"a":3,"e":"表寒证因风寒束表、卫阳被遏，典型表现为恶寒重发热轻、无汗、头身疼痛、鼻塞流清涕、苔薄白、脉浮紧。咽喉肿痛是风热上攻或肺胃热盛所致，属表热或里热证，风寒表证一般无咽痛或仅咽痒，故不属表寒证典型表现。恶寒发热、头身痛、流清涕、无汗均为风寒袭表的常见症状"},{"q":"弦脉与革脉的共同特征主要表现在","o":["流利度","紧张度","至数","脉宽","脉位"],"a":1,"e":"弦脉端直以长、如按琴弦，革脉浮而搏指、中空外坚如按鼓皮，二者均以脉体紧张度高、应指绷紧为共同特征，故主要表现在紧张度。流利度是滑脉与涩脉的对比；至数是数脉、迟脉的区别；脉宽涉及洪脉、细脉；脉位是浮脉、沉脉的区分，均非弦脉与革脉的共同点。弦、革脉虽主病不同，但按之绷紧的紧张感相同"},{"q":"下列哪一项不属于失神的临床表现","o":["目暗睛迷","瞳神呆滞","精神委靡","目浮光外露","面色晦黯无华"],"a":3,"e":"失神表现为目暗睛迷、瞳神呆滞、精神委靡、面色晦黯无华、反应迟钝，甚至循衣摸床、神昏，是精气大伤、病势危重之象。目浮光外露是久病危重者突然目光浮亮、色如妆、神似好转的假神，为阴阳即将离决的回光返照，不属于失神。目暗睛迷、瞳神呆滞、精神委靡、面色晦黯无华均是精气亏竭的失神表现"},{"q":"以下不主实热证的是","o":["牢脉","滑脉","洪脉","数脉","长脉"],"a":0,"e":"牢脉沉而实大弦长、坚牢不移，主阴寒内盛、疝气、癥积，属阴寒实证，不主实热。滑脉主痰湿、食积、实热及妊娠；洪脉主气分热盛；数脉主热证；长脉主阳盛、热盛、癫痫，均可主实热。牢脉虽脉力充实，但沉牢主寒主实，与洪、数等实热脉的浮数有力不同，故不主实热证"},{"q":"下列各项，不属脾阳虚证的临床表现的是","o":["浮肿尿少","带下清稀量多","畏寒肢冷","月经过多","腹痛喜温喜按"],"a":3,"e":"脾阳虚证以脾失温运、寒从中生为核心，常见腹痛喜温喜按、畏寒肢冷、大便稀溏、肢体浮肿尿少、带下清稀量多。月经过多多属脾不统血、冲任不固，虽与脾气（阳）虚有关，但非脾阳虚证本身的典型临床表现。浮肿尿少、带下清稀、畏寒肢冷、腹痛喜温喜按均紧扣脾阳不足、温化失职，故月经过多为除外项"},{"q":"脾胃虚寒之人可见下列哪一症状","o":["口甜而腻","口中泛酸","口中酸馊","口淡无味","口有苦味"],"a":3,"e":"脾胃虚寒、运化失职、津液不能上承于口，故觉口淡无味，常伴食欲不振、胃脘隐痛喜温喜按、大便稀溏。口甜而腻多属脾胃湿热或痰湿；口中泛酸多为肝胃不和或胃气上逆；口中酸馊是食积内停、胃气腐熟失常；口有苦味多因肝胆火热或邪在少阳，均与脾胃虚寒的口淡无味不同"},{"q":"根据五轮学说，眼睑为","o":["水轮","风轮","血轮","气轮","肉轮"],"a":4,"e":"五轮学说将眼部分属五脏，眼睑（胞睑）属肉轮、归脾，脾主肌肉，故眼睑为肉轮。水轮为瞳神、属肾；风轮为黑睛、属肝；血轮为两眦、属心；气轮为白睛、属肺，均与眼睑的肉轮归属不符。眼睑红肿、下垂、睑缘糜烂等常从脾胃论治，即基于肉轮属脾的理论"},{"q":"根据五轮学说，黑睛属于","o":["肺","脾","肾","心","肝"],"a":4,"e":"五轮学说中黑睛（角膜）属风轮、归肝，肝开窍于目、肝气通于目，故黑睛属于肝。肺主白睛为气轮；脾主眼睑为肉轮；肾主瞳神为水轮；心主两眦为血轮，均与黑睛属肝的归属不同。黑睛生翳、星翳、凝脂等病变多从肝经风热或肝火论治，即本于风轮属肝"},{"q":"小儿食指络脉诊法适用于","o":["七岁以内","五岁以内","三岁以内","一岁以内","十岁以内"],"a":2,"e":"小儿食指络脉诊法主要适用于3岁以内小儿，因此时小儿寸口脉位短小、诊脉不便，且肌肤薄嫩、络脉显露清晰，可候风、气、命三关以辨病。七岁、五岁、十岁以内年龄偏大，络脉渐不显、诊脉已可配合；一岁以内虽可诊络脉，但适用上限为三岁，故三岁以内为规范表述"},{"q":"指力适中，不轻不重，按至肌肉而取脉的方法是","o":["浮取","中取","沉取","单按","总按"],"a":1,"e":"切脉指法中，指力适中、不轻不重、按至肌肉而取脉的方法为中取，又称寻法，可体察脉象的中层特征。浮取（举）是轻用力、按至皮肤，用于探表浅脉；沉取（按）是重用力、按至筋骨，用于探深部脉；单按是单指按一部，总按是三指同时按寸关尺，均非按至肌肉的中取。举、按、寻是切脉三种基本指法"},{"q":"灰黑苔辨寒热的关键是观察","o":["舌苔之厚薄","舌苔之腐腻","舌形之胖瘦","舌苔之润燥","舌之老嫩"],"a":3,"e":"灰黑苔主病有寒热之别，关键在润燥：苔灰黑而湿润、滑润多属阳虚寒湿、痰饮内停；苔灰黑而干燥、焦裂多属热盛伤津、阴虚火旺。苔之厚薄、腐腻主要辨邪气盛衰与湿浊；舌形胖瘦辨虚实、水湿；舌之老嫩辨虚实，均非灰黑苔辨寒热的关键，润燥才是区分寒热属性的核心依据"},{"q":"以高热不退，四肢抽搐，颈项强直，两目上视，角弓反张，牙关紧闭，舌红绛，苔黄燥，脉弦数为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","寒滞肝脉证"],"a":3,"e":"高热不退、四肢抽搐、颈项强直、两目上视、角弓反张、牙关紧闭，伴舌红绛、苔黄燥、脉弦数，是热邪炽盛、灼伤筋脉、肝风内动，属热极生风证。血虚生风以肢体麻木、震颤、面色淡白、舌淡为主，无高热；肝阳化风多有头晕头胀、面红、肢体麻木、中风；阴虚风动手足蠕动、潮热盗汗、舌红少苔；寒滞肝脉少腹冷痛、畏寒，均无高热抽搐"},{"q":"下列何证的主症是寒热往来，胸胁苦满，心烦喜呕","o":["阳明病证","厥阴病证","太阴病证","太阳病证","少阳病证"],"a":4,"e":"寒热往来、胸胁苦满、心烦喜呕，是邪郁少阳、枢机不利、胆火上炎、胃失和降之象，属少阳病证，常伴口苦、咽干、目眩。阳明病证为身大热、大汗、大渴、便秘；厥阴病证为消渴、气上撞心、饥不欲食、寒热错杂；太阴病证为腹满而吐、食不下、自利；太阳病证为恶寒发热、头项强痛、脉浮，均非少阳半表半里之证"},{"q":"下述何项对于新生儿问诊意义不大","o":["妊娠期母体营养状况","有无传染病史","妊娠期母体患过何病","母亲妊娠期、产育期用过何药","分娩时是否难产、早产"],"a":1,"e":"新生儿问诊重在母体妊娠期情况与分娩经过，因新生儿自身疾病多与母体妊娠期营养、患病、用药及分娩时难产、早产、窒息等相关，故妊娠期母体营养、患过何病、产育期用药、分娩是否难产早产均有意义。新生儿本人有无传染病史对其诊断意义不大，因其出生时间短、既往史几近于无，故为意义不大之项"},{"q":"白厚腻苔多见于","o":["里热证","寒湿证","表寒证","虚寒证","阴虚证"],"a":1,"e":"白厚腻苔是苔色白、苔质厚腻，主寒湿内盛、湿浊中阻，因寒湿困脾、阳气被遏、湿浊上泛于舌，故多见于寒湿证。里热证多见黄苔或黄厚苔；表寒证苔薄白、不厚腻；虚寒证多见舌淡苔白滑、质薄；阴虚证少苔、剥苔或黄燥，均非白厚腻苔所主。白厚腻紧扣寒湿、湿浊内盛"},{"q":"泻下黄糜，伴肛门灼热者，属于","o":["大肠液亏","大肠湿热","肠虚滑脱","脾肾阳虚","肝郁乘脾"],"a":1,"e":"泻下黄糜、肛门灼热，是湿热下注大肠、传导失司、热迫津液外泄所致，属大肠湿热，常伴腹痛、里急后重、小便短赤。大肠液亏以大便干结、排便困难为主；肠虚滑脱以久泻久痢、滑脱不禁、肛门无灼热为主；脾肾阳虚为五更泄泻、完谷不化、腹部冷痛；肝郁乘脾为腹痛即泻、泻后痛减、与情志相关，均与黄糜灼热的湿热下注不同"},{"q":"观察舌苔以辨别病邪深浅的主要依据是","o":["舌苔的有无","舌苔的黄白","舌苔的有根无根","舌苔的薄厚","舌苔的润燥"],"a":3,"e":"舌苔薄厚可辨病邪深浅与邪正盛衰：薄苔多属表证、邪气轻浅或胃气充盛；厚苔多属里证、邪气入里或湿浊、食积内盛，苔越厚邪越深。苔之有无辨胃气存亡与病情进退；黄白辨寒热；有根无根辨虚实、胃气；润燥辨津液盈亏，均非辨别病邪深浅的主要依据，薄厚才是关键"},{"q":"牙齿光燥如石，多为","o":["胃津已伤","肾阴枯竭","胃火炽盛","阳明热盛，津液大伤","肾气旺盛，津液充足"],"a":3,"e":"牙齿光燥如石，是阳明热盛、里热炽盛、津液大伤、牙面失于津液濡润所致，常伴高热、大汗、大渴、便秘、舌红苔黄燥。胃津已伤虽可致口干，但程度较轻、不及如石之燥；肾阴枯竭牙齿多枯槁、松动、色黑，伴潮热；胃火炽盛以牙龈肿痛、口臭为主；肾气旺盛津液充足则牙齿润泽坚固，均与光燥如石不同"},{"q":"下列选项中，不属于闭经常见原因的是","o":["痰湿阴滞胞宫","气滞血瘀","寒凝血瘀","肝郁血热","肝肾不足"],"a":3,"e":"闭经多因肝肾不足、气血虚弱、阴虚血燥致血海空虚，或气滞血瘀、寒凝血瘀、痰湿阻滞胞宫致经隧不通，故痰湿阴滞胞宫、气滞血瘀、寒凝血瘀、肝肾不足皆为常见原因。肝郁血热多致月经先期、量多、色深红或崩漏，血热迫血妄行而非经闭，故不属于闭经的常见原因"},{"q":"以头晕头胀，或头痛剧烈，面红目赤，急躁易怒，失眠多梦，舌红苔黄，脉弦数为主要表现的证是","o":["肝血虚证","肝风内动证","肝郁气滞证","肝火炽盛证","肝胆湿热证"],"a":3,"e":"头晕头胀、头痛剧烈、面红目赤、急躁易怒、失眠多梦、舌红苔黄、脉弦数，是肝火炽盛、循经上攻头目、热扰心神之象，属肝火炽盛证。肝血虚见面色淡白、视力减退、肢体麻木、舌淡；肝风内动以抽搐、震颤、眩晕为主；肝郁气滞以胸胁胀痛、情志抑郁、脉弦为主，无明显火热；肝胆湿热以胁痛、口苦、黄疸、苔黄腻为主，均非肝火上炎的实热表现"},{"q":"以下不属于涩脉主病的是","o":["伤精","血少","气滞血瘀","夹痰夹食","阴盛气结"],"a":4,"e":"涩脉往来艰涩、如轻刀刮竹，主伤精、血少、气滞血瘀、夹痰夹食等，因精血亏少或邪气阻滞、脉道不畅所致。阴盛气结是结脉的主病（阴盛则气机郁结、脉来缓慢而止），非涩脉所主，故不属于涩脉主病。伤精、血少致脉道不充而涩，气滞血瘀、痰食内停致脉道受阻而涩，均为涩脉的常见主病"},{"q":"牙齿光燥如石者多属","o":["热极动风","胃阴亏损","肾虚，虚火上炎","阳明热甚、津液大伤","肾阴枯竭，精不上荣"],"a":3,"e":"牙齿光燥如石，多属阳明热甚、津液大伤，里热蒸腾、胃津耗竭、牙齿失润。热极动风以高热抽搐、角弓反张为主；胃阴亏损以口干、饥不欲食、舌红少苔为主，程度较轻；肾虚虚火上炎牙齿松动、隐隐作痛、潮热；肾阴枯竭精不上荣则牙齿枯槁、色黑、脱落，均非阳明热盛、津液骤伤的光燥如石"},{"q":"辨寒热的目的是","o":["辨病因","辨病性","辨病位","辨邪正盛衰","辨标本缓急"],"a":1,"e":"寒热是辨别疾病性质的两个纲领，寒证与热证反映机体阴阳偏盛偏衰，故辨寒热的目的在于辨病性。辨病因是求病因（如六淫、七情）；辨病位由表里完成；辨邪正盛衰由虚实完成；辨标本缓急是确定治疗先后，均非寒热二纲的作用。表里、寒热、虚实、阴阳分别主病位、病性、邪正、类别，寒热专主病性"},{"q":"嗜睡的主要病机是","o":["阳气不足","阳盛阴虚","阴阳两虚","阳虚阴盛","阴盛格阳"],"a":3,"e":"嗜睡是神疲欲睡、呼之能醒、醒后复睡，主要因阳气虚衰、阴气偏盛，阳不入阴、神失温养所致，故病机为阳虚阴盛。阳气不足虽是重要环节，但单纯阳虚未概括阴盛这一方面；阳盛阴虚、阴阳两虚非嗜睡主要病机；阴盛格阳是虚阳被格拒于外的危象，表现为真寒假热，均非嗜睡的阳虚阴盛。痰湿困脾所致嗜睡亦属阴盛之类"},{"q":"野外工作者面色偏黑，称为","o":["主色","善色","客色","常色","恶色"],"a":2,"e":"野外工作者因长期日晒、风吹等环境因素影响而面色偏黑，属随外界条件发生相应变化的正常肤色，称为客色。主色是个体一生不变的基本面色；常色是正常肤色的总称，包括主色与客色；善色、恶色是病色的分类，分别指病色润泽与枯槁，均非因环境而暂变的面色，故野外工作者面黑为客色"},{"q":"下列脉象除哪项外，脉位皆表浅","o":["浮脉","芤脉","濡脉","散脉","弱脉"],"a":4,"e":"浮脉轻取即得、芤脉浮大中空、濡脉浮而细软、散脉浮散无根，四者脉位均表浅、轻取可得。弱脉沉而细软、须重按始得，脉位在深层，故为例外。浮与散虽均表浅，但散脉浮散无根、至数不清；芤与濡虽浮，但芤中空、濡细软，各有特征，唯弱脉独沉，与其他四脉的浮浅之位相反"},{"q":"下列哪项宜诊断为心肺气虚证","o":["咳嗽气喘、自汗畏风","咳痰清稀、声低少气","咳喘心悸、神疲思睡","胸胁闷痛、咳唾益甚","呼多吸少、短气乏力"],"a":2,"e":"心肺气虚证是心肺两脏气虚，既有肺气不足、宣降失司之咳喘、气短，又有心气不足、心失所养之心悸、神疲，故咳喘心悸、神疲思睡宜诊为心肺气虚。咳嗽气喘、自汗畏风偏肺气虚卫表不固；咳痰清稀、声低少气为肺气虚；胸胁闷痛、咳唾益甚是饮停胸胁；呼多吸少、短气乏力是肾不纳气，均非心肺同病之象"},{"q":"下列各项，属于寒湿困脾证常见病因的是","o":["暴饮暴食","饮食肥甘生冷","思虑过度","劳倦内伤","久泻久痢"],"a":1,"e":"寒湿困脾因过食肥甘生冷、损伤脾阳，或涉水淋雨、居处潮湿，寒湿内侵、困阻脾运所致，故饮食肥甘生冷是其常见病因。暴饮暴食多致食积、胃脘痞满；思虑过度、劳倦内伤多致脾气虚或心脾两虚；久泻久痢多致脾虚或脾肾阳虚，均非寒湿困脾的直接常见病因。肥甘生冷助湿生寒，最易困遏脾阳"},{"q":"“直中”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经证候同时出现","一经证候未罢，又出现另一经证候","外邪入犯三阴而出现三阴证候"],"a":4,"e":"直中指外邪不经过三阳经传变，直接侵入三阴经而出现三阴证候，多因正气亏虚、邪气直入，病势较重。两经或三经证候同时出现是合病；一经证候已罢、继见另一经是传经；互为表里的阴阳两经证候同时出现是并病；一经证候未罢又见另一经亦属并病范畴，均与外邪直犯三阴的直中不同"},{"q":"实证的临床表现常见","o":["神疲乏力","自汗","五心烦热","腹部绞痛","畏寒"],"a":3,"e":"实证是邪气亢盛、正气未虚，以邪实、有余为特征，常见腹部绞痛、疼痛拒按、高热、烦躁、便秘等。神疲乏力、自汗多属气虚；五心烦热是阴虚内热；畏寒多属阳虚或寒证，均为虚象或寒象，不属实证。腹部绞痛因实邪（寒、食、虫、石）阻滞气机、不通则痛，是实证的常见表现"},{"q":"浮滑脉的主病多为","o":["痰热内结","饮食停滞","湿热内蕴","风痰","风寒袭表"],"a":3,"e":"浮脉主表、主风，滑脉主痰，浮滑相兼多为风痰上扰或风痰袭表，如眩晕、头晕、咳痰、胸闷，故主风痰。痰热内结多见滑数或黄腻苔；饮食停滞多见滑脉或促脉，不浮；湿热内蕴多见滑数、濡数或黄腻苔；风寒袭表多见浮紧脉，均与浮滑主风痰不同。浮以候风、滑以候痰，二者合参即风痰"},{"q":"疮疡红肿高大，根盘紧束，灼热疼痛为","o":["痈","疽","疔","疖","丹毒"],"a":0,"e":"疮疡红肿高大、根盘紧束、灼热疼痛，属阳证疮疡，称为痈，多因湿热火毒蕴结、气血壅滞不通所致。疽为阴证，漫肿无头、皮色不变、不热少痛；疔形小如粟、根深坚硬、麻木痒痛，病情凶险；疖形小而浅、红肿热痛、根脚浮浅、易溃易敛；丹毒为皮肤焮红成片、色如涂丹、边缘清楚、灼热，均与红肿高大根盘紧束的痈不同"},{"q":"因气候环境的变化而使面色发生相应变化的正常肤色称为","o":["客色","主色","常色","善色","恶色"],"a":0,"e":"因季节气候、生活环境变化而相应改变的正常肤色，称为客色，如夏日面稍赤、冬日面稍白、野外工作者面偏黑，均属生理性变异。主色是个体终身不变的基本肤色；常色是正常肤色的统称，含主色与客色；善色、恶色是病色的润泽与枯槁之分，均非因环境而变的肤色，故为客色"},{"q":"下列各项不属于中焦病证的是","o":["腹满便秘","胸脘痞闷","大便不爽","呼吸气粗","舌红少苔"],"a":4,"e":"中焦病证包括阳明燥热与太阴湿热：阳明腑实见腹满便秘、身热、口渴；太阴湿热见胸脘痞闷、大便不爽、身热不扬，呼吸气粗可由中焦热盛、气机壅滞所致。舌红少苔是下焦肝肾阴虚、虚热内扰的舌象，属下焦病证，不属中焦，故为例外。三焦辨证以上焦肺、中焦脾胃、下焦肝肾分候，舌红少苔显然归于下焦阴虚"},{"q":"下列属于特征相反的脉象是","o":["沉脉与伏脉","洪脉与实脉","濡脉与浮脉","滑脉与涩脉","弦脉与紧脉"],"a":3,"e":"滑脉往来流利、应指圆滑如珠走盘，涩脉往来艰涩、滞涩不畅如轻刀刮竹，二者一利一涩，脉象特征完全相反。沉脉与伏脉均属深位、仅程度不同；洪脉与实脉均脉力充实；濡脉与浮脉均居浮位；弦脉与紧脉均紧张有力，皆非相反。滑与涩在流利度上截然对立，是典型的相反脉象"},{"q":"肺气不得宣散，上逆于喉间，气道窒塞，呼吸急促称之为","o":["喘证","哮证","上气","短气","少气"],"a":2,"e":"上气是肺气不得宣散、上逆喉间、气道窒塞、呼吸急促而气机上逆之象，故题干所叙即为上气。喘证以呼吸困难、张口抬肩、难以平卧为主；哮证以喉中哮鸣有声、反复发作为特征；短气是呼吸短促、不相接续但无明显上逆；少气是气短声低、言语无力，均非肺气上逆、气道窒塞的上气"},{"q":"沉涩脉主病常为","o":["肝郁气滞","水饮内停","血虚肝郁","寒凝血瘀","阳明热甚"],"a":3,"e":"沉脉主里、主寒，涩脉主血瘀、血少，沉涩相兼为寒邪内盛、血行凝滞、脉道不畅，故主寒凝血瘀，常伴疼痛固定、遇寒加重、舌紫暗。肝郁气滞多见弦脉；水饮内停多见弦脉或沉滑；血虚肝郁见细弦或细涩但脉不沉；阳明热甚见洪数或滑数，均非沉涩所主的里寒血瘀之证"},{"q":"下列各项，不属于水停证临床表现的是","o":["水肿按之凹陷不易起","小便短少不利","身体困重","舌淡胖苔白滑，脉濡缓","咳吐清稀痰涎"],"a":4,"e":"水停证是水液内停、泛溢肌肤，常见水肿按之凹陷难起、小便短少不利、身体困重、舌淡胖苔白滑、脉濡缓。咳吐清稀痰涎是水饮停积于肺、肺气上逆之饮证（支饮、痰饮）表现，病位在肺，与泛溢肌肤的水停证不同，故不属水停证临床表现。水肿、尿少、身重、舌胖苔白滑均是水液泛溢、停聚体表的征象"},{"q":"切脉指法中，不轻不重，委曲求之，称为","o":["举","总按","按","寻","单按"],"a":3,"e":"切脉指法中，不轻不重、委曲求之、左右前后推寻以体察脉象，称为寻法，是介于举（浮取）、按（沉取）之间的指法。举是轻取皮肤；按是重按筋骨；总按是三指同按寸关尺；单按是单指按一部，均非委曲求之的寻法。寻法用于仔细揣摩脉的形态、节律与力量变化"},{"q":"下列哪项最不可能出现在心阳暴脱证","o":["心悸怔忡","脉数极而无力","心胸疼痛","四肢厥冷","冷汗淋漓"],"a":1,"e":"心阳暴脱因心阳骤然衰亡、温运停滞，常见心悸怔忡、心胸剧痛、四肢厥冷、冷汗淋漓、面色苍白、脉微细欲绝或结代。脉数极而无力主热盛伤津、阴液将竭或虚阳浮越，非心阳暴脱的典型脉象，故最不可能出现。四肢厥冷、冷汗淋漓、心悸怔忡、心胸疼痛均紧扣心阳暴脱的阳气骤亡、胸阳不振"},{"q":"观察病人面色的关键，在于区分","o":["主色与客色","善色与恶色","常色与病色","客色与病色","主色与病色"],"a":1,"e":"观察病人面色，关键在于区分善色与恶色：善色五色鲜明润泽，说明气血未衰、病情轻、预后好；恶色晦暗枯槁，说明精气已伤、病情重、预后差。主色与客色是常色的分类，辨个体与环境的正常面色；常色与病色是正常与异常之别；客色与病色、主色与病色均非观察病色的关键，善恶之辨才直接关系病情轻重与预后判断"},{"q":"用手指掌面或手掌轻轻接触病人局部皮肤，以了解肌肤的情况称为","o":["按法","触法","摸法","压法","叩法"],"a":1,"e":"用手指掌面或手掌轻触病人局部皮肤，以了解肌肤的寒热、润燥、肿胀等情况，称为触法，是切诊中触诊的基本手法。按法是较重用力按压以探查深部；摸法、压法侧重触摸、按压局部形态与压痛；叩法是以手指叩击体表、听声音辨病位，均与轻轻接触皮肤了解肌肤情况的触法不同。触法重在轻触体察肌肤表象"},{"q":"下列各项，属于脾虚气陷证临床表现的是","o":["脘腹重坠，食后更甚","腹痛喜暖喜按","畏寒肢冷","身热不扬，汗出不解","便血"],"a":0,"e":"脾虚气陷证因脾气虚弱、升举无力、中气下陷，常见脘腹重坠、食后更甚、肛门坠胀、久泻脱肛或内脏下垂，伴神疲乏力、头晕。腹痛喜暖喜按是脾胃虚寒；畏寒肢冷是阳虚；身热不扬、汗出不解是湿温或湿热；便血多属脾不统血或大肠湿热，均非中气下陷、升举无力的重坠表现，故脘腹重坠食后更甚为脾虚气陷所独有"},{"q":"多食易饥，口臭便秘者，可见于","o":["胃火炽盛","食滞胃脘","胃气不足","胃阴亏虚","肝气犯胃"],"a":0,"e":"多食易饥、口臭、便秘，是胃火炽盛、腐熟功能亢进、胃热上蒸、津伤肠燥所致，常伴口渴、牙龈肿痛。食滞胃脘以脘腹胀满、嗳气酸腐、拒按、泻后痛减为主；胃气不足则食少纳呆；胃阴亏虚饥不欲食、口干不欲饮；肝气犯胃以胃脘胀痛、情志相关、嗳气为主，均非胃火炽盛的消谷善饥、口臭便秘"},{"q":"虚实夹杂不包括","o":["表虚里实证","上实下虚证","虚实并重证","虚中夹实证","实证转虚证"],"a":4,"e":"虚实夹杂是虚证与实证同时并见，包括表虚里实、上实下虚、虚实并重、虚中夹实及实中夹虚等，邪正相持、虚实错杂。实证转虚证是邪气渐退、正气受损，由实转虚的动态转化过程，属于证候转化而非虚实同时并见的夹杂，故不属于虚实夹杂。虚实夹杂贵在同时并见，转化则强调先后演变，二者性质不同"},{"q":"最不易见于肺热炽盛证的症状是","o":["咳嗽气喘","气息灼热","大便秘结","咽喉肿痛","腥臭脓痰"],"a":4,"e":"肺热炽盛证因热邪壅肺、肺失宣降、气机上逆，见咳嗽气喘、气息灼热、咽喉肿痛，肺与大肠相表里、热移大肠则大便秘结。腥臭脓痰是热毒壅肺、血肉腐化为脓的肺痈特征，需经热盛肉腐成脓的阶段，非单纯肺热炽盛证所见，故最不易出现。咳嗽、气喘灼热、咽痛、便秘均紧扣肺热壅盛、气逆津伤"},{"q":"战汗后向愈的表现是","o":["精神萎靡","身热不减","烦躁不安","脉静身凉","脉象疾数"],"a":3,"e":"战汗是正邪剧争的表现，汗后若脉象平和、身热消退、四肢转温、精神安静，即脉静身凉，提示邪去正复、疾病向愈。精神萎靡、烦躁不安是正虚或邪热内扰；身热不减、脉象疾数说明邪热未退、正气不支，为病情恶化的表现，均非向愈之象。脉静身凉是战汗后正胜邪却、病情转机的佳兆"},{"q":"暴注下泻，色黄味臭者属于","o":["湿热蕴脾证","大肠湿热证","肝胆湿热证","肠热腑实证","肠虚滑泻证"],"a":1,"e":"暴注下泻、泻物色黄味臭，是湿热之邪下注大肠、传导失司、热迫津泄，属大肠湿热证，常伴腹痛、肛门灼热、里急后重。湿热蕴脾以脘腹痞闷、纳呆、身重、苔黄腻为主，泻下不若此急暴；肝胆湿热以胁痛、口苦、黄疸为主；肠热腑实以腹满硬痛、便秘为主；肠虚滑泻为久泻滑脱、味不臭，均与暴注黄臭的湿热下注不同"},{"q":"往来流利，应指圆滑，如珠走盘的脉象是","o":["弦脉","滑脉","数脉","涩脉","细脉"],"a":1,"e":"往来流利、应指圆滑、如珠走盘，是滑脉的脉象特征，主痰湿、食积、实热及妊娠。弦脉端直以长、如按琴弦；数脉一息五六至、重在速率；涩脉往来艰涩、如轻刀刮竹，与滑脉相反；细脉脉细如线、应指明显，均与流利圆滑的滑脉不同。如珠走盘是滑脉最为形象的特征描述"},{"q":"下列不属实证的是","o":["食积","内燥","气滞","水停","血瘀"],"a":1,"e":"实证是邪气亢盛、正气未衰，食积、气滞、水停、血瘀皆由有形实邪或气机阻滞所致，属实证范畴。内燥是津液亏少、濡润失职、血脉不充，属虚证（津液亏虚）或阴虚内热之类，正气、津液不足而非邪气有余，故不属实证。食积、气滞、水停、血瘀均为邪实、有余之病理，与内燥的津亏不足相对"},{"q":"弹石脉的脉象是","o":["短小坚搏，如循薏苡子","如屋漏残滴，良久一滴","如釜中沸水，浮泛无根","脉来乍疏乍密，如解乱绳状","脉在筋骨之间，如指弹石"],"a":4,"e":"弹石脉在筋骨之间、坚硬如指弹石、无柔和之象，是肾气竭绝、胃气已无的死脉。短小坚搏、如循薏苡子是转豆等怪脉之象，非弹石；如屋漏残滴、良久一滴是屋漏脉；如釜中沸水、浮泛无根是釜沸脉；脉来乍疏乍密、如解乱绳状是解索脉，均与脉在筋骨、坚硬如石的弹石脉不同"},{"q":"下列各项，不属中医诊断的内容的是","o":["收集病情资料","判断健康与否","作出疾病诊断","辨别确定证名","提出治疗原则"],"a":4,"e":"中医诊断学的任务包括运用诊法收集病情资料、判断健康与否、作出疾病诊断（辨病）及辨别确定证名（辨证），为防治提供依据。提出治疗原则属于治疗学、方药学的范畴，是诊断之后的论治环节，不属诊断本身的内容。诊法、辨病、辨证构成中医诊断的核心，均围绕认识疾病展开，唯论治不属于诊断"},{"q":"诊脉时指力从轻到重，从重到轻，左右前后推寻，以寻找脉动最明显的特征，称为","o":["浮取","中取","沉取","寻法","总按"],"a":3,"e":"诊脉时指力从轻到重、从重到轻，并左右前后推寻，以寻找脉动最明显的特征，称为寻法，是举、按之间细致体察脉象的手法。浮取（举）仅轻按皮肤；中取按至肌肉；沉取（按）重按筋骨；总按是三指同时切按寸关尺，均非这种轻重变化、前后推寻的操作，故为寻法"},{"q":"最应归属阴证的是","o":["里虚寒证","里虚热证","表虚寒证","表虚热证","里实寒证"],"a":0,"e":"阴证以里、虚、寒为属性，里虚寒证三者兼备，故最应归属阴证。表虚寒证虽虚寒但病位在表，属阳中之阴；里实寒证病位在里而邪气实，不属虚证。里虚热证、表虚热证均见热象，归于阳证"},{"q":"咽喉间起灰白色假膜，不易剥离，剥则出血，随即复生者，称为","o":["白喉","乳蛾","瘿瘤","烂乳蛾","痰核"],"a":0,"e":"白喉为疫毒之邪壅于咽喉，假膜灰白、不易剥离、剥则出血且随即复生，是其特点。乳蛾为咽喉两侧扁桃体红肿疼痛、化脓，无假膜；瘿瘤为颈前肿块随吞咽上下移动，与咽喉假膜无关；痰核为皮下痰湿结块"},{"q":"饭后嗜睡，神疲倦怠，食少纳呆者多为","o":["痰湿困脾","中气不足","心肾阴虚","热入心包","心肾阳虚"],"a":1,"e":"中气不足则脾胃运化失职，食少纳呆，饭后气血归于脾胃、脑失所养，故嗜睡神疲。痰湿困脾亦有嗜睡，但必见头身困重、胸闷苔腻；心肾阳虚多见精神萎靡、畏寒肢冷而无食后嗜睡特点"},{"q":"解索脉的主病是","o":["肾气竭绝","肾与命门之气皆亡","三阳热极，阴液枯竭","三阴寒极，阳亡于外","胃气营卫将绝"],"a":1,"e":"解索脉脉来散乱、乍疏乍密如解乱绳，主肾与命门之气皆亡，为危重败脉。肾气竭绝仅言肾气而不及命门，概括不全；三阳热极、阴液枯竭多见细数疾脉，三阴寒极、阳亡于外多见脉微欲绝，均无散乱如解索之象"},{"q":"“望色十法”中判断病情之轻重的纲领是","o":["泽夭","清浊","微甚","散抟","浮沉"],"a":0,"e":"望色十法中浮沉辨表里、清浊辨阴阳、微甚辨虚实、散抟辨新久，泽夭辨病情轻重。泽为明润、夭为枯槁，故泽夭是判断轻重预后之纲领。散抟主病之新久聚散，与轻重判断不同；浮沉仅定病位深浅"},{"q":"下列哪项不是望头部情况的主要诊察范畴","o":["脑的病变","肾的病变","肺的病变","精气盛衰","血的虚实"],"a":2,"e":"头为诸阳之会，望头主要察脑病变、肾精盛衰及血的虚实，因肾藏精、其华在发，血气上荣于头。肺的病变主要通过望鼻、咽喉及痰涕等诊察，不属望头范畴；精气盛衰可从头颅形态、发泽体现"},{"q":"下列哪项提示病多凶险，预后不佳","o":["络脉仅显示于风关","络脉达于气关","透关射甲","络脉达于命关","络脉沉隐"],"a":2,"e":"小儿指纹由风关、气关、命关渐次透达，透关射甲指指纹直透指甲，提示病邪深入、病情凶险、预后不佳。络脉仅显于风关主病轻邪浅；达于气关主病进；达于命关主病危，但仍较透关射甲为轻"},{"q":"问现在症的方法，首先应该是","o":["问寒热情况","按十问内容逐项询问","根据症状进行询问","根据体征进行询问","抓住主症展开询问"],"a":4,"e":"问现在症当先抓住主症，围绕主症展开询问，再按十问内容补充，方不致漫无边际。按十问逐项罗列易平均用力、抓不住重点；根据症状或体征零星询问缺乏系统，均非首先之法"},{"q":"精神萎靡，意识模糊的是","o":["得神","少神","失神","假神","神乱"],"a":2,"e":"失神表现为精神萎靡、意识模糊、反应迟钝，提示脏腑精气亏虚、病情较重。少神仅精神不振、倦怠乏力而意识清楚；假神为危重之人突然精神好转，属回光返照；神乱则见躁狂、抑郁等神志异常"},{"q":"古称谓“哕”者即","o":["干呕","恶心","嗳气","呃逆","呕吐"],"a":3,"e":"哕为古称，即呃逆，因胃气上逆、膈肌痉挛而喉间呃呃连声。干呕为有声无物；嗳气为胃中气体上出、声长而缓；恶心为欲呕未吐、胃气上逆之轻者；呕吐则有物有声"},{"q":"由于气候影响，平脉在春天可见","o":["浮","沉","洪","弦","迟"],"a":3,"e":"春阳气升发，脉应之而见弦，故平脉春天可见弦。浮为秋脉，沉为冬脉，洪为夏脉，迟为寒象而非春之平脉，均非春季应时之脉"},{"q":"主元气离散之脉是","o":["散脉","弱脉","微脉","芤脉","细脉"],"a":0,"e":"散脉浮散无根、至数不齐，主元气离散，为脏腑精气将绝之候。弱脉主气血两虚，微脉主阴阳气血俱虚，芤脉主失血伤阴，均属虚脉但无离散无根之象"},{"q":"以下不属于弦脉主病的是","o":["痛证","疟疾","胆病","湿证","痰饮"],"a":3,"e":"弦脉主肝胆病、痛证、痰饮、疟疾，脉端直以长如按琴弦。湿证多见濡脉、缓脉，以脉细软或迟缓为主，非弦脉所主；其余痛证、疟疾、胆病、痰饮皆在弦脉主病之列"},{"q":"燥邪伤肺，或肺阴亏虚者，其痰常表现为","o":["痰中带血","痰少而黏难以咯出","咯吐脓血痰","痰黄质黏而稠","痰多色白滑易咯"],"a":1,"e":"燥邪伤肺或肺阴亏虚，津液不足、肺失濡润，故痰少而黏、难以咯出。痰中带血多见肺阴虚络伤或肺热；咯吐脓血痰为肺痈；痰黄质稠属热痰；痰多色白滑易咯为湿痰"},{"q":"下列各项说法，错误的是","o":["围绕主要病痛问诊","运用医学术语问诊","耐心听患者陈述病情","对危重病人要扼要问诊","现在症是当前诊断的主要依据"],"a":1,"e":"问诊应使用通俗易懂语言，避免医学术语造成患者误解，故“运用医学术语问诊”错误。围绕主要病痛问诊、耐心听取陈述、危重者扼要询问均属正确方法；现在症确为当前诊断主要依据"},{"q":"月经提前7天以上，量多、色红、质稠者，属于","o":["气虚","血热","血虚","血寒","血瘀"],"a":1,"e":"血热内扰，迫血妄行，故月经提前量多、色红质稠。气虚不摄血则经行提前而量多色淡质稀；血寒多致经期延后、色暗有块；血虚、血瘀常表现为经少、色暗或痛经"},{"q":"脉来时有一止，止有定数，良久方来的是","o":["代脉","促脉","涩脉","结脉","动脉"],"a":0,"e":"代脉脉来一止、止有定数、良久方来，主脏气衰微。促脉数而中止、止无定数；结脉缓而中止、止无定数；涩脉往来艰涩不畅而无规律歇止；动脉滑数有力如豆，均无定数之止"},{"q":"虚证的形成不包括","o":["外邪直中","饮食失调","思虑太过","悲哀卒恐","过度劳倦"],"a":0,"e":"虚证多因饮食失调、思虑太过、悲哀卒恐、过度劳倦等致正气亏虚。外邪直中多邪气盛实，发为实证，不属虚证成因；其余四项均耗伤气血阴阳，为虚证常见来源"},{"q":"以下不属于沉脉类的是","o":["沉脉","涩脉","伏脉","牢脉","弱脉"],"a":1,"e":"沉脉类包括沉、伏、牢、弱，共同特点为脉位深沉、重按始得。涩脉往来艰涩、如轻刀刮竹，属虚实夹杂之脉，不以脉位深沉为特征，故不属沉脉类"},{"q":"燥热伤津常出现","o":["口黏","口苦","口酸","口甜","口涩"],"a":4,"e":"燥热伤津、津液不能上承于口，故口涩。口苦多属肝胆火旺；口甜为脾胃湿热或消渴；口黏为湿邪困脾；口酸多为肝热或食积内停，均与燥热伤津无涉"},{"q":"下列除哪项外均为至数不齐的脉象","o":["散脉","动脉","促脉","结脉","代脉"],"a":1,"e":"散脉至数不齐，促、结、代皆有心搏歇止而节律不整，均属至数不齐之脉。动脉脉形如豆、滑数有力，速率虽快但节律整齐，无歇止，故不属至数不齐"},{"q":"脾胃虚弱导致脘腹疼痛的特点是","o":["隐痛","灼痛","窜痛","胀痛","刺痛"],"a":0,"e":"脾胃虚弱、气血不足，脘腹失于温养，故疼痛隐隐、喜温喜按。灼痛多属热邪或阴虚火旺；刺痛为瘀血；胀痛多属气滞；窜痛多为气机走窜或风邪，均非脾胃虚弱之象"},{"q":"下列选项中，均具有脉位深沉特点的脉象是","o":["牢脉，实脉，洪脉，弦脉","洪脉，实脉，弦脉，芤脉","牢脉，革脉，弦脉，弱脉","弱脉，革脉，伏脉，牢脉","牢脉，弱脉，沉脉，伏脉"],"a":4,"e":"牢、弱、沉、伏均脉位深沉，须重按始得，故共具脉位深沉特点。实脉、洪脉、弦脉脉位不沉；芤脉浮大中空、革脉浮而搏指，均居浮位，不属深沉之列"},{"q":"下列各项，问带下最无意义是","o":["天数","量的多少","颜色","质的变化","气味"],"a":0,"e":"问带下重在量、色、质、气味，以辨寒热虚实及湿热下注。天数对辨证无直接意义，最无价值；带下量多色白质稀多属脾虚寒湿，色黄质稠臭秽多为湿热下注"},{"q":"胸胁部胀闷或痛，呼吸、咳嗽或转侧时牵引作痛者属于","o":["风水搏肺证","肺热炽盛证","痰热壅肺证","寒痰阻肺证","饮停胸胁证"],"a":4,"e":"饮停胸胁、气机阻滞，故胸胁胀闷或痛，呼吸、咳嗽、转侧时牵扯作痛，是为悬饮。风水搏肺以水肿、恶风为主；肺热炽盛见发热咳黄痰；痰热壅肺见痰黄稠；寒痰阻肺见咳白清稀痰"},{"q":"痰火扰心的狂证可出现","o":["哭笑无常，焦虑恐惧","神昏谵语","登高而歌，弃衣而走","突然昏仆，四肢抽动","失眠惊悸"],"a":2,"e":"痰火扰心，神明被蒙，狂证可见登高而歌、弃衣而走、躁妄不羁。神昏谵语多属热入心包或热盛神昏；哭笑无常、焦虑恐惧多见癫证或脏躁；突然昏仆、四肢抽动为痫病"},{"q":"初起如粟如米，根脚坚硬较深，麻木或发痒，顶白而痛者，称为","o":["痈","疽","疹","疖","疔"],"a":4,"e":"疔初起如粟如米、根脚坚硬较深、麻木或发痒、顶白而痛，好发于颜面手足。痈红肿高大、根盘紧束；疽漫肿无头、皮色不变；疖形小而浅、红肿热痛、易溃易敛；疹为皮肤小红点"},{"q":"散脉的主病是","o":["元气离散","气血两虚","诸虚劳损","失精亡血","阴盛气结"],"a":0,"e":"散脉浮散无根、节律不齐，主元气离散。气血两虚多见细弱脉；诸虚劳损多见虚细脉；失精亡血多见芤脉或革脉；阴盛气结多见沉脉或结脉，均非散脉所主"},{"q":"口干微渴，发热恶寒，咽喉肿痛者，多见于","o":["温病卫分证","阳明经证","消渴病","水逆证","温病营分证"],"a":0,"e":"口干微渴、发热恶寒、咽喉肿痛为温邪犯肺卫之象，属温病卫分证。阳明经证但热不寒、大渴大汗；消渴以多饮多尿消瘦为主；水逆证见饮水即吐；营分证身热夜甚、神昏谵语"},{"q":"瞪目直视，多为","o":["有机磷农药中毒","阿托品中毒","脏腑精气衰竭","肝风内动","瘿病"],"a":2,"e":"瞪目直视、目睛固定不灵，为脏腑精气衰竭、病情危重之象。肝风内动多见目斜视、上视或眼球颤动；有机磷中毒见瞳孔缩小；阿托品中毒见瞳孔散大；瘿病为颈前肿块"},{"q":"下列各项，与绝汗无关的是","o":["面色苍白","恶寒战栗","冷汗淋漓","呼吸气微","肢厥脉微"],"a":1,"e":"绝汗为病情危重、阳气暴脱之汗，见冷汗淋漓、呼吸气微、肢厥脉微、面色苍白。恶寒战栗为战汗先兆，邪正剧争，汗出后热退脉静，非绝汗表现"},{"q":"脏躁可表现为","o":["淡漠痴呆","猝然昏仆","焦虑恐惧","狂躁不安","蒙蔽清窍"],"a":2,"e":"脏躁多因心阴不足、肝失濡养，可见焦虑恐惧、精神恍惚、悲伤欲哭。淡漠痴呆多属痰蒙心神或癫病；猝然昏仆为痫病；狂躁不安属痰火扰心之狂证；蒙蔽清窍为痰浊闭窍"},{"q":"一个规范的证名，应当包括病位和","o":["病因","病机","病性","病势","连接词"],"a":2,"e":"规范证名由病位与病性两部分构成，如“肝胆湿热”中肝胆为病位、湿热为病性。病因、病机、病势并非证名必备要素；连接词仅起语法作用，不决定证名内涵"},{"q":"花剥苔一般提示","o":["胃气阴两伤","湿遏热邪","脾虚伤食","胃肠有热","痰浊未化"],"a":0,"e":"花剥苔为舌苔部分剥落、余处仍存，主胃气阴两伤。湿遏热邪多见苔白腻或黄腻；脾虚伤食见苔厚腻或剥落不均；胃肠有热见黄苔；痰浊未化见腻苔，均非花剥苔之典型提示"},{"q":"胆郁痰扰证的情志变化表现为","o":["多思善虑","抑郁不乐","喜笑不休","胆怯易惊","悲忧不解"],"a":3,"e":"胆郁痰扰，胆气不宁、痰热内扰，故见胆怯易惊、惊悸不寐。多思善虑、抑郁不乐多属肝郁脾虚或心脾两虚；喜笑不休属喜伤心或痰火扰心；悲忧不解多属肺气虚或脏躁"},{"q":"微脉的主病是","o":["气虚血少","气虚有湿","阴阳气血俱虚","诸虚诸湿","阳气有余"],"a":2,"e":"微脉极细极软、似有似无，主阴阳气血俱虚、阳气衰微。气虚血少多见细脉；气虚有湿多见濡脉；诸虚诸湿多见虚细或濡缓；阳气有余当见实热之脉，非微脉所主"},{"q":"肠虚滑泻证的辨证要点是大便失禁与下列何项共见","o":["气虚症状","血虚症状","阳虚症状","阴虚症状","津亏症状"],"a":2,"e":"肠虚滑泻因脾肾阳虚、大肠失于固摄，辨证要点为大便失禁或滑泻无度与阳虚症状并见。气虚、血虚、阴虚、津亏虽均属虚，但不具温煦失职之里寒表现，非本证要点"},{"q":"下列哪个病证不属于痰蒙心神证临床表现","o":["神志抑郁","狂","痴呆","癫病","痫病"],"a":1,"e":"痰蒙心神见神志抑郁、痴呆、癫病、痫病，以静、抑为特点。“狂”属痰火扰心，表现为躁狂妄动，与痰蒙心神之静证相反，故不属于其临床表现"},{"q":"因外界因素变动而发生相应变化的肤色是","o":["主色","客色","善色","恶色","病色"],"a":1,"e":"客色为随季节、气候、环境等外界因素变动而相应改变的肤色，属生理范围。主色为个体一生不变的固有肤色；善色、恶色为病色之光泽好坏；病色即病理肤色"},{"q":"阴虚或气阴两虚导致的汗出是","o":["自汗","盗汗","战汗","半身汗","绝汗"],"a":1,"e":"盗汗为睡时汗出、醒后汗止，因阴虚内热或气阴两虚、卫外不固所致。自汗为白天清醒时汗出，多属气虚；战汗为邪正剧争、先寒战后汗出；绝汗为阳气暴脱之大汗淋漓"},{"q":"湿邪困遏作痛的特点是","o":["重痛","胀痛","冷痛","隐痛","刺痛"],"a":0,"e":"湿邪重浊黏滞，困遏气机，故疼痛沉重、固定不移，是为重痛。胀痛属气滞；冷痛属寒邪或阳虚；隐痛属虚证；刺痛属瘀血，均与湿邪困遏无关"},{"q":"下列目形见于脏腑精气衰竭的是","o":["眼窝微陷","眼窝深陷","眼球突出","针眼","眼丹"],"a":1,"e":"眼窝深陷为脏腑精气衰竭、津液亏耗之象，多属危重。眼窝微陷可见于正常或轻度津伤；眼球突出多属瘿病或肺胀；针眼、眼丹为眼睑局部化脓性病变"},{"q":"肝郁气滞证与肝阳上亢证均可见有","o":["情志抑郁","烦躁易怒","胁肋疼痛","脉细数","舌体淡白"],"a":2,"e":"肝郁气滞与肝阳上亢均可因肝失疏泄、肝气郁滞而见胁肋疼痛。情志抑郁仅见于肝郁气滞；烦躁易怒多属肝阳上亢或肝火；脉细数、舌淡白皆非两者共有"},{"q":"对诊断肺肾阴虚证最有意义的是","o":["咳嗽痰少、声音嘶哑","腰膝酸软、骨蒸潮热","舌红少苔、脉象细数","颧红咽干、月经不调","咳痰带血、遗精盗汗"],"a":4,"e":"肺肾阴虚见咳痰带血、遗精盗汗，兼顾肺失清肃与肾失封藏，最具诊断意义。咳嗽痰少声嘶、腰膝酸软潮热、舌红少苔、颧红咽干等仅反映肺或肾单一脏腑病变，特异性不足"},{"q":"以下不属于代脉主病的是","o":["风证","痛证","虚证","惊恐","食滞"],"a":4,"e":"代脉主脏气衰微，亦可见于风证、痛证、惊恐等致气血运行失常。食滞多见滑脉或腻脉，与代脉之歇止定数无关，故不属代脉主病"},{"q":"久流腥臭浊涕，状如鱼脑者，多为","o":["肺痈","肺热","鼻渊","瘟疫","肺痿"],"a":2,"e":"鼻渊因风热或胆腑郁热上犯鼻窍，见久流腥臭浊涕、状如鱼脑、鼻塞头痛。肺痈见咳吐脓血腥臭痰；肺热见发热咳黄痰；瘟疫为传染性热病；肺痿见咳吐浊唾涎沫"},{"q":"紫舌多主","o":["外感风热表证","血行不畅","阴虚火旺","气血不足","里热亢盛"],"a":1,"e":"紫舌主血行不畅，或寒凝血瘀、或热壅血滞，舌色青紫。外感风热表证多见舌尖偏红；阴虚火旺见舌红少苔；气血不足见舌淡；里热亢盛见舌红苔黄"},{"q":"喜伤证的临床表现有","o":["善悲喜哭","喜笑不休","胆怯心悸","胸闷胁胀","二便失禁"],"a":1,"e":"喜伤心，喜证可见喜笑不休、心神涣散。善悲喜哭多属脏躁或心虚；胆怯心悸属胆郁痰扰或心胆气虚；胸闷胁胀属肝郁气滞；二便失禁多属恐伤肾或下焦失固"},{"q":"寸口诊法始见于","o":["《内经》","《难经》","《脉经》","《伤寒论》","《濒湖脉学》"],"a":0,"e":"寸口诊法最早记载于《内经》，如“肺朝百脉”“气口独为五脏主”等论。《难经》在此基础上明确提出“独取寸口”；《脉经》为脉学专著；《伤寒论》重在辨证论治；《濒湖脉学》为后世脉学著作"},{"q":"下列哪项不属于腻苔的特征","o":["苔质疏松浮浅","苔质颗粒细腻致密","中间厚边周薄","融合成片","紧贴舌面，揩之不去"],"a":0,"e":"腻苔颗粒细腻致密、紧贴舌面、揩之不去、中间厚边缘薄，主湿浊痰饮。“苔质疏松浮浅”为腐苔特征，揩之可去，与腻苔致密紧贴相反，故不属腻苔特征"},{"q":"《景岳全书》中“阴挺”指","o":["阴囊肿大","阴部湿疹","子宫脱垂","脱肛","肛痈"],"a":2,"e":"《景岳全书》所称“阴挺”指子宫脱垂，因气虚下陷、带脉失约所致。阴囊肿大、阴部湿疹、脱肛、肛痈各有专名，均非阴挺所指"},{"q":"下列哪项不属于心病的常见症状","o":["怔忡","心痛","健忘","神识错乱","背痛"],"a":4,"e":"心病常见怔忡、心痛、健忘、神识错乱等，因心主血脉、主神明。背痛多与太阳经、督脉或肺有关，不属心病常见症状；其余皆与心之血脉神明功能相关"},{"q":"下列哪项不属于心气虚证的常见症状","o":["心悸","心烦","胸闷","气短","自汗"],"a":1,"e":"心气虚见心悸、胸闷、气短、自汗、神疲乏力，因心气不足、鼓动无力。心烦多属心火亢盛或心阴虚火扰，非心气虚常见症状，故应排除"},{"q":"下列何证表现为喘声低微，呼吸短促难续，得一长息为快，动则喘甚","o":["风寒袭肺","痰湿阻肺","痰热壅肺","肺肾气虚","肺脾气虚"],"a":3,"e":"肺肾气虚、肾不纳气，故喘声低微、呼吸短促难续、深吸为快、动则喘甚。风寒袭肺、痰湿阻肺、痰热壅肺皆属邪实气壅之喘，声高气粗；肺脾气虚虽虚但无明显呼多吸少"},{"q":"下列除哪项外，都可与肾精亏虚有关","o":["鼻柱塌陷，眉毛头发脱落","目胞色黑晦暗","耳郭瘦薄","牙根宣露","齿摇发脱"],"a":0,"e":"鼻柱塌陷、眉毛头发脱落为疠风（麻风）等所致，与肾精亏虚无关。目胞色黑晦暗、耳郭瘦薄、牙根宣露、齿摇发脱皆因肾精不足、不能上荣于五官"},{"q":"下列不是气血两虚证的临床表现的是","o":["少气懒言","肢体麻木","头晕目眩","舌有紫斑","唇甲色淡"],"a":3,"e":"气血两虚见少气懒言、肢体麻木、头晕目眩、唇甲色淡，因气虚推动无力、血虚濡养不足。舌有紫斑主瘀血内停，非气血两虚之象，故不属其临床表现"},{"q":"脾病的常见面色是","o":["白色","黄色","黑色","青色","红色"],"a":1,"e":"脾主运化，脾病常见面色萎黄或黄，因气血生化不足、湿邪内蕴。白色多属肺、虚、寒、失血；黑色属肾；青色属肝；红色属心或热"},{"q":"肾阳虚衰、阴寒凝滞，面色多为","o":["面色黑而淡黯","面色黑而干焦","面色黧黑，肌肤甲错","面色枯黄","面色苍白"],"a":0,"e":"肾阳虚衰、阴寒凝滞，面色黑而淡黯，因阳虚温煦失职、寒凝血滞。黑而干焦为肾阴虚、虚火灼津；面色黧黑、肌肤甲错为瘀血内停；苍白为阳虚或失血；枯黄为脾虚"},{"q":"神昏暴厥多见于","o":["喜证","怒证","恐证","悲证","思证"],"a":1,"e":"怒则气上，暴怒使肝气上逆、气血壅滞于上，可见神昏暴厥。喜证多喜笑不休；恐证见胆怯、二便失禁；悲证见善悲喜哭；思证见多思善虑、纳呆"},{"q":"对心肾阳虚，最有诊断意义的是","o":["心悸怔忡、肢肿形寒","心中悸动、面白神疲","心胸憋痛、舌质暗淡","心悸失眠、腰酸盗汗","腰膝冷痛、畏寒肢冷"],"a":0,"e":"心肾阳虚，心悸怔忡、肢肿形寒并见，心阳虚则心悸，肾阳虚水泛则肢肿、形寒，最具诊断意义。心中悸动面白神疲偏心气虚；心胸憋痛舌暗淡偏心血瘀；心悸失眠腰酸盗汗偏心肾阴虚"},{"q":"肠虚滑泻证的泻下特点是","o":["时干时稀","大便秘结","下利无度","气味恶臭","里急后重"],"a":2,"e":"肠虚滑泻因脾肾阳虚、大肠失固，泻下特点为下利无度、滑脱不禁。时干时稀属肝郁脾虚；大便秘结属肠燥或热结；气味恶臭属湿热；里急后重属痢疾或大肠湿热"},{"q":"下列各项中最不易导致月经先期的是","o":["营血亏损","肝郁血热","气虚不摄","阴虚火旺","阳盛血热"],"a":0,"e":"营血亏损、血海不足多致月经后期、量少，最不易导致月经先期。肝郁血热、气虚不摄、阴虚火旺、阳盛血热均可使血海不宁、经血提前"},{"q":"提示疾病发展变化转折点的是","o":["自汗","盗汗","大汗","战汗","绝汗"],"a":3,"e":"战汗为正邪剧争、病情转折之象，汗出后脉静身凉为病退，汗出后热仍不退、脉躁急为病进，提示疾病发展变化转折点。自汗、盗汗为虚证常症；大汗、绝汗为危候"},{"q":"细脉的脉象是","o":["举之无力，按之空虚","沉细而软，应指无力","极细极软，似有似无","脉体如线，应指明显","浮而细软，应指无力"],"a":3,"e":"细脉脉体如线、应指明显，但细软有力。举之无力按之空虚为虚脉；沉细而软应指无力为弱脉；极细极软似有似无为微脉；浮而细软应指无力为濡脉"},{"q":"《素问·五脏生成》中，描述为白如枯骨是","o":["主色","客色","善色","恶色","病色"],"a":3,"e":"《素问·五脏生成》以“白如枯骨”为恶色，晦暗枯槁、无光泽，提示病情危重。善色明润光泽；主色为固有肤色；客色随外界变化；病色泛指病理肤色"},{"q":"芤脉的主病是","o":["实热","瘀血","气滞","失血","气虚"],"a":3,"e":"芤脉浮大中空、如按葱管，主失血、伤阴，因血容量骤减、脉道空虚。实热多见洪数脉；瘀血多见涩脉；气滞多见弦脉；气虚多见虚细脉"},{"q":"下列除哪项外均属于阳斑的表现","o":["斑色红紫","平铺于皮肤","点小如粟","压之不退色","身热、面赤、脉数"],"a":2,"e":"阳斑色红紫、平铺于皮肤、压之不退色，伴身热面赤脉数。“点小如粟”为疹之形态，疹高出皮面、形如粟粒，非阳斑表现，故应排除"},{"q":"以日晡潮热、大便不通、腹痛为辨证要点的属于","o":["热邪壅肺","热扰胸膈","热结肠道","热郁胆经","热扰心神"],"a":2,"e":"日晡潮热、大便不通、腹痛拒按为热结肠道、腑实内结之辨证要点。热邪壅肺见咳喘黄痰；热扰胸膈见心烦懊憹；热郁胆经见口苦胁痛；热扰心神见神昏谵语"},{"q":"气营两燔的舌象表现为","o":["红绛舌，薄白苔","红绛舌，黄白苔","红瘦舌，黑苔","红舌，苍老滑苔","淡白舌，黄裂苔"],"a":1,"e":"气营两燔既有气分大热又入营动血，舌象为红绛舌、黄白苔。红绛薄白苔偏卫营；红瘦黑苔为热极伤阴；苍老滑苔主实热；淡白黄裂苔为气血两虚兼热，均非气营两燔"},{"q":"阳明经证最不可能出现的是","o":["脉洪大","大汗出","身大热","大便溏","口大渴"],"a":3,"e":"阳明经证以大热、大汗、大渴、脉洪大为特点，大便溏不属其表现。大便溏多属脾虚湿盛或肠虚；其余大汗、身大热、口大渴、脉洪大均为经证典型"},{"q":"肝阳上亢头痛的特点是","o":["重痛","胀痛","窜痛","灼痛","隐痛"],"a":1,"e":"肝阳上亢、肝气上逆，头部胀痛、昏沉，伴眩晕烦躁，故头痛以胀痛为特点。重痛属湿邪；窜痛属气滞或风邪；灼痛属热邪；隐痛属虚证"},{"q":"以下何脉不属重按始得的脉象","o":["弱脉","牢脉","革脉","伏脉","沉脉"],"a":2,"e":"革脉浮而搏指、中空外坚，重按反空，不属重按始得之脉。弱脉、牢脉、伏脉、沉脉均脉位深沉，须重按方得"},{"q":"28脉中，具备虚、沉、小的特点的脉象是","o":["伏脉","弱脉","细脉","濡脉","涩脉"],"a":1,"e":"弱脉沉细而软，具备虚、沉、小（细）三者特点。伏脉深沉但非虚细；细脉细但不沉；濡脉浮细；涩脉往来艰涩，均不兼具三性"},{"q":"寒证化热的临床意义是","o":["邪热毒气严重","阳气耗散","疫毒痢初期","痰湿凝聚","阳气旺盛"],"a":4,"e":"寒证化热提示阳气旺盛、邪从阳化，正气有能力与邪相争而转热。邪热毒气严重为热毒炽盛；阳气耗散可致亡阳；疫毒痢初期为湿热疫毒；痰湿凝聚为阴邪内停"},{"q":"脾病虚证的基础证型是","o":["脾不统血证","脾气虚证","脾阴虚证","脾虚气陷证","脾阳虚证"],"a":1,"e":"脾气虚证为脾病诸虚证之基础，脾不统血、脾虚气陷、脾阳虚皆由脾气虚发展而来。脾阴虚另属阴液亏虚，非以脾气虚为基础"},{"q":"重按实大弦长的脉象是","o":["长脉","弦脉","伏脉","牢脉","紧脉"],"a":3,"e":"牢脉沉按实大弦长、坚牢不移，主阴寒内盛、疝气癥积。长脉仅脉体延长；弦脉端直以长；伏脉推筋着骨；紧脉紧张有力如转索，均非实大弦长"},{"q":"下列对主诉的表述，最正确的是","o":["经常腹痛已多年","5年来右胁胀痛","患高血压1年","发热、咳嗽2天","咳喘反复发作20年"],"a":3,"e":"主诉为最主要的症状或体征及其持续时间，“发热、咳嗽2天”符合要求。经常腹痛已多年、5年来右胁胀痛、咳喘20年均有症状而时间表述笼统或仅言年限；患高血压1年为病名非症状"},{"q":"证候真假的“真”是指","o":["病人提供的资料为真","临床上常见的症状表现","与疾病内在本质相符的证候","整个病程中始终存在的症状表现","与病人既往疾病和体质状态相符的表现"],"a":2,"e":"证候真假之“真”指与疾病内在本质相符的证候，反映病变真实属性。病人提供资料真实、常见症状、病程始终存在的症状、与既往体质相符者，均未必反映当前本质"},{"q":"心阴虚证的舌象最有可能是下列哪项","o":["舌红苔黄","舌红绛苔薄黄","舌淡红苔薄","舌红少苔","舌淡红无苔"],"a":3,"e":"心阴虚、心失濡养、虚热内扰，舌象为舌红少苔。舌红苔黄、舌红绛苔薄黄主实热或热入营；舌淡红苔薄为正常；舌淡红无苔偏气虚或胃气不足"},{"q":"濡脉和弱脉的共同特征是","o":["迟细而无力","沉而无力","空虚无力","细而无力","浮而无力"],"a":3,"e":"濡脉浮细无力，弱脉沉细无力，共同特征为细而无力。沉而无力仅指弱脉；浮而无力仅指濡脉；空虚无力为虚脉；迟细而无力非两者所共有"},{"q":"舌体胖大，边有齿痕多为","o":["肾阴不足","肺阴不足","脾虚湿盛","心血不足","肝血不足"],"a":2,"e":"脾虚运化失职、湿邪内停，故舌体胖大、边有齿痕。肾阴不足、肺阴不足、心血不足、肝血不足多见舌红少苔或舌淡瘦薄，无胖大齿痕"},{"q":"寸关尺分候脏腑，《难经》以左寸候","o":["心、膻中","心、胸中","心、小肠","心、大肠","心、心包络"],"a":2,"e":"《难经》以左寸候心、小肠，左关候肝、胆，左尺候肾与膀胱。心、膻中，心、胸中，心、大肠，心、心包络等配属均与《难经》寸关尺分候脏腑之说不符"},{"q":"导致亡阴的病因病机，错误的是","o":["病久阴竭","持续壮热","吐泻不止","大汗不止","严重冻伤"],"a":4,"e":"亡阴因持续壮热、大汗不止、吐泻不止、病久阴竭等致阴液大量耗伤。严重冻伤损伤阳气，多致亡阳，非亡阴病因"},{"q":"真热假寒证通常不见","o":["脉沉有力","神志昏沉","高热肢厥","面色浮红如妆","胸腹灼热"],"a":3,"e":"真热假寒见高热肢厥、胸腹灼热、脉沉有力、神志昏沉，为热极格阴于外。面色浮红如妆为虚阳上浮、真寒假热之戴阳表现，与真热假寒相反"},{"q":"郑声的病机是","o":["心气不足，神失所养","心气大伤，精神散乱","瘀血阻遏心窍","热扰心神，神明失主","痰湿阻遏心窍"],"a":1,"e":"郑声为神识不清、语言重复、声音低微无力，因心气大伤、精神散乱。心气不足神失所养多见独语或谵语轻证；热扰心神为谵语；痰湿或瘀血阻窍为癫证或错语"},{"q":"心阳不足时，虚里搏动的特点是","o":["搏动迟弱","绝而不应","虚里动高","数急时止","聚而不散"],"a":0,"e":"心阳不足、鼓动无力，虚里搏动迟弱、节律缓慢。绝而不应主阳气暴脱；虚里动高为宗气外泄或惊恐；数急时止为心气紊乱；聚而不散非心阳不足之象"},{"q":"手足蠕动的病机是","o":["热极生风","血虚生风","阴虚动风","肝阳化风","寒凝筋脉"],"a":2,"e":"手足蠕动、肌肉瞤动，因阴液亏虚、筋脉失养、虚风内动所致，属阴虚动风。热极生风见抽搐有力、角弓反张；血虚生风见肢体麻木、震颤；肝阳化风见眩晕欲仆、半身不遂"},{"q":"下列除哪项外脉率均较正常脉率慢","o":["缓脉","弦脉","迟脉","结脉","涩脉"],"a":1,"e":"弦脉脉率正常，端直以长如按琴弦，不属迟脉类。缓脉一息四至、迟脉一息三至、结脉迟缓中止、涩脉往来艰涩且速率偏慢，均较正常脉率慢"},{"q":"肝郁气滞导致胁痛的特点是","o":["隐痛","灼痛","胀痛","掣痛","绞痛"],"a":2,"e":"肝郁气滞、气机阻滞于胁络，故胁肋胀痛、走窜不定。隐痛属虚；灼痛属热；掣痛多为筋脉拘急；绞痛多为寒邪或结石阻滞，均非肝郁气滞特点"},{"q":"对诊断心肺气虚证最有意义的是","o":["咳喘痰多、动则尤甚","喘息短气、呼多吸少","咳痰清稀、乏力神疲","自汗乏力、喘咳心悸","咳喘无力、自汗畏风"],"a":3,"e":"心肺气虚，自汗乏力为气虚，喘咳心悸为肺心同病，最具诊断意义。咳喘痰多动则尤甚偏肺脾气虚；喘息短气呼多吸少偏肾不纳气；咳痰清稀乏力神疲偏肺气虚"},{"q":"下列哪项属于心病的常见症状","o":["口舌生疮","阴囊湿疹","目泡赤烂","牙龈肿痛","咽喉肿痛"],"a":0,"e":"心开窍于舌，心火上炎可见口舌生疮、舌尖红赤。阴囊湿疹属肝胆湿热下注；目泡赤烂属脾胃湿热；牙龈肿痛属胃火；咽喉肿痛多属肺胃热盛"},{"q":"目赤胀痛，伴急躁易怒，口干口苦者，属于","o":["肝气犯胃","胆气上逆","肝郁脾虚","肝火上炎","风热上扰"],"a":3,"e":"肝火上炎、循经上扰，故目赤胀痛，伴急躁易怒、口干口苦、便秘尿黄。肝气犯胃以胃脘胀痛、嗳气为主；胆气上逆见口苦呕苦；肝郁脾虚见胁胀纳呆；风热上扰起病急、伴表证"},{"q":"身热夜甚、心烦不寐、斑疹隐现，舌红绛，脉细数，其临床意义是","o":["卫分证","气分证","营分证","血分证","热灼营阴"],"a":2,"e":"身热夜甚、心烦不寐、斑疹隐现、舌红绛、脉细数，为热入营分、营阴受损之象。卫分证见发热恶寒；气分证但热不寒、大汗大渴；血分证见斑疹显露、出血动血"},{"q":"镜面舌的形成机理是","o":["热甚伤津","水湿上泛","热入营血","胃肠热结","胃无生发之气"],"a":4,"e":"镜面舌舌面光洁如镜、无苔，因胃阴枯竭、胃无生发之气，舌苔不能生成。热甚伤津见苔黄燥；水湿上泛见苔白滑；热入营血见舌红绛；胃肠热结见苔黄厚燥"},{"q":"主痰热、湿热、食积内热的脉象是","o":["滑数脉","浮滑脉","弦数脉","洪数脉","细数脉"],"a":0,"e":"滑脉主痰饮、食积、实热，数脉主热，滑数相兼主痰热、湿热、食积内热。浮滑偏风痰或表证夹痰；弦数偏肝胆热；洪数偏气分大热；细数偏阴虚火旺"},{"q":"下列哪项不属于心阳虚证的辨证要点","o":["心悸","怔忡","心胸疼痛","神疲乏力","阳虚症状"],"a":3,"e":"心阳虚辨证要点为心悸怔忡、心胸疼痛及阳虚症状。神疲乏力为心气虚或脾气虚之常见表现，非心阳虚辨证要点，故应排除"},{"q":"皮肤、面目发黄，鲜明如橘子色，伴汗液、尿液颜色深黄如黄柏汁，口渴，舌苔黄腻者，属于","o":["阳黄","阴黄","萎黄","黄疸","苍黄"],"a":0,"e":"阳黄因湿热蕴结肝胆、胆汁外溢，身目发黄鲜明如橘子色，汗尿深黄如黄柏汁，苔黄腻。阴黄黄色晦黯如烟熏；萎黄为脾虚血少、面黄无光泽；苍黄为面色青黄相兼"},{"q":"以猝然昏倒，不省人事，喉中痰鸣，口眼歪斜，半身不遂，舌红苔腻，脉弦有力为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","寒滞肝脉证"],"a":1,"e":"肝阳化风、风阳上扰，故猝然昏倒、不省人事、喉中痰鸣、口眼歪斜、半身不遂，舌红苔腻、脉弦有力。血虚生风见麻木震颤；阴虚风动见手足蠕动；热极生风见高热抽搐"},{"q":"阴黄是指","o":["面色黄鲜明","黄色晦黯如烟熏","面色苍黄","面色淡黄而兼虚浮","面、目、尿俱黄"],"a":1,"e":"阴黄为寒湿困脾、胆汁外溢，黄色晦黯如烟熏。面色黄鲜明为阳黄；面色苍黄为肝郁脾虚；面色淡黄虚浮为萎黄；面目尿俱黄为黄疸总称"},{"q":"与惊伤证无关的是","o":["惊悸","坐卧不宁","胆怯","二便失禁","健忘失眠"],"a":3,"e":"惊伤心胆，惊伤证见惊悸、胆怯、坐卧不宁、健忘失眠等心神不宁之象。二便失禁为恐伤肾、肾气不固之下焦失固表现，与惊伤证无关"},{"q":"症见腹胀满，疼痛拒按，大便燥结，舌红苔黄厚焦燥，其脉可为","o":["沉紧脉","迟细脉","浮滑脉","沉缓脉","浮紧脉"],"a":1,"e":"腹胀满、疼痛拒按、大便燥结、舌红苔黄厚焦燥为里热结实之阳明腑实，热结于里、气血阻滞，脉可见迟（迟而有力主热结）。沉紧主寒邪内痛；浮滑主痰食或表证夹痰；沉缓主寒湿；浮紧主外感风寒，均非里热结实之脉"},{"q":"下列属于麻疹顺证表现的是","o":["壮热无汗","疹点颜色淡红而黯","疹点突然隐没，神昏喘息","疹出透彻，色泽红润","疹点不能透发，颜色白而不红"],"a":3,"e":"麻疹顺证见疹出透彻、分布均匀、色泽红润、发热和缓、精神安定。壮热无汗为疹出不畅；疹色淡红而黯为气血不足或逆证；疹点突然隐没、神昏喘息为麻疹逆证、毒邪内陷；白而不红为风寒郁滞"},{"q":"病人一侧颧下颌上耳周发红肿起，伴有寒热、疼痛者，称为","o":["痄腮","发颐","阳水","阴水","抱头火丹"],"a":1,"e":"发颐为热毒郁结少阳、阳明，一侧颧下颌上耳周发红肿起、伴寒热疼痛。痄腮多为两侧腮腺肿痛、起病急、有传染性；阳水、阴水为水肿；抱头火丹为头面部丹毒、焮红灼热、边界清楚"},{"q":"下列哪项对诊断肾阴虚证最有意义","o":["腰酸耳鸣","舌红无苔","经少经闭","遗精潮热","眩晕健忘"],"a":3,"e":"遗精潮热为肾阴虚、相火妄动之特征，对诊断肾阴虚最有意义。腰酸耳鸣、舌红无苔、经少经闭、眩晕健忘虽可见于肾阴虚，但亦常见于其他证候，特异性不足"},{"q":"主寒证和痛证的脉象是","o":["紧脉","缓脉","革脉","短脉","促脉"],"a":0,"e":"紧脉脉来紧张、有力如转索，主寒证、痛证，亦主宿食。缓脉主湿或脾胃虚弱；革脉主亡血失精；短脉主气郁或气虚；促脉主阳盛热结或脏气衰败"},{"q":"下列各项，属于“病”的概念的是","o":["湿热","胸闷","内风","麻疹","气滞"],"a":3,"e":"麻疹为具体疾病，属“病”的概念。湿热、内风、气滞为病机概念；胸闷为症状，均非病名"},{"q":"大肠湿热证一般不见下列哪项","o":["肛门灼热","溏结不调","泻下黄糜","便下脓血","里急后重"],"a":1,"e":"大肠湿热见肛门灼热、泻下黄糜、便下脓血、里急后重，因湿热下注大肠。溏结不调、时干时稀多属肝郁脾虚或脾虚湿盛，非大肠湿热典型表现"},{"q":"咳吐脓血腥臭痰者，多属","o":["肺痈","白喉","肺痿","顿咳","肺痨"],"a":0,"e":"肺痈为热毒壅肺、血肉腐败，见咳吐脓血腥臭痰、胸痛发热。白喉见咽喉灰白假膜；肺痿见咳吐浊唾涎沫；顿咳见阵发性痉挛性咳嗽；肺痨见咳嗽咯血、潮热盗汗"},{"q":"舌尖红赤或破溃，多为","o":["心火上炎","外感风热表证","肝经有热","肾阴亏虚","湿热下注"],"a":0,"e":"舌尖属心，心火上炎则舌尖红赤或生疮破溃。外感风热表证多见舌边尖红；肝经有热见舌边红；肾阴亏虚见舌红少苔或舌尖红；湿热下注见舌苔黄腻"},{"q":"寸关尺分候脏腑，右关部侯","o":["心","肺","脾","肝","肾"],"a":2,"e":"寸关尺分候脏腑，右关候脾与胃，左关候肝胆，寸候心肺，尺候肾。心、肺、肝、肾各有对应部位，均不在右关"},{"q":"头痛连项者，属","o":["太阳经头痛","少阳经头痛","阳明经头痛","厥阴经头痛","少阴经头痛"],"a":0,"e":"头痛连项、后枕部痛及项背，属太阳经头痛，因太阳经循行于项背。少阳经头痛在头两侧；阳明经头痛在前额眉棱；厥阴经头痛在巅顶；少阴经头痛多伴齿痛、头痛连齿"},{"q":"下列各项，提出“独取寸口”诊脉法的是","o":["《黄帝内经》","《难经》","《脉经》","《伤寒杂病论》","《中藏经》"],"a":1,"e":"“独取寸口”诊脉法由《难经》明确提出，并详述寸关尺分部。《黄帝内经》虽论寸口但未独取；《脉经》为王叔和所撰脉学专著；《伤寒杂病论》以辨证论治为主；《中藏经》为脏腑辨证著作"},{"q":"腹部肿块推之可移，痛无定处，病在","o":["血分","气分","虚痞","结胸","肠痈"],"a":1,"e":"腹部肿块推之可移、痛无定处，为聚证，病在气分，因气机郁滞、聚散无常。血分癥块坚硬、固定不移、痛有定处；虚痞满而不痛、按之柔软；结胸为胸腹硬满疼痛；肠痈为右下腹固定压痛"},{"q":"下列各项，不属现病史内容的是","o":["发病情况","病变过程","做过何诊断","经过哪些治疗","过去曾患何病"],"a":4,"e":"现病史包括发病情况、病变过程、诊治经过等。“过去曾患何病”属既往史内容，不属现病史"},{"q":"属于内湿证辨证要点的是","o":["恶寒微热","皮肤湿疹","瘙痒","纳呆腹泻","脉浮滑"],"a":3,"e":"内湿证因脾失健运、湿邪内生，辨证要点为纳呆腹泻、腹胀、苔腻、脉濡。恶寒微热、脉浮滑为外感表证；皮肤湿疹、瘙痒多为外湿或风湿犯表"},{"q":"咳声不扬，痰稠色黄，证属","o":["风热袭表","寒邪客肺","热邪犯肺","痰湿阻肺","阴虚肺燥"],"a":2,"e":"热邪犯肺、肺失清肃、炼液成痰，故咳声不扬、痰稠色黄。风热袭表伴发热恶寒、咽痛；寒邪客肺见咳白稀痰、恶寒；痰湿阻肺见痰白黏稠量多；阴虚肺燥见干咳少痰"},{"q":"经前小腹胀痛，行经后痛减者，多为","o":["气血不足","血瘀","肾虚","寒证","气滞"],"a":4,"e":"气滞则经前气血运行不畅、小腹胀痛，行经后气机得舒故痛减。血瘀多见刺痛、痛处固定、经色暗红有块；肾虚、气血不足多见经期或经后隐痛、喜按"},{"q":"多食易饥，大便溏泄者，多属","o":["胃火亢盛","胃阴不足","胃强脾弱","阴虚火旺","肝气犯胃"],"a":2,"e":"胃强脾弱、胃热则消谷善饥，脾虚运化失职则大便溏泄。胃火亢盛多食易饥但大便干结；胃阴不足饥不欲食；阴虚火旺伴潮热盗汗；肝气犯胃见胁胀、嗳气"},{"q":"下列哪项舌象特征可见于正常人","o":["红绛舌","裂纹舌","歪斜舌","瘦薄舌","胖大舌"],"a":1,"e":"裂纹舌可见于正常人，为先天性舌面裂纹、无苔垢覆盖、无疼痛等不适。红绛舌主热盛或阴虚；歪斜舌主中风或肝风；瘦薄舌主气血阴液不足；胖大舌主脾虚湿盛"},{"q":"发热，齿龈红肿疼痛出血，口渴欲饮，舌红，脉数。宜诊断为","o":["肝火炽盛证","心火亢盛证","胃火炽盛证","肺热炽盛证","阴虚火旺证"],"a":2,"e":"胃火炽盛、循经上攻，故发热、齿龈红肿疼痛出血、口渴欲饮、舌红脉数。肝火炽盛见目赤胁痛；心火亢盛见口舌生疮、心烦；肺热炽盛见咳喘黄痰；阴虚火旺见潮热盗汗、舌红少苔"},{"q":"胃脘冷痛，喜温喜按，食后痛减，畏寒肢冷，证属","o":["胃气虚证","胃阳虚证","食滞胃脘证","脾气虚证","脾阳虚证"],"a":1,"e":"胃阳虚、胃失温养，故胃脘冷痛、喜温喜按、食后痛减，伴畏寒肢冷。胃气虚以隐痛、食少、乏力为主，寒象不显；食滞胃脘见胀痛、嗳腐吞酸；脾气虚、脾阳虚以腹泻、腹胀为主"},{"q":"不属于面色白的主证是","o":["虚证","寒证","失血","夺气","水饮"],"a":4,"e":"面色白主虚证、寒证、失血、夺气，因气血不足或阳气虚衰、血液不能上荣。水饮内停多见面色黑或黄，不属面色白主证"},{"q":"下列除哪项外，均可导致癃闭","o":["热结膀胱","瘀血内结","肾阳虚衰","肾气不固","结石阻塞"],"a":3,"e":"肾气不固以下焦失固为主，见小便失禁、遗尿、滑精、胎动易滑、月经淋漓，不导致癃闭。热结膀胱、瘀血内结、结石阻塞均可阻塞水道；肾阳虚衰气化无权亦致癃闭"},{"q":"以下脉象中，脉位不在浮位的脉象是","o":["洪脉","散脉","芤脉","弱脉","革脉"],"a":3,"e":"弱脉沉细而软，脉位在沉位，不在浮位。洪脉浮大有力；散脉浮散无根；芤脉浮大中空；革脉浮而搏指，均在浮位"},{"q":"虚证常见","o":["五心烦热","大便干结","小便不通","痰涎壅盛","腹痛拒按"],"a":0,"e":"虚证常见五心烦热，为阴虚内热之象。大便干结可见于实热或阴虚；小便不通多属癃闭实证；痰涎壅盛、腹痛拒按均为实证表现"},{"q":"以咳喘无力、声低懒言、自汗为主要表现的证是","o":["肺气虚证","肺脾气虚证","肺阴虚证","肺肾气虚证","心肺气虚证"],"a":0,"e":"肺气虚、肺失宣降、宗气不足，故咳喘无力、声低懒言、自汗。肺脾气虚兼见食少便溏；肺阴虚见干咳少痰；肺肾气虚见呼多吸少；心肺气虚兼见心悸"},{"q":"苔少无津多见于","o":["里热证","寒湿证","表寒证","虚寒证","阴虚证"],"a":4,"e":"阴虚证、津液不足、舌面失润，故苔少无津。里热证见苔黄燥；寒湿证见苔白腻；表寒证苔薄白；虚寒证见舌淡苔白润"},{"q":"发黄干枯，稀疏易落，多属","o":["禀赋不足","血虚受风","疳积","精血不足","血热"],"a":3,"e":"发黄干枯、稀疏易落为精血不足、发失所养。禀赋不足多见小儿囟门迟闭、发育迟缓；血虚受风见斑秃；疳积见发枯如穗；血热见发红赤或早白"},{"q":"痰白滑而量多，易咳出者，属","o":["风痰","寒痰","热痰","湿痰","燥痰"],"a":3,"e":"湿痰因脾虚湿聚、痰湿内停，故痰白滑、量多、易咳出。寒痰白而清稀；热痰黄稠；风痰清稀而多泡沫；燥痰少而黏、难咯"},{"q":"下列哪项不属于心气虚证的辨证要点","o":["心悸","神疲","多梦","胸闷","气虚症状"],"a":2,"e":"心气虚辨证要点为心悸、神疲、胸闷及气虚症状。多梦多属心血不足、心阴虚或心脾两虚、神不守舍，非心气虚辨证要点"},{"q":"下列各项，不属痫病的常见临床表现的是","o":["猝然跌倒","四肢抽搐","半身不遂","口吐涎沫","醒后如常"],"a":2,"e":"痫病见猝然跌倒、四肢抽搐、口吐涎沫、醒后如常，因痰浊闭窍、肝风内动。半身不遂为中风后遗症，非痫病常见表现"},{"q":"属于除中表现的是","o":["食欲旺盛","食量逐渐减少","食量逐渐增加","饥而不欲食","重病突然欲食"],"a":4,"e":"除中为疾病危重阶段、胃气将绝而反见食欲亢进、突然欲食的假象，是预后不良之兆。食量逐渐减少为胃气渐衰；饥而不欲食为胃阴不足；食欲旺盛、食量逐渐增加非除中"},{"q":"下列哪项对诊断肾气不固证最无意义","o":["胎动易滑","小便失禁","滑精早泄","齿摇发脱","月经淋漓"],"a":3,"e":"齿摇发脱为肾精亏虚、不能充养齿发，与肾气不固之封藏失职无关。胎动易滑、小便失禁、滑精早泄、月经淋漓皆因肾气不固、下元失约"},{"q":"下列各项，不属食滞胃脘证的临床表现的是","o":["胃脘胀痛","嗳腐吞酸","泻下不爽","厌恶食物","呕吐清水"],"a":4,"e":"食滞胃脘见胃脘胀痛、嗳腐吞酸、厌恶食物、泻下不爽。呕吐清水为胃阳虚或饮停胃脘、寒饮上逆，非食滞胃脘表现"},{"q":"风寒犯肺证与寒痰阻肺证皆可见到的症状是","o":["咳白痰","咳黄痰","喉间痰鸣","气喘","苔厚"],"a":0,"e":"风寒犯肺与寒痰阻肺均属寒邪为患、肺失宣降，故皆见咳白痰。咳黄痰属热；喉间痰鸣多属寒痰或哮证；气喘非必有；苔厚多属痰湿食积"},{"q":"气滞血瘀多见","o":["革脉","虚脉","疾脉","涩脉","实脉"],"a":3,"e":"涩脉往来艰涩、如轻刀刮竹，主气滞血瘀、精伤血少。革脉主亡血失精；虚脉主虚证；疾脉主阳极阴竭；实脉主实证，均非气滞血瘀之脉"},{"q":"脉来急数而时一止，止无定数，是指","o":["疾脉","促脉","结脉","动脉","代脉"],"a":1,"e":"促脉脉来急数而时一止、止无定数，主阳盛热结或脏气衰败。疾脉脉来急疾无歇止；结脉缓而中止、止无定数；动脉滑数如豆无歇止；代脉止有定数"},{"q":"风湿头疼的主要特点是","o":["头痛如裹","头痛晕","头脑空痛","头痛连项","头痛绵绵"],"a":0,"e":"风湿头痛因湿邪重浊、蒙蔽清阳，故头痛如裹、头重昏蒙。头痛而晕多为血虚或肝阳；头脑空痛属肾虚精髓不足；头痛连项属太阳经；头痛绵绵属气虚"},{"q":"面色淡白无华多属","o":["气滞","血虚","阴虚","亡阴","血瘀"],"a":1,"e":"面色淡白无华、缺乏血色，为血虚、血液不能上荣于面。气滞多见面色青暗；阴虚见颧红；亡阴见面色潮红或萎黄；血瘀见面色晦暗或黧黑"},{"q":"燥邪犯肺证与肺阴虚证的主要鉴别要点是","o":["有无发热恶寒","有无胸痛咳血","有无口干咽燥","痰量的多少","咯痰的难易"],"a":0,"e":"燥邪犯肺为外感，必有发热恶寒等表证；肺阴虚为内伤，无表证，故有无发热恶寒是主要鉴别点。胸痛咳血、口干咽燥、痰量多少、咯痰难易两者均可出现"},{"q":"疮疡红肿高大，根盘紧束，伴有焮热疼痛，称为","o":["痈","疽","疹","疖","疔"],"a":0,"e":"痈为气血壅滞、热毒炽盛，疮疡红肿高大、根盘紧束、焮热疼痛。疽漫肿无头、皮色不变；疖形小浅表；疔根脚坚硬、顶白而痛；疹为皮肤小丘疹"},{"q":"引起哮病发作最常见的诱因是","o":["宿痰内伏","感受外邪","劳倦过度","过食辛辣","情志失调"],"a":1,"e":"哮病宿痰内伏为病理基础，发作最常见诱因为感受外邪，外邪引动伏痰、痰气交阻。劳倦过度、过食辛辣、情志失调亦可诱发但不如外邪常见"},{"q":"虚里位于","o":["左乳下第4、5肋间","左乳下第3、4肋间","右乳下第4、5肋间","右乳下第3、4肋间","剑突下"],"a":0,"e":"虚里为宗气汇聚之处，位于左乳下第4、5肋间、心尖搏动处，可测知宗气盛衰。其余肋间及右乳下、剑突下定位均不准确"},{"q":"脉象“有神”是指","o":["从容和缓","节律一致","柔和有力","沉取有力","不浮不沉"],"a":2,"e":"脉象“有神”指柔和有力、节律整齐，为气血充足、心脉调和之象。从容和缓为胃气之象；节律一致为有节律；沉取有力为有根；不浮不沉为平脉脉位"},{"q":"神识不清，语无伦次，声高有力者称为","o":["错语","独语","谵语","呓语","郑声"],"a":2,"e":"谵语为神识不清、语无伦次、声高有力，属热扰心神之实证。错语为语言错乱、说后自知；独语为喃喃自语、他人听不清；呓语为睡中梦话；郑声为声音低微、语言重复"},{"q":"微脉、弱脉、濡脉的共同特征是","o":["脉细如线","细小无力","浮取即得","沉取即得","举按有力"],"a":1,"e":"微脉极细极软、似有似无；弱脉沉细而软；濡脉浮细而软，三者共同特征为细小无力。脉细如线仅指细脉；浮取即得仅濡脉；沉取即得仅弱脉；举按有力为实脉"},{"q":"咽喉色红，肿痛不显者，多辨证为","o":["肺胃热盛","肺肾阴虚","肝火犯肺","肺经风热","肝肾阴虚"],"a":1,"e":"咽喉色红、肿痛不显，为肺肾阴虚、虚火上炎、咽喉失养。肺胃热盛则咽喉红肿疼痛明显；肝火犯肺见咽干、咳嗽气逆；肺经风热起病急、咽痛伴表证；肝肾阴虚以腰膝酸软为主"},{"q":"下列与先天禀赋不足有关的是","o":["桶状胸","鸡胸、漏斗胸、肋如串珠","胸廓不对称","小儿头摇","扁平胸"],"a":1,"e":"鸡胸、漏斗胸、肋如串珠为先天禀赋不足、肾精亏虚、骨骼发育不良（佝偻病）之象。桶状胸多属肺胀；胸廓不对称多为后天伤病；小儿头摇多属肝风或惊风；扁平胸多为先天或消瘦体型"},{"q":"以下脉象中，脉位在浮位的脉象是","o":["沉脉","伏脉","牢脉","濡脉","弱脉"],"a":3,"e":"濡脉浮细而软、轻取即得，脉位在浮位。沉脉、伏脉、牢脉、弱脉均脉位深沉，须重按始得，不属浮位"},{"q":"热扰神明引起的呕吐多表现为","o":["吐势较缓","吐利并作","朝食暮吐","呕吐脓血","呈喷射状呕吐"],"a":4,"e":"热扰神明、颅内压增高，呕吐多呈喷射状、吐势急促。吐势较缓多属脾胃虚弱；吐利并作多属霍乱或胃肠湿热；朝食暮吐为胃反；呕吐脓血为热毒伤络或痈疡"},{"q":"脉形细小，脉势软弱，按之欲绝，若有若无，是","o":["散脉","濡脉","微脉","弱脉","细脉"],"a":2,"e":"微脉极细极软，按之欲绝、若有若无，是气血大虚、阳气衰微之象。濡脉浮而细软，主虚证湿证，脉位偏浮；弱脉沉细而软，脉位偏沉；细脉脉细如线但应指明显，不似微脉之欲绝；散脉浮大无根、至数不齐，属元气离散"},{"q":"导致半身无汗的病机是","o":["阳气虚损","邪阻经络","中焦郁热","脏腑实热","气虚痰凝"],"a":1,"e":"半身无汗多因风邪、痰瘀阻滞一侧经络，营卫不行、腠理闭塞，故汗出偏废于半身。阳气虚损、气虚痰凝多致全身自汗或汗少；中焦郁热、脏腑实热每见全身汗出或但头汗出、手足汗出，均不偏于一侧"},{"q":"“望色十法”中判断病情之虚实的纲领是","o":["散抟","微甚","浮沉","清浊","泽夭"],"a":1,"e":"望色十法以微甚辨虚实，色浅淡为微主虚，色深浓为甚主实。浮沉分表里，浮主表、沉主里；清浊辨阴阳，清主阳、浊主阴；散抟分新久，散主新病、抟主久病；泽夭判成败，泽主生、夭主死。虚实纲领唯在微甚"},{"q":"劳神过度的辨证要点是","o":["失眠多梦","神疲懒言","腰膝酸软","形体消瘦","形体臃肿"],"a":0,"e":"劳神过度耗伤心血脾气，心神失养则失眠多梦、心悸健忘，故为辨证要点。神疲懒言重在气虚；腰膝酸软责之肾虚；形体消瘦多属阴虚火旺或气血不足；形体臃肿为痰湿偏盛，均非劳神伤心神的定位"},{"q":"气血两虚证和气虚血瘀证的共同证候表现","o":["心悸失眠","舌质黯","少气懒言","肢体麻木","面色萎黄"],"a":2,"e":"气血两虚与气虚血瘀均以气虚为本，故共同见少气懒言、神疲乏力。舌质黯、肢体麻木是血瘀阻络之象，气血两虚舌多淡白；心悸失眠偏心血虚；面色萎黄为血虚失荣，皆非两证共有"},{"q":"下列各项，属于形盛气虚表现的是","o":["体胖能食，肌肉坚实","体胖食少，神疲乏力","形瘦能食，舌红苔黄","形瘦颧红，皮肤干焦","卧床不起，骨瘦如柴"],"a":1,"e":"形盛气虚者形体虽胖，却食少、神疲乏力，是气虚痰湿内停、外盛中虚。体胖能食、肌肉坚实为形盛气盛之实证；形瘦颧红、皮肤干焦属阴虚火旺；形瘦能食、舌红苔黄为中焦有火；卧床骨瘦如柴为气血极虚"},{"q":"住院病历中家族史应记录（）的健康状况","o":["直系亲属","父母身体状况","旁系亲属","与本人生活密切相关者","直系亲属和与本人生活密切相关的亲属"],"a":4,"e":"家族史着重记录直系亲属及与本人生活密切、长期共处者的健康状况，以排查遗传与传染因素。仅列直系亲属或旁系亲属均不全面；与本人生活密切相关者虽非血亲亦须记录，故二者合载方为完整"},{"q":"下述哪项不属辨证的范畴","o":["分析病因","确定病位","推断病势","判断病性","明确病名"],"a":4,"e":"辨证旨在分析病因、确定病位、判断病性、推断病势，进而概括证候；明确病名属辨病范畴。分析病因、确定病位、判断病性、推断病势皆为辨证环节，唯明确病名不在其列"},{"q":"失眠伴有心悸、纳差及便溏者，属于","o":["心脾两虚","心阴不足","心血亏虚","心肾不交","食积胃脘"],"a":0,"e":"心脾两虚心血不足则心悸失眠，脾气虚则纳差、便溏，故见是证。心阴不足、心血亏虚无脾虚运化失常之纳差便溏；心肾不交兼潮热盗汗、腰膝酸软；食积胃脘见嗳腐吞酸、脘腹胀满"},{"q":"弦脉的脉象特征是","o":["绷急弹指，状如转索","沉取有力，实大弦长","轻按搏指，中空外坚","端直以长，如按琴弦","脉位深沉，重按始得"],"a":3,"e":"弦脉端直以长、如按琴弦，主肝胆病、疼痛、痰饮、疟疾。绷急弹指、状如转索是紧脉；沉取有力、实大弦长为牢脉；轻按搏指、中空外坚是革脉；脉位深沉、重按始得为沉脉，皆非弦脉"},{"q":"心悸失眠属心脾两虚证者，最有说服力的依据是","o":["心烦而悸、脉象细数","食少腹胀、乏力舌淡","心悸善惊、多梦易醒","烦热盗汗、舌质红绛","心悸怔忡、面色淡白"],"a":1,"e":"心脾两虚须心血虚与脾气虚并见，食少腹胀、乏力舌淡正是脾气虚的确据，合心悸失眠而成立。心烦而悸、脉细数偏心阴虚；心悸善惊、多梦易醒为心胆气虚；烦热盗汗、舌红绛属阴虚火旺；面色淡白仅示血虚"},{"q":"饥不欲食的病机是","o":["脾失健运","胃强脾弱","胃阴不足","胃火炽盛","脾气亏虚"],"a":2,"e":"饥不欲食是胃阴不足，虚火内扰则知饥，胃失和降则不欲食。脾失健运为食少纳呆；胃强脾弱见多食易饥兼便溏；胃火炽盛则消谷善饥；脾气亏虚仅食少乏力，均无饥而不欲食之象"},{"q":"下列哪项一般不会出现滑苔","o":["脾阳不振","痰饮恋肺","寒湿内生","蓄水证","气滞血瘀"],"a":4,"e":"滑苔主痰饮水湿，脾阳不振、寒湿内生、蓄水证水湿不化，痰饮恋肺津液上泛，皆可致苔滑。气滞血瘀以舌质黯、瘀点瘀斑为特征，无水湿内停之机，故一般不出现滑苔"},{"q":"下列哪项不属于常色的表现","o":["光明润泽","含蓄隐隐","鲜明暴露","兼见红色","容光焕发"],"a":2,"e":"常色红黄隐隐、明润含蓄、容光焕发，个体偏红亦属主色常色。鲜明暴露、浮露无根是病色浮越之象，非含蓄之常色；光明润泽、含蓄隐隐、容光焕发皆常色表现，唯鲜明暴露当排除"},{"q":"坐而喜俯，少气懒言多属","o":["痰湿阻肺","水气痰饮","肺实气逆","肺虚体弱","痰饮停肺"],"a":3,"e":"坐而喜俯、少气懒言是肺气虚弱、体弱气短之态。坐而仰首、喘促气粗多为肺实气逆；水气痰饮、痰湿阻肺与痰饮停肺均见咳喘痰多、胸闷，属邪实壅肺，与肺虚体弱之静默少气不同"},{"q":"浮大中空，如按葱管，是","o":["浮脉","结脉","芤脉","缓脉","濡脉"],"a":2,"e":"芤脉浮大中空、如按葱管，主失血伤阴、血脉空虚。浮脉轻取即得、按之稍减而不空；结脉缓而时止、止无定数；缓脉一息四至、脉来和缓；濡脉浮而细软，均无中空之象"},{"q":"下列各项，不属问诊内容的是","o":["了解病人的自觉症状","了解既往的患病情况","发现病人的异常气色","得知以往的诊治情况","了解病人的工作性质及环境"],"a":2,"e":"发现病人异常气色属望诊内容，不属问诊。了解自觉症状、既往患病、以往诊治及工作性质环境，分别属现病史、既往史、个人史等问诊范畴，均由询问而得，唯气色须视诊察觉"},{"q":"痰最容易停聚于","o":["脾","心","肺","咽喉","肢体"],"a":2,"e":"脾为生痰之源、肺为贮痰之器，痰成之后随气上逆，最易停聚于肺，故咳痰为痰证常见。心多为痰蒙神明；咽喉为痰气交阻之梅核气；肢体痰核、流注相对少见，皆非贮痰主处"},{"q":"观察舌苔，辨别病邪的性质主要依据","o":["舌苔的有无","舌苔的润燥","舌苔的厚薄","舌苔的颜色","舌苔有根与无根"],"a":3,"e":"苔色辨病邪性质，白苔主寒、黄苔主热、灰黑苔主寒热之极，故颜色为据。苔的润燥辨津液盈亏；厚薄辨病位深浅与邪气盛衰；有无及有根无根辨胃气存亡，均非直接定病邪性质"},{"q":"面色黑而干焦者，多属","o":["肾阳虚衰，血失温养","阴虚火旺","寒湿带下","瘀血久停","肾虚水饮"],"a":1,"e":"面色黑而干焦是肾精久耗、阴虚火旺，虚火灼津、面部失润。肾阳虚衰、血失温养见面色黧黑而暗淡；肾虚水饮见面黑而紫暗或目眶发黑；寒湿带下非面色主病；瘀血久停见面色黧黑兼肌肤甲错，与干焦有别"},{"q":"阳明潮热的时间是","o":["11~13时","13~15时","15~17时","17~19时","19~21时"],"a":2,"e":"阳明潮热即日晡潮热，发于申时十五至十七时，因阳明腑实、燥屎内结，邪热乘日晡阳气渐衰之时内盛。阴虚潮热多在午后、夜间，伴盗汗、舌红少苔；湿温潮热身热不扬、午后热甚、苔腻；余时辰均非阳明应时之热"},{"q":"下列各项，不属胃阴虚证的临床表现的是","o":["胃脘灼痛","口燥咽干","大便干结","消谷善饥","舌红少津"],"a":3,"e":"消谷善饥是胃火炽盛、腐熟太过，食入即化，非胃阴虚。胃阴虚胃脘灼痛、口燥咽干、大便干结、舌红少津，且多饥不欲食；上述灼痛、咽干、便干、少津皆胃阴虚典型表现，唯消谷善饥当除外"},{"q":"淡白舌可见于","o":["阴虚火旺证","肝阳上亢证","阳虚水湿内停","外感表热证","外感表寒证"],"a":2,"e":"淡白舌主气血两虚与阳虚，阳虚水湿内停、舌体失温故色淡。阴虚火旺、肝阳上亢见面红舌红绛；外感表热见舌尖偏红、苔薄黄；外感表寒多见淡红苔薄白，均非淡白舌主病"},{"q":"膀胱湿热证一般不出现的症状是","o":["小便浑浊","余沥不尽","尿急短黄","排尿灼痛","小便频数"],"a":1,"e":"余沥不尽是肾气不固、下元虚损，膀胱失约。膀胱湿热见尿频、尿急、尿短黄、排尿灼痛及小便浑浊，此四项皆湿热下注膀胱之候；余沥不尽属虚，非湿热实证所有"},{"q":"脾肾阳虚可见下列哪项","o":["泻下腐臭","泻下黄糜","肛门灼热","完谷不化","里急后重"],"a":3,"e":"完谷不化是脾肾阳虚、火不暖土，脾胃腐熟运化失职，水谷直达下焦。泻下腐臭、泻下黄糜为大肠湿热；肛门灼热属湿热下注；里急后重为湿热痢疾，均非阳虚寒证"},{"q":"心阳虚证的舌象最有可能的是下列哪项","o":["舌红绛无苔","舌淡胖苔白滑","舌淡嫩苔薄黄","舌淡白苔黄滑","舌淡红苔薄白"],"a":1,"e":"心阳虚、阳虚水停，故舌淡胖、苔白滑。舌红绛无苔为阴虚火旺、津液大伤；舌淡嫩苔薄黄为气虚兼微热；舌淡白苔黄滑寒热错杂；舌淡红苔薄白为正常舌象，皆非心阳虚之舌"},{"q":"舌体歪斜多见于","o":["气血虚衰","肝风夹痰","阴虚动风","热甚动风","寒凝筋脉"],"a":1,"e":"舌体歪斜多因肝风夹痰、风痰阻络，为中风口眼㖞斜之征。气血虚衰见舌淡瘦薄；阴虚动风、热甚动风见舌红绛、颤动强硬；寒凝筋脉见舌淡紫而短缩，均非歪斜之因"},{"q":"食积证呕吐物的特点是","o":["清稀","酸腐","黄绿苦水","黯红有血块","清水痰涎"],"a":1,"e":"食积胃脘、宿食停滞，胃气上逆则呕吐物酸腐。呕吐清稀为胃寒或寒饮；黄绿苦水属肝胆郁热、胆液上逆；黯红有血块为瘀血或上消化道出血；清水痰涎为痰饮内停，皆非食积"},{"q":"卫分证是","o":["里热证","里寒证","表寒证","表热证","表虚证"],"a":3,"e":"卫分证是温病初起、邪犯肺卫，见发热微恶寒、脉浮数，属表热证。里热证为气分及以后；里寒证、表寒证均非温病卫分；表虚证为太阳中风、汗出脉浮缓，与卫分表热有别"},{"q":"《脉经》中记载有脉象的种类是多少种","o":["21种","24种","26种","27种","28种"],"a":1,"e":"《脉经》为王叔和所撰，系统记载脉象二十四种，奠定了脉学基础。其余数目均非《脉经》所载之数，或为《内经》等他书说法，与此问无涉"},{"q":"弱脉的脉象特征为","o":["脉极软而沉细","脉细如线","脉来绷急","迟缓无为","来盛去衰"],"a":0,"e":"弱脉极软而沉细，须重按乃得、应指无力。脉细如线为细脉；脉来绷急为紧脉；迟缓无为为缓脉；来盛去衰、浮大有力为洪脉，皆非弱脉状"},{"q":"下列哪项对诊断肺肾气虚证最无意义","o":["咳喘无力","声低自汗","苔腻脉滑","腰膝酸软","呼多吸少"],"a":2,"e":"苔腻脉滑主痰湿内盛，与肺肾气虚之虚证病机相反，故最无意义。肺肾气虚见咳喘无力、声低自汗，腰膝酸软、呼多吸少为肾不纳气，皆本证要点；唯苔腻脉滑属实邪，当排除"},{"q":"体瘦食多属于","o":["阳虚脾弱","阴虚火旺","气血亏虚","阴虚不足","中焦有火"],"a":4,"e":"体瘦食多是中焦有火、胃热腐熟太过，即瘦人多火。阳虚脾弱见形瘦食少、便溏；阴虚火旺、阴虚不足见形瘦颧红、潮热盗汗；气血亏虚见面色萎黄、乏力，均无能食之象"},{"q":"面目一身俱黄，且黄鲜明如橘皮色的是","o":["萎黄","黄胖","阳黄","阴黄","水饮"],"a":2,"e":"阳黄由湿热熏蒸肝胆、胆汁外溢，故面目一身俱黄、色鲜明如橘皮。阴黄属寒湿，黄色晦暗如烟熏；萎黄为血虚、面色萎黄少华；黄胖为脾虚湿盛、面黄虚浮；水饮非黄疸，均无鲜明橘色"},{"q":"形成脉象的动力是","o":["心脏搏动","脉道通利","气血盈亏","脏腑协同","肾藏精化血"],"a":0,"e":"心主血脉，心脏搏动是推动血液运行、形成脉象的动力。脉道通利是脉象形成条件；气血盈亏为物质基础；脏腑协同中肺朝百脉、肝藏血、脾统血参与调节；肾藏精化血为根本，皆非直接动力"},{"q":"胃脘胀痛，伴有嗳腐吞酸，呕吐宿食者，多为","o":["寒犯胃脘","食滞胃脘","肝气犯胃","血瘀胃腑","胃火炽热"],"a":1,"e":"食滞胃脘、宿食内停，胃失和降则胃脘胀痛、嗳腐吞酸、呕吐宿食。寒犯胃脘见冷痛喜温；肝气犯胃见胀痛连胁、嗳气频作；血瘀胃腑见刺痛固定不移；胃火炽热见灼痛、口臭、便秘"},{"q":"与恐伤证无关的是","o":["气下","伤肾","恶梦惊醒","二便失禁","头目胀痛"],"a":4,"e":"恐伤肾、恐则气下，故见二便失禁、恶梦惊醒等肾气不固、心神不安之象。头目胀痛是怒则气上、肝阳上亢或肝火上炎所致，与恐伤气下病机相反；气下、伤肾、二便失禁、恶梦惊醒皆恐伤表现"},{"q":"下述何项与月经后期无关","o":["营血亏损","阳气虚衰","气滞血瘀","寒凝血瘀","阳盛血热"],"a":4,"e":"阳盛血热迫血妄行，致月经先期、量多色深，与月经后期相反。营血亏损、阳气虚衰、寒凝血瘀、气滞血瘀均使血海不能按时满溢，而成月经后期，唯阳盛血热当除外"},{"q":"久流浊涕不止者，为","o":["鼻渊","肺痿","鼻衄","肺痈","外感风寒"],"a":0,"e":"鼻渊以久流浊涕、量多不止为主症，因肺经热盛或胆腑郁热上犯鼻窍。鼻衄为鼻出血；肺痿见咳吐浊唾涎沫；肺痈见咳吐脓血、腥臭；外感风寒见鼻塞流清涕，皆非浊涕不止"},{"q":"以下除哪项均为“得神”的表现","o":["神志清楚","颧赤如妆","反应灵敏","肌肉不削","两目精彩"],"a":1,"e":"颧赤如妆是虚阳浮越、戴阳之假神，属病危之象，非得神。神志清楚、反应灵敏、肌肉不削、两目精彩皆得神表现，见之说明精气充足、神旺于内；唯颧赤如妆浮艳不实，当排除"},{"q":"虚里是指","o":["左乳下心尖冲动处","心下","胃脘","少腹","胁肋"],"a":0,"e":"虚里为左乳下、心尖搏动之处，用以诊察宗气盛衰。心下为胃脘上部；胃脘在中焦；少腹为小腹两侧；胁肋为胸胁部位，均非虚里所在"},{"q":"肾虚体衰可导致的是","o":["足跟胫膝酸痛","四肢游走疼痛","四肢困重","四肢冷痛剧烈","四肢局部红肿灼痛"],"a":0,"e":"肾主骨、腰为肾府，肾虚体衰则足跟、胫膝酸痛、腰膝酸软。四肢游走疼痛为行痹（风邪偏盛）；四肢困重为着痹（湿邪偏盛）；四肢冷痛剧烈为痛痹（寒邪偏盛）；局部红肿灼痛为热痹"},{"q":"下列各项，不属阴脏人的特点的是","o":["头圆颈粗","肩宽胸厚","偏于矮胖","喜静少动","喜凉恶热"],"a":4,"e":"阴脏人阳气偏弱，多见头圆颈粗、肩宽胸厚、偏于矮胖、喜静少动、喜热恶寒。喜凉恶热是阳脏人、阳盛阴虚之性，与阴脏人相左；其余四项皆阴脏人体态与性情特征"},{"q":"鉴别蓄水证与蓄血证，下述哪项最有意义","o":["少腹硬满或不满","口渴引饮或不渴","小便自利或不利","大便泄泻或秘结","脉象浮数或浮缓"],"a":2,"e":"蓄水证水饮停于膀胱、气化不利，故小便不利；蓄血证瘀热结于下焦血分，膀胱气化未受影响，故小便自利，此为关键鉴别。少腹硬满蓄血多有而蓄水不满；口渴引饮蓄水较著；大便与脉象非二者鉴别要点"},{"q":"耳廓厚大，多属","o":["气血不足","肝胆湿热","阴寒内盛","肾精亏耗","肾气充足"],"a":4,"e":"耳为肾之窍，耳廓厚大、色泽红润是肾气充足、先天禀赋良好。耳廓瘦薄为气血不足或肾虚；耳廓青黑主阴寒内盛或痛证；肝胆湿热见耳部红肿、流脓；肾精亏耗见耳廓干枯焦黑"},{"q":"白睛色红，多为","o":["肝经风热","肺火、外感风热","脾有湿热","心火上炎","肝经湿热"],"a":1,"e":"白睛属肺、为气轮，肺火上炎或外感风热犯肺则白睛红赤。肝经风热多致全目赤肿、目眦红赤；脾有湿热常见睑缘赤烂；心火上炎多见两眦赤痛；肝经湿热可致目黄赤、眦部溃烂，皆非白睛独红之主因"},{"q":"大便先干后溏，多属","o":["脾气虚弱","肝郁乘脾","命门火衰","湿盛伤脾","食滞肠胃"],"a":0,"e":"大便先干后溏是脾气虚弱、运化失职，水谷不分。肝郁乘脾见腹痛即泻、泻后痛减；命门火衰见五更泄泻、完谷不化；湿盛伤脾见大便溏薄、身重苔腻；食滞肠胃见泻下腐臭、腹痛胀满"},{"q":"肝病日久，两胁胀满疼痛，并见舌质瘀斑，瘀点。其病机是","o":["气滞血瘀","气不摄血","气随血脱","气血两虚","气血失和"],"a":0,"e":"肝病日久、气郁化火，气滞则血行不畅，瘀阻胁络，故两胁胀满刺痛、舌现瘀斑瘀点。气不摄血见出血；气随血脱见于大出血后；气血两虚见舌淡、隐痛；气血失和无瘀斑瘀点之征"},{"q":"气血两虚证的舌色为","o":["舌淡红","舌淡白","舌红","舌绛","舌紫"],"a":1,"e":"气血两虚、血脉不充，舌体失养故色淡白。舌淡红为常色；舌红主热、舌绛主热盛或阴虚火旺；舌紫主瘀血或寒凝，皆非气血两虚之舌色"},{"q":"病人卧时向外，躁动不安，多属","o":["阳证","阴证","寒证","虚证","虚寒证"],"a":0,"e":"卧时向外、躁动不安、身轻而转侧自如，是阳证、热证、实证之态。阴证、寒证、虚证、虚寒证每见卧时向内、蜷缩静卧、身重懒动，与向外躁动者相反，故本候属阳"},{"q":"里热亢盛和阴虚火旺都可见到的舌象是","o":["瘦薄舌","红绛舌","芒刺舌","肿胀舌","青紫舌"],"a":1,"e":"红绛舌主热证，里热亢盛者舌红苔黄、阴虚火旺者舌红绛少苔，二者均见。瘦薄舌主阴虚或气血虚；芒刺舌主热盛、阴虚火旺少见；肿胀舌主湿热或中毒；青紫舌主瘀血，非二者共有"},{"q":"下列哪项不是黄厚腻苔的主病","o":["湿热蕴结","痰浊化热","寒湿内结","食积化热","痰热交阻"],"a":2,"e":"黄厚腻苔主湿热蕴结、痰浊化热、食积化热、痰热交阻。寒湿内结阳虚寒凝，当见白腻或白滑苔，苔色不黄；上述湿热、痰热、食积化热、痰热交阻皆可见黄厚腻苔，唯寒湿内结不主此苔"},{"q":"下列哪项不属脉位浮的脉象","o":["散脉","濡脉","微脉","芤脉","革脉"],"a":2,"e":"微脉极细极软、脉位偏沉，不属浮脉类。散脉浮大无根；濡脉浮而细软；芤脉浮大中空；革脉浮而搏指、中空外坚，四者皆浮脉类，唯微脉当除外"},{"q":"除下列哪项外均为脾肾阳虚证的大便异常表现","o":["久泻久痢","泻下清冷水液","先干后溏","完谷不化","五更泄泻"],"a":2,"e":"先干后溏是脾气虚弱、运化失常，非脾肾阳虚。脾肾阳虚火不暖土，见久泻久痢、泻下清冷水液、完谷不化、五更泄泻，此四者皆阳虚寒盛、腐熟无权之候，唯先干后溏属脾虚"},{"q":"耳鸣声小，如闻蝉鸣，按之减轻，时发时止，属于","o":["肾精亏虚","肝胆火盛","痰浊上蒙","瘀血阻滞","风邪上袭"],"a":0,"e":"肾开窍于耳，肾精亏虚、髓海不足则耳鸣声小如蝉、按之减轻、时发时止，属虚证。肝胆火盛耳鸣声大、突发、按之不减；痰浊上蒙伴头重胸闷；瘀血阻滞、风邪上袭均非此虚鸣之象"},{"q":"肝经风热常表现为","o":["睑缘赤烂","目眦淡红","白睛红赤","全目赤肿","目窠浮肿"],"a":3,"e":"肝开窍于目，肝经风热上扰则全目赤肿、羞明流泪。睑缘赤烂为脾胃湿热；目眦淡红为心血不足；白睛红赤属肺火或风热犯肺；目窠浮肿多为水肿，皆非肝经风热之全目赤肿"},{"q":"以身目发黄，色鲜明如橘，大便黏滞不爽，小便短黄，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","肝阴虚证"],"a":1,"e":"湿热蕴结肝胆，胆汁外溢则身目发黄、色鲜明如橘，湿热下注则大便黏滞、小便短黄，苔黄腻、脉弦滑数为肝胆湿热之征。寒滞肝脉见少腹冷痛；肝郁气滞见胁胀无黄；热极生风见抽搐；肝阴虚见潮热盗汗，均无此黄疸湿热象"},{"q":"舌苔厚腻如积粉，多为","o":["食积内停","时邪夹湿","痰饮上泛","痰湿化热","湿浊内盛"],"a":1,"e":"舌苔厚腻如积粉是时邪（疫疠）夹湿、秽浊内蕴之征。食积内停苔厚腻而腐；痰饮上泛苔白滑；痰湿化热苔黄腻；湿浊内盛苔白腻，均非积粉之状，唯时邪夹湿主之"},{"q":"胃脘灼痛，口气臭秽，渴喜冷饮，大便秘结，舌红苔黄，脉滑数，证属","o":["食滞胃脘证","寒滞胃脘证","胃热炽盛证","肝郁脾虚证","肝胃不和证"],"a":2,"e":"胃热炽盛、腐熟太过则胃脘灼痛、口气臭秽、渴喜冷饮、大便秘结，舌红苔黄、脉滑数。食滞胃脘见嗳腐吞酸；寒滞胃脘见冷痛喜温；肝郁脾虚见胁胀便溏；肝胃不和见胀痛嗳气，均无此胃火之象"},{"q":"临床常见的气逆证，多与下列哪些脏腑关系密切","o":["肺、脾、肾","肺、胃、肾","肺、胃、肝","心、肝、肺","心、肺、肾"],"a":2,"e":"气逆证多为肺气上逆之咳喘、胃气上逆之呕吐呃逆、肝气上逆之头痛呕血，故与肺胃肝关系密切。脾主升清、肾主纳气、心主血脉，均非气逆病变所主，故不选"},{"q":"下列哪项为紧张度较低的脉象","o":["弦脉","濡脉","紧脉","革脉","牢脉"],"a":1,"e":"濡脉浮而细软，举之有余、按之不足，紧张度低。弦脉端直以长、紧脉绷急弹指、革脉浮而搏指、牢脉沉实有力，四者紧张度均高，与濡脉之柔软相对"},{"q":"初起多为红斑，迅速形成肿胀、丘疹或水疱，继而水疱破裂、渗液，出现红色湿润之糜烂，此为","o":["缠腰火丹","阳斑","湿疹","瘾疹","热气疮"],"a":2,"e":"湿疹皮疹多形，初起红斑、迅速成肿胀丘疹水疱，破后渗液、见红色湿润糜烂，瘙痒剧烈、对称分布。缠腰火丹沿神经簇集水疱、疼痛；阳斑为斑疹；瘾疹风团时隐时现；热气疮为簇集小水疱，均无此糜烂渗液过程"},{"q":"自言自语，喃喃不休，见人语止，首尾不续者称为","o":["错语","独语","谵语","郑声","狂言"],"a":1,"e":"独语喃喃自语、见人语止、首尾不续，多因心气不足、痰蒙心神，见于癫证。错语说后自知错误；谵语神昏胡言、声高有力；郑声神志不清、语言重复、声音低微；狂言躁妄叫骂，皆与独语有别"},{"q":"属于中医住院病历个人史的是","o":["起病情况","生活习惯","伴随症状","发病以来诊治经过及结果","发病以来一般情况"],"a":1,"e":"个人史记录生活习惯、嗜好、职业、居处、性格等。起病情况、伴随症状、发病以来诊治经过及一般情况均属现病史内容，由询问疾病发生发展而得，不属个人史"},{"q":"不属于瘟黄辨证要点的是","o":["来势凶猛","高热神昏","猝然发黄","苔白如积粉","出血发斑"],"a":3,"e":"瘟黄（急黄）湿热疫毒炽盛，来势凶猛、猝然发黄、高热神昏、出血发斑，病势险恶。苔白如积粉是时邪夹湿、湿温之苔，非瘟黄辨证要点；其余四项皆瘟黄危重之征"},{"q":"燥邪犯肺证见恶寒发热、无汗、脉浮紧，属","o":["秋燥","温燥","凉燥","内燥","风燥"],"a":2,"e":"凉燥为秋燥偏寒，燥与寒合，故见恶寒发热、无汗、脉浮紧等表寒象。温燥见身热重、有汗、脉浮数、咽干口渴；内燥为脏腑津亏、无表证；秋燥为总称；风燥非规范分型，均不符此表寒脉紧之候"},{"q":"下列各项中属于营分证临床表现的是","o":["发热微恶寒","头痛","咽喉肿痛","舌绛","脉浮数"],"a":3,"e":"舌绛是营分证标志，热入营阴、营热蒸腾，兼身热夜甚、心烦不寐、斑疹隐隐、脉细数。发热微恶寒、头痛、脉浮数均为表证；咽喉肿痛属肺系热，皆非营分所见"},{"q":"症见咳嗽痰黄，伴发热微恶风寒，咽喉肿痛，舌苔薄黄，脉浮数，宜辨证为","o":["风热表证","风热犯肺证","肺热炽盛证","痰热壅肺证","燥邪犯肺证"],"a":1,"e":"风热犯肺、肺失清肃则咳嗽痰黄，兼发热微恶风寒、咽喉肿痛、苔薄黄、脉浮数等表热象。风热表证以表证为主、咳较轻；肺热炽盛为里实热、无恶寒；痰热壅肺痰多黄稠；燥邪犯肺干咳少痰，均非此证"},{"q":"病人的病情表现不宜称作","o":["症状","病候","病机","病形","病状"],"a":2,"e":"病机是疾病发生发展的内在机制，属本质层面，非病情外在表现。症状、病候、病形、病状均可指病人表现于外的异常，唯病机当除外"},{"q":"下列各项，不属于构成躯体身形的基本要素的是","o":["皮","肉","脉","络","筋"],"a":3,"e":"躯体身形基本要素为皮、肉、脉、筋、骨五体。络为经络之分支，属经络系统，不在五体之列；皮、肉、脉、筋皆五体之一，唯络不属构成身形的基本要素"},{"q":"小腹刺痛，小便自利者，为","o":["膀胱虚寒","寒凝肝脉","虫积","脾胃虚寒","蓄血"],"a":4,"e":"蓄血证瘀热结于下焦，少腹硬满刺痛，因病在血分、膀胱气化未受影响，故小便自利。膀胱虚寒见小便清长；寒凝肝脉见少腹冷痛、牵引阴器；虫积见脐周绞痛；脾胃虚寒见腹部冷痛喜温，皆非蓄血"},{"q":"肝火上炎证最易出现的脉象是","o":["滑数脉","浮滑脉","弦数脉","洪数脉","弦紧脉"],"a":2,"e":"肝火上炎、肝经热盛，肝脉弦、热盛则数，故最常见弦数脉。滑数主痰热；浮滑主风痰；洪数主气分热盛；弦紧主寒凝、痛证，均与肝火上炎之脉不符"},{"q":"红黄隐隐，明润含蓄的面色是","o":["病色","常色","善色","恶色","主色"],"a":1,"e":"常色红黄隐隐、明润含蓄，是精气充足、气血调和之正常面色。病色晦暗暴露；善色虽病而润泽；恶色晦暗枯槁、夭然不泽；主色为个体终生固有之色，皆非红黄隐隐明润含蓄之常色定义"},{"q":"主阴寒内盛，疝气癥瘕的脉象是","o":["革脉","牢脉","实脉","结脉","洪脉"],"a":1,"e":"牢脉沉按实大弦长、坚牢不移，主阴寒内盛、疝气癥瘕。革脉浮而搏指、中空外坚，主亡血失精；实脉浮沉皆有力；结脉缓而时止；洪脉浮大有力、来盛去衰，皆非牢脉"},{"q":"囟陷多属虚证，多因","o":["脑髓有病","温病火邪上攻","吐泻伤津、气血不足","颅内水液停聚","脾肾阳虚"],"a":2,"e":"囟陷多因吐泻伤津、气血不足，脑髓失养、颅骨失充所致，属虚证。脑髓有病或颅内水液停聚多致囟填隆起；温病火邪上攻亦致囟填；脾肾阳虚非婴幼儿囟陷之主因"},{"q":"下列各项，不属脾不统血证的临床表现的是","o":["皮肤紫斑","面色无华","少气懒言","口臭龈肿齿衄","神疲乏力"],"a":3,"e":"口臭龈肿齿衄是胃火上炎、灼伤龈络。脾不统血见皮肤紫斑、便血尿血崩漏，兼面色无华、少气懒言、神疲乏力等气虚失摄之象，此四项皆其表现，唯口臭龈肿齿衄属胃热"},{"q":"下列不属表证特点的是","o":["外感邪气","起病急","必发展成里证","病情轻","病程短"],"a":2,"e":"表证由外感邪气所致，起病急、病情轻、病程短，未必内传入里。表证可汗出而解，不必发展成里证；外感邪气、起病急、病情轻、病程短皆表证特点，唯必发展成里证说法绝对，当除外"},{"q":"虚实辨证用以辨别","o":["病势","病因","病位","病名","邪正盛衰"],"a":4,"e":"虚实辨证辨别邪正盛衰，邪气盛则实、精气夺则虚。病势由表里出入、寒热转化等辨；病因由病因辨证；病位由脏腑经络辨证；病名属辨病，皆非虚实所辨"},{"q":"虚里搏动正常者应为","o":["搏动微弱","散慢不收","搏动应衣","动而不紧","弹手有力"],"a":3,"e":"正常虚里搏动动而不紧、缓而不怠、节律一致。搏动微弱为宗气不足；散慢不收为宗气大虚；搏动应衣为宗气外泄；弹手有力为宗气太过，均非正常之象"},{"q":"判断气血盛衰的主要依据是","o":["舌体的颜色","舌苔的厚薄","舌体的动态","舌苔的颜色","舌下络脉"],"a":0,"e":"舌色直接反映气血盛衰，淡白为气血虚、红绛为热、青紫为瘀。舌苔厚薄辨邪气盛衰与病位浅深；舌体动态辨筋脉病变；舌苔颜色辨病性寒热；舌下络脉辨瘀血，皆非气血盛衰之主据"},{"q":"鉴别表证与里证主要根据","o":["寒热是否并见","头痛轻重","腹痛喜按拒按","咳嗽有无黄痰","脉象迟数"],"a":0,"e":"表证恶寒发热同时并见，里证但热不寒或但寒不热，故寒热是否并见为鉴别表里之主据。头痛轻重、腹痛喜按拒按、咳嗽痰色、脉象迟数均非辨别表里的关键，不能据此定表里"},{"q":"下列与虚喘发作关系最密切的是","o":["心肺","肝肺","肺肾","脾肺","脾肾"],"a":2,"e":"虚喘因肺虚气短、肾虚不能纳气，气不归元，病在肺肾。心肺多为实证或心脉瘀阻之喘；肝肺、脾肺、脾肾虽相关，但虚喘发作以肺肾两虚、肾不纳气最为密切"},{"q":"结、代、促脉的共同点是","o":["脉来急数","脉来时止","脉来迟缓","止有定数","止无定数"],"a":1,"e":"结、代、促三者均见脉来时止、节律不齐。促脉数而时止、止无定数；结脉缓而时止、止无定数；代脉止有定数、良久方还；脉来急数仅促、脉来迟缓仅结、止有定数仅代，唯时止为三者共有"},{"q":"下列哪项属于危重舌象","o":["歪斜舌","裂纹舌","胖嫩舌","紫黯舌","镜面舌"],"a":4,"e":"镜面舌舌苔全部剥落、光滑如镜，是胃气将绝、胃阴枯竭之危重舌象。歪斜舌为中风；裂纹舌主阴血亏虚；胖嫩舌主阳虚水湿；紫黯舌主瘀血，皆非危重之舌"},{"q":"下列哪一项不属于浮脉类","o":["濡脉","散脉","革脉","动脉","芤脉"],"a":3,"e":"浮脉类包括浮、洪、濡、散、芤、革，脉位偏浮。动脉滑数而短、厥厥动摇、关部明显，不属浮脉类；濡脉、散脉、革脉、芤脉皆浮脉类，唯动脉当除外"},{"q":"下列哪项不是失眠的常见原因","o":["痰湿内蕴","心胆气虚","心肾不交","肝郁化火","食滞内停"],"a":0,"e":"失眠多因心脾两虚、心肾不交、肝郁化火、心胆气虚、食滞内停（胃不和则卧不安）等。痰湿内蕴虽可困脾，但非失眠直接常见原因；上述心胆气虚、心肾不交、肝郁化火、食滞内停皆失眠常见"},{"q":"肺热壅盛，痰多表现为","o":["痰黄稠","痰脓血腥臭","痰清稀","痰白黏稠","痰稀有泡沫"],"a":0,"e":"肺热壅盛、热灼津液，故痰黄稠。痰脓血腥臭是肺痈；痰清稀或多泡沫为寒饮、风水；痰白黏稠多属湿痰或燥痰，皆非肺热壅盛之黄稠痰"},{"q":"大便中夹杂有脓血黏液者，属于","o":["肝郁脾虚","脾肾阳虚","食滞胃肠","脾气亏虚","大肠湿热"],"a":4,"e":"大肠湿热、传导失司，湿热灼伤肠络则大便夹脓血黏液，伴里急后重。肝郁脾虚见腹痛即泻；脾肾阳虚见五更泄；食滞胃肠见泻下腐臭；脾气亏虚见便溏，均无脓血黏液"},{"q":"关节痛剧，伴肿大变形，屈伸受限者，属于","o":["行痹","痛痹","热痹","尪痹","着痹"],"a":3,"e":"尪痹为痹证日久、肝肾亏虚、痰瘀凝滞，关节疼痛剧烈、肿大变形、屈伸受限。行痹疼痛游走不定；痛痹遇寒痛甚但无变形；热痹关节红肿热痛；着痹重着麻木，皆无关节变形"},{"q":"下列各项，不属气虚证表现的是","o":["神疲乏力","少气懒言","头晕眼花","活动后诸症加剧","尿频清长"],"a":4,"e":"尿频清长是肾气不固或阳虚、水道失约。气虚证见神疲乏力、少气懒言、头晕眼花、活动后诸症加剧，此四者皆气虚推动无力、功能减退之候，唯尿频清长不属气虚证典型表现"},{"q":"下列哪一项属脉症不相应","o":["表证见浮脉","里证见沉脉","久病见浮脉","暴病见浮脉","暴病见洪脉"],"a":2,"e":"久病正气亏虚，脉当沉细，反见浮脉是虚阳外越、脉症不相应。表证见浮脉、暴病见浮脉或洪脉皆邪盛于表、脉症相应；里证见沉脉亦相应，唯久病见浮脉为不相应"},{"q":"下列哪项不属于气虚证的表现","o":["神疲乏力","畏寒肢冷","少气懒言","舌质淡嫩","脉虚"],"a":1,"e":"畏寒肢冷是阳虚证、温煦失职。气虚证见神疲乏力、少气懒言、舌质淡嫩、脉虚，此四者皆气虚之候；畏寒肢冷属阳虚，非单纯气虚所有"},{"q":"小儿发结如穗，多属","o":["禀赋不足","血虚受风","疳积","精血不足","血热"],"a":2,"e":"疳积患儿脾胃受损、营养失调，故发结如穗、干枯稀疏。禀赋不足见毛发稀疏；血虚受风见斑秃；精血不足见发枯早脱；血热见发黄赤，皆非发结如穗之疳积特征"},{"q":"下列主诉哪项最正确","o":["5年来右胁胀痛","患高血压病1年","经常腹痛已多年","发热、咳嗽2天","咳喘反复发作20年"],"a":3,"e":"主诉为核心症状加持续时间，发热、咳嗽2天简明规范。右胁胀痛仅列症状、欠时间要素；患高血压病1年用病名代症状；经常腹痛已多年、咳喘反复发作20年时限模糊，均不及发热咳嗽2天规范"},{"q":"解索脉的脉象是","o":["如釜中沸水，浮泛无根","短小坚搏，如循薏苡子","如屋漏残滴，良久一滴","脉在筋肉之间，乍疏乍密，如解乱绳状","脉在皮肤，头定尾摇，似有似无"],"a":3,"e":"解索脉为七怪脉之一，脉在筋肉之间、乍疏乍密、如解乱绳，是元气将绝之象。釜中沸水、浮泛无根为釜沸脉；短小坚搏、如循薏苡子为弹石脉；良久一滴如屋漏残滴为屋漏脉；头定尾摇、似有似无为鱼翔脉"},{"q":"区别血分证和营分证的基本要点是","o":["身热躁扰","昏狂谵语","斑疹隐隐","吐血衄血","舌质红绛"],"a":3,"e":"血分证热盛动血，迫血妄行则吐血衄血、斑疹显露，此为与营分证之基本区别。身热躁扰、昏狂谵语二者均可见；斑疹隐隐为营分；舌质红绛二者共有；唯吐血衄血为血分动血所独有"},{"q":"可使舌苔染白的食物或药物是","o":["蛋黄","橘子","牛乳","吸烟","核黄素"],"a":2,"e":"牛乳、豆浆等白色饮品可使舌苔染白，属染苔假象。蛋黄、橘子含色素使苔染黄；吸烟使苔灰黑或黄；核黄素使苔黄染，皆非染白之物"},{"q":"弱脉与濡脉的不同之处主要在于","o":["脉势","脉长","脉位","至数","脉宽"],"a":2,"e":"弱脉与濡脉皆细软无力，区别在脉位：弱脉沉、须重按，濡脉浮、轻取即得。脉势二者均软弱；脉长、至数、脉宽非二者主要区别，唯脉位为关键"},{"q":"舌色青多见于","o":["阳虚气不化津","气血不足","寒凝血瘀","营血热盛","痰湿中阻"],"a":2,"e":"青舌主寒凝血瘀、筋脉拘急，故舌色青多见于寒凝血瘀。阳虚气不化津多见淡胖舌；气血不足见淡白舌；营血热盛见红绛舌；痰湿中阻见苔腻而舌不青，皆非青舌主病"},{"q":"下列哪项不属于心阳暴脱证的辨证要点","o":["心悸怔忡","心胸疼痛","神志昏糊","畏寒怕冷","亡阳症状"],"a":3,"e":"心阳暴脱以心悸怔忡、心胸剧痛、神志昏糊及亡阳症状（大汗淋漓、四肢厥冷、脉微欲绝）为辨证要点。畏寒怕冷是心阳虚一般表现，尚未至暴脱；上述心悸、胸痛、神昏、亡阳皆暴脱要点"},{"q":"下列哪一项一般不会出现面色苍白","o":["亡阳证","血脱证","阴寒凝滞","脾胃气虚","大失血之人"],"a":3,"e":"脾胃气虚、气血生化不足，见面色萎黄少华而非苍白。亡阳证阳气暴脱、血脱证与大失血之人血脉空虚、阴寒凝滞血脉收引，均可见面色苍白，唯脾胃气虚不现苍白"},{"q":"下列脉象中不主痰饮证的脉象是","o":["滑脉","弦脉","促脉","结脉","濡脉"],"a":4,"e":"濡脉主虚证、湿证，不主痰饮。滑脉主痰饮；弦脉主饮；促脉、结脉可因痰饮阻滞气机、脉行不畅而见，均与痰饮相关；唯濡脉属虚湿，非痰饮主脉"},{"q":"小儿睡眠露睛，最常见的原因是","o":["脾气虚弱","外伤所致","先天不足","气血亏虚","肾精亏损"],"a":0,"e":"小儿睡眠露睛（眼睑闭合不全）多因脾气虚弱、气血不足，眼睑失养、肌肉无力。外伤所致有外伤史；先天不足、肾精亏损多影响生长发育；气血亏虚可致但以脾气虚弱为常见"},{"q":"有形实邪阻闭气机所致疼痛多为","o":["隐痛","窜痛","绞痛","胀痛","重痛"],"a":2,"e":"绞痛为有形实邪（结石、瘀血、蛔虫）阻闭气机、不通则痛，痛势剧烈如绞。隐痛多属虚证；窜痛为气滞或风邪；胀痛为气滞；重痛为湿邪困阻，皆非实邪阻闭之绞痛"},{"q":"兼具沉、弦、实、大、长五脉之象，坚牢不移的脉象是","o":["沉脉","长脉","伏脉","牢脉","实脉"],"a":3,"e":"牢脉兼具沉、弦、实、大、长五脉之象，坚牢不移、沉按乃得。沉脉仅脉位沉；长脉仅脉体长；伏脉需推筋着骨；实脉浮沉皆有力但无弦长坚牢之相，皆非牢脉"},{"q":"以下哪项表现为疮疡红肿高大，根盘紧束，焮热疼痛","o":["疽","痈","疔","疖","丹毒"],"a":1,"e":"痈为阳证疮疡，气血壅聚，见疮疡红肿高大、根盘紧束、焮热疼痛。疽为阴证、漫肿无头、皮色不变；疔形小根深、坚硬如钉；疖形小而浅；丹毒皮肤焮红成片、边界清楚，皆非痈之高大焮痛"},{"q":"脉不见于寸口，而从尺部斜向手背，称为","o":["斜飞脉","反关脉","鱼翔脉","虾游脉","雀啄脉"],"a":0,"e":"斜飞脉为桡动脉先天走行变异，脉不见于寸口、从尺部斜向手背。反关脉是脉见于腕背而寸口无脉；鱼翔、虾游、雀啄皆七怪脉、属危重病脉，非位置变异"},{"q":"血分证与营分证的共有症状是","o":["身热夜甚","吐血衄血","手足蠕动","目睛上视","颈项强直"],"a":0,"e":"身热夜甚是热入营血、阴液受损的共同表现，血分证与营分证均可见。吐血衄血仅血分动血；手足蠕动、目睛上视、颈项强直为热极生风或肝风内动，非二者共有"},{"q":"根据《灵枢•五色》划分法将面部分为不同部位并给予命名，其中颊侧命名为","o":["庭","阙","名堂","蔽","藩"],"a":4,"e":"《灵枢·五色》分部命名：庭为额、阙为眉间、明堂为鼻、蔽为耳门、藩为颊侧。颊侧当名藩，庭、阙、明堂、蔽各有所指，皆非颊侧之名"},{"q":"痰热壅肺证，舌象可见","o":["舌淡嫩胖，苔白润滑","舌质红，苔黄厚腻","舌红少苔而有裂纹","舌淡红，苔白腻","舌绛红，苔黄燥"],"a":1,"e":"痰热壅肺，痰热互结、灼伤津液，故舌质红、苔黄厚腻。舌淡嫩胖、苔白润滑为阳虚水湿；舌红少苔有裂纹为阴虚；舌淡红苔白腻为寒痰湿痰；舌绛红苔黄燥为热入营血，皆非痰热壅肺之舌"},{"q":"鼓胀重证中，常与腹部膨隆同时出现的是","o":["脊柱后突","脊柱侧弯","肋如串珠","漏斗胸","腹露青筋"],"a":4,"e":"鼓胀重证肝脾肾功能失调、气滞血瘀水停，腹大胀满，兼腹露青筋（腹壁静脉曲张）。脊柱后突、侧弯、肋如串珠、漏斗胸皆胸廓或脊柱畸形，与腹部膨隆无涉"},{"q":"儿童常见，发作前，咳嗽喷嚏，眼泪汪汪，耳后有红丝出现；发热三四日，疹点从头面到胸腹四肢，形如麻粒，抚之触手，此为","o":["痱子","风疹","湿疹","隐疹","麻疹"],"a":4,"e":"麻疹前驱期有咳嗽喷嚏、眼泪汪汪、耳后红丝，发热三四日后疹点自头面自上而下波及胸腹四肢，形如麻粒、抚之触手。风疹疹细稀疏、消退快；湿疹多形渗出；瘾疹风团时隐时现；痱子为汗腺堵塞之小疹，皆非麻疹"},{"q":"舌苔腻而滑，多为","o":["时邪夹湿","外感风寒","食积内停","痰饮上泛","痰湿化热"],"a":3,"e":"苔腻而滑是痰饮上泛、湿浊内停之象。时邪夹湿苔厚腻如积粉；外感风寒苔薄白；食积内停苔厚腻而腐；痰湿化热苔黄腻，皆非腻滑之苔，唯痰饮上泛主之"},{"q":"可作为鉴别燥邪犯肺证与肺阴虚证的症状是","o":["发热恶寒","痰中带血","口唇干燥","尿少便干","痰少而黏"],"a":0,"e":"发热恶寒是外感表证之象，燥邪犯肺属外感、故见之；肺阴虚属内伤，无表证，但见潮热盗汗、五心烦热，此为二者鉴别关键。痰中带血、口唇干燥、尿少便干、痰少而黏二者均可见，不足以鉴别"},{"q":"紧脉的脉象特征是","o":["如按琴弦","如按葱管","如按鼓皮","如牵绳转索","如按刀刃"],"a":3,"e":"紧脉绷急弹指、状如牵绳转索，主寒证、痛证。如按琴弦为弦脉；如按葱管为芤脉；如按鼓皮为革脉；如按刀刃非紧脉特征描述，皆非紧脉"},{"q":"浮大中空的脉象是","o":["散脉","革脉","洪脉","芤脉","濡脉"],"a":3,"e":"芤脉浮大中空、如按葱管，主失血伤阴。散脉浮大无根、至数不齐；革脉浮而搏指、中空外坚；洪脉浮大有力、来盛去衰；濡脉浮而细软，皆非浮大中空之芤脉"},{"q":"观察舌苔，辨别病位的深浅主要依据","o":["舌苔的有无","舌苔的润燥","舌苔的厚薄","舌苔的颜色","舌苔的有根与无根"],"a":2,"e":"苔之厚薄辨病位深浅，薄苔主表、病位浅，厚苔主里、病位深。苔的有无及有根无根辨胃气存亡；润燥辨津液盈亏；颜色辨病性寒热，皆非辨病位深浅之主据"},{"q":"“望色十法”中“浮沉”是判断病情的","o":["表里","虚实","阴阳","轻重","新久"],"a":0,"e":"望色十法中浮沉分表里，浮主表证、沉主里证。微甚定虚实；清浊辨阴阳；散抟分新久；泽夭判成败，皆非浮沉所主，故浮沉对应表里"},{"q":"五色晦暗枯槁者为","o":["主色","客色","善色","恶色","病色"],"a":3,"e":"恶色五色晦暗枯槁、夭然不泽，主病重、预后差。主色为个体固有之色；客色随环境时令变化；善色虽病而光明润泽；病色泛指异常色泽，皆非晦暗枯槁之恶色"},{"q":"饭后嗜睡，神倦，食少纳呆者，为","o":["热入心包","肝阳化风","痰湿困脾","心肾阳虚","中气不足"],"a":4,"e":"中气不足、脾胃虚弱，清阳不升则饭后嗜睡、神倦、食少纳呆。热入心包见神昏谵语；肝阳化风见眩晕肢颤；痰湿困脾见头重如裹、胸闷苔腻；心肾阳虚见嗜睡畏寒、肢冷脉微，皆非中气不足之单纯食少神倦"},{"q":"下列哪项对诊断膀胱湿热证最无意义","o":["血尿","尿频","尿痛","尿急","尿失禁"],"a":4,"e":"尿失禁是肾气不固、下元虚损或中气下陷、膀胱失约。膀胱湿热见尿频、尿急、尿痛、血尿，此四者皆湿热下注之候，与尿失禁之虚象相反，故尿失禁最无意义"},{"q":"长期微热，烦劳则甚，兼见少气自汗，属","o":["湿温潮热","气虚发热","阴虚潮热","阳明潮热","气郁发热"],"a":1,"e":"气虚发热因脾胃气虚、阳气虚浮，故长期微热、烦劳则甚，兼少气自汗。湿温潮热身热不扬、午后热甚；阴虚潮热午后夜间、盗汗；阳明潮热日晡热甚、便秘；气郁发热与情志相关，皆非气虚发热"},{"q":"鼻头红肿生疮，多属","o":["胃热或血热","肺胃湿热","外感风热","湿热郁结","阴虚肺燥"],"a":0,"e":"鼻头属脾、胃脉所过，鼻头红肿生疮多因胃热或血热上壅。肺胃湿热见面鼻油腻、痤疮；外感风热见鼻塞流涕；湿热郁结、阴虚肺燥均非鼻头红肿生疮之主因"},{"q":"色红或青紫，点大成片，平摊于皮肤下，摸之不碍手，此为","o":["痈","疹","斑","疽","痱子"],"a":2,"e":"斑色红或青紫、点大成片、平铺皮下、抚之不碍手。疹形小如粟粒、高出皮面、抚之碍手；痈、疽为疮疡肿疡；痱子为汗疹，皆非斑之平铺皮下、摸之不碍手"},{"q":"下列各项，不属既往史内容的是","o":["居住或旅游过的地域","曾接受过何种预防接种","以往患过何种其他疾病","是否做过何种手术治疗","有无药物之类的过敏史"],"a":0,"e":"居住或旅游过的地域属个人史（社会经历），不属既往史。预防接种、以往所患疾病、手术史、药物过敏史均属既往史内容，记录既往健康状况与防治经历，唯地域居处当归入个人史"},{"q":"口甜而黏腻多为","o":["肝脾不和","脾胃气虚","肝胆湿热","脾胃湿热","肝胃不和"],"a":3,"e":"口甜而黏腻是脾胃湿热、浊气上泛。肝脾不和见胁胀、口苦；脾胃气虚见口淡乏味；肝胆湿热见口苦、胁痛；肝胃不和见口苦、嗳气吞酸，皆非口甜黏腻之脾胃湿热"},{"q":"热极生风证与肝阳化风证均可见到的症状是","o":["高热","头重脚轻","肢体抽搐","角弓反张","腰膝酸软"],"a":2,"e":"肢体抽搐是肝风内动的共同表现，热极生风与肝阳化风均可见。高热仅热极生风；头重脚轻、腰膝酸软为肝阳化风（阴虚阳亢）之象；角弓反张多见热极、痉证，非二者共有"},{"q":"舌淡苔黑滑者，多属","o":["痰火内蕴","阴虚火旺","热盛伤津","阳虚寒盛","湿热郁蒸"],"a":3,"e":"舌淡苔黑而滑润是阳虚寒盛、寒湿内阻，津液不化。痰火内蕴、热盛伤津、阴虚火旺均见苔黑而燥；湿热郁蒸见苔黄腻，皆非黑滑之寒象，唯阳虚寒盛主之"},{"q":"面色与口唇青紫者，多属","o":["阴寒内盛","肝郁脾虚","心血瘀阻","高热抽搐","胁下癥积"],"a":2,"e":"心主血脉，心血瘀阻、血脉不通，则面色与口唇青紫。阴寒凝滞见面色青白；肝郁脾虚见面色萎黄、胁胀；高热抽搐为热极生风；胁下癥积为瘀血积块，皆非心血瘀阻之面唇青紫"},{"q":"脉形如豆，滑数而短，厥厥动摇，关部尤显，是","o":["微脉","动脉","疾脉","结脉","弱脉"],"a":1,"e":"动脉脉形如豆、滑数而短、厥厥动摇、关部尤显。微脉极细极软；疾脉一息七八至；结脉缓而时止；弱脉沉细而软，皆非动脉之滑数如豆、动摇关部"},{"q":"鱼翔脉的脉象是","o":["短小坚搏，如循薏苡子","如釜中沸水，浮泛无根","如屋漏残滴，良久一滴","脉在皮肤，时而跃然而去，须臾又来","脉在皮肤，头定尾摇，似有似无"],"a":4,"e":"鱼翔脉为七怪脉之一，脉在皮肤、头定尾摇、似有似无，如鱼游翔。短小坚搏、如循薏苡子为弹石脉；釜中沸水、浮泛无根为釜沸脉；良久一滴如屋漏残滴为屋漏脉；脉在皮肤、时而跃然而去、须臾又来为虾游脉"},{"q":"下列关于实证和虚证鉴别错误的是","o":["实证疼痛拒按，虚证疼痛喜按","实证多发热，虚证多恶寒","实证声高气粗，虚证声低息微","实证舌质老，虚证舌质嫩","实证脉有力，虚证脉无力"],"a":1,"e":"虚实鉴别中，实证可发热，虚证亦可发热（阴虚潮热、气虚发热），虚证多恶寒说法片面，为错误项。疼痛拒按与喜按、声高气粗与声低息微、舌质老与嫩、脉有力与无力，皆正确的虚实鉴别"},{"q":"下列除哪项外，皆肾气不固所致","o":["尿频而清","余沥不尽","小便失禁","尿频而痛","遗尿"],"a":3,"e":"尿频而痛是淋证、膀胱湿热，气化不利、水道涩痛。肾气不固见尿频而清、余沥不尽、小便失禁、遗尿，此四者皆肾虚失固之候；唯尿频而痛属湿热实证，非肾气不固"},{"q":"“O”形腿又称","o":["膝内翻","膝外翻","足内翻","足外翻","鹤膝风"],"a":0,"e":"O形腿即膝内翻，两膝向内靠拢、两足外撇呈O状。膝外翻为X形腿、两膝分开；足内翻、足外翻为足部畸形；鹤膝风为膝关节肿大、形如鹤膝，皆非O形腿"},{"q":"舌体瘦薄而色淡者，多属","o":["阴津亏虚","热盛津伤","气血两虚","阳气亏虚","寒湿内蕴"],"a":2,"e":"舌体瘦薄而色淡是气血两虚、舌体失养。阴津亏虚、热盛津伤见舌瘦薄而红绛；阳气亏虚见舌淡胖嫩；寒湿内蕴见舌淡胖、苔白腻，皆非瘦薄色淡之气血两虚"},{"q":"面色紫黯黧黑，伴有肌肤甲错多因","o":["肾阴亏虚","瘀血阻络","肾虚水饮","肾气亏虚","肾阳亏虚"],"a":1,"e":"瘀血阻络、日久不化，见面色紫黯黧黑、肌肤甲错、舌质紫黯。肾阴亏虚见颧红潮热；肾虚水饮见面黑带紫、水肿；肾气亏虚、肾阳亏虚见面色暗淡，但均无肌肤甲错之瘀血特征"},{"q":"下列哪项不符合斑的临床表现","o":["点大成片","色深红或青紫","平铺于皮下","压之退色","抚之不碍手"],"a":3,"e":"斑平铺皮下、压之不退色，是其特点；压之退色为疹的表现，不符合斑。点大成片、色深红或青紫、平铺于皮下、抚之不碍手皆斑的临床表现，唯压之退色不属斑"},{"q":"疟疾可见","o":["浮脉","弦脉","芤脉","散脉","洪脉"],"a":3,"e":"官方答案为【散脉】，但依据教材，正确答案为【弦脉】。弦脉端直以长，主肝胆病、疼痛、痰饮与疟疾，疟脉自弦即指疟疾常见弦脉。散脉浮大无根、按之渐无，主元气离散、脏腑精气将绝，为危重之象，与疟疾无涉。浮脉主表、芤脉主失血伤阴、洪脉主热盛，皆非疟疾典型脉"},{"q":"睡中咬牙啮齿，多辨证为","o":["肾阴虚","胃热或虫积","肝风内动","阳明热盛","脾虚"],"a":1,"e":"睡中咬牙啮齿（齘齿）多因胃热或虫积，胃热炽盛、虫扰不安致咀嚼肌痉挛。肾阴虚见牙齿松动；肝风内动见抽搐；阳明热盛见谵语、烦躁；脾虚见磨牙声轻，皆非胃热虫积之咬牙"},{"q":"濡脉的脉象是","o":["浮数无根","浮而细软","沉细而软","浮大无力","脉细如线"],"a":1,"e":"濡脉浮而细软、轻取即得。浮数无根为散脉；沉细而软为弱脉，脉位沉；浮大无力为虚脉；脉细如线为细脉，皆非濡脉之浮而细软"},{"q":"尿后余沥不尽多因下列何项所致","o":["肾精不足","肾阴亏虚","瘀血内阻","肾气不固","结石阻塞"],"a":3,"e":"尿后余沥不尽是肾气不固、下元虚损，膀胱失约、固摄无权。肾精不足主生殖发育迟缓；肾阴亏虚见潮热盗汗；瘀血内阻、结石阻塞见排尿艰涩、刺痛，皆非肾气不固之余沥"},{"q":"风热犯肺证与肺热炽盛证的鉴别，可根据是否伴有","o":["咽喉肿痛","口干口渴","咳脓血痰","恶寒发热","苔黄脉数"],"a":3,"e":"风热犯肺有发热微恶风寒等表证，肺热炽盛为里实热、但热不寒，故恶寒发热有无为二者鉴别点。咽喉肿痛、口干口渴、苔黄脉数二者均可见；咳脓血痰为肺痈，非二者鉴别依据"},{"q":"下列不属于正常脉象的生理变异的是","o":["妊娠期脉常见滑数而冲和","老人脉多兼弦","运动员脉多缓而有力","发热后脉滑数有力","瘦人脉偏浮"],"a":3,"e":"发热后脉滑数有力是病理反应，不属正常生理变异。妊娠脉滑数而冲和、老人脉多弦、运动员脉缓而有力、瘦人脉偏浮，皆因体质、年龄、生理状态不同而形成的正常脉象变异"},{"q":"脉沉细，应指无力，为","o":["微脉","细脉","濡脉","弱脉","虚脉"],"a":3,"e":"弱脉沉细而软、应指无力，须重按始得。微脉极细极软、按之欲绝；细脉脉细如线但应指有力；濡脉浮而细软、脉位浮；虚脉浮大无力，皆非弱脉之沉细应指无力"},{"q":"热势较高，日晡热甚，兼腹胀便秘者，属","o":["气分壮热","骨蒸潮热","阳明潮热","湿温潮热","气郁发热"],"a":2,"e":"阳明潮热（日晡潮热）热势较高、日晡申时热甚，兼腹胀便秘，因阳明腑实、燥屎内结。气分壮热持续高热、不按时辰；骨蒸潮热午后夜间、盗汗；湿温潮热身热不扬、苔腻；气郁发热随情志波动，皆非阳明腑实之潮热"},{"q":"痰湿内阻的特征表现是","o":["胸闷气短","胸闷气喘","胸闷胁胀","胸闷刺痛","胸闷痰多"],"a":4,"e":"痰湿内阻、津液不化，故胸闷、痰多，为特征表现。胸闷气短多为心肺气虚；胸闷气喘为痰饮壅肺、肺气上逆；胸闷胁胀为肝郁气滞；胸闷刺痛为心血瘀阻，皆非痰湿内阻之胸闷痰多"},{"q":"以重手按压或推寻身体的局部，以了解其深部有无压痛或肿块，称为","o":["按法","触法","摸法","叩法","诊法"],"a":0,"e":"按诊中以重手按压或推寻局部，了解深部有无压痛或肿块，称为按法。触法为轻手触摸体表；摸法为探查肿块形态；叩法为叩击听声；诊法为四诊总称，皆非重手按压之按法"},{"q":"属于八纲证候错杂关系的是","o":["真寒假热证","上热下寒证","实证转虚证","表实热证","里虚寒证"],"a":1,"e":"上热下寒属寒热错杂，是八纲证候错杂关系之一。真寒假热属证候真假；实证转虚属证候转化；表实热证、里虚寒证为表里与寒热虚实相兼之单纯证候，非典型的寒热、虚实错杂关系"},{"q":"证候真假的“假”是指","o":["临床不常见的症状表现","因个体差异而出现的特殊表现","病人叙述虚假的病情资料","起病时出现，一段时间后消失的症状","与病理本质不符的症"],"a":4,"e":"证候真假之假指与疾病病理本质不符的临床表现，如真寒假热之假热。临床不常见症状、个体差异表现、病人叙述虚假、起病短暂症状均非假的准确定义，唯与本质不符之症当之"},{"q":"下列哪一项不是热证的表现","o":["舌鲜红少苔","苔灰黑而干燥","舌红苔黄","舌红绛而痿软","舌质淡而青紫湿润"],"a":4,"e":"舌质淡而青紫湿润是寒证、阳虚或瘀血之象，非热证。舌鲜红少苔、苔灰黑而干燥、舌红苔黄、舌红绛而痿软皆热盛伤津、阴虚火旺之舌，属热证表现，唯淡而青紫湿润当除外"},{"q":"肠燥津亏证与肠热腑实证的鉴别可根据","o":["有无大便干燥","有无小便短少","有无舌红苔黄","有无腹满坚硬","有无腹胀疼痛"],"a":3,"e":"肠燥津亏与肠热腑实均见大便干结，但肠热腑实为实热内结，兼腹满硬痛拒按、潮热谵语、舌红苔黄燥、脉沉实；肠燥津亏为津亏肠燥，无腹满坚硬，见舌红少津、脉细涩。有无大便干燥为二者共有，小便短少与舌红苔黄非鉴别关键，腹胀疼痛亦可见于气滞"},{"q":"不属现病史内容的是","o":["发病情况","病变过程","做过何诊断","经过哪些治疗","过去患过何病"],"a":4,"e":"现病史记述本次疾病的发生、演变与诊治经过，含发病情况、病变过程、所作诊断及治疗经过。过去患过何病属既往史，记录既往疾病与健康状况，不属现病史。发病情况与病变过程为现病史主体，做过何诊断、经过哪些治疗属诊治经过，均归现病史"},{"q":"虚脉的脉象特征为","o":["举之泛泛有，重按稍减而不空","三部脉举之无力，按之空虚","浮大中空，如按葱管","浮散无力，漫无根蒂，稍用力则按不着","浮而细软"],"a":3,"e":"官方答案为【浮散无力，漫无根蒂，稍用力则按不着】，但依据教材，正确答案为【三部脉举之无力，按之空虚】。虚脉为无力脉的总称，三部九候举之无力、按之空虚，应指松软。原答案所述浮散无根、稍按即无是散脉的特征，散脉主气血散脱，与虚脉三部皆无力不同。举之泛泛有、重按稍减而不空为浮脉，浮大中空如按葱管为芤脉"},{"q":"与生活密切接触有关的疾病是","o":["肺痨","头痛","水肿","中风","消渴"],"a":0,"e":"肺痨由痨虫感染所致，属传染性疾病，与生活环境密切接触相关。头痛、水肿、中风、消渴多由情志、饮食、劳倦或脏腑内伤而成，不因密切接触传播，故不属此类"},{"q":"望痰有助于诊察哪些脏腑的功能状态及病邪的性质","o":["肺脾肾","肺肝肾","心肺肝","肺胃肾","心肺肾"],"a":0,"e":"痰由水液代谢障碍而成，肺主宣发肃降、通调水道，脾主运化水湿，肾主水液，三脏功能失常均可聚湿生痰，故望痰可测肺脾肾。肝主疏泄、胃主受纳，与痰的生成关系不如脾肾直接，心肺肝、肺胃肾等组合均未涵盖生痰的关键脏腑"},{"q":"下列哪项不属于证候真假","o":["阴盛格阳证","上寒下热证","至虚有盛候","大实有羸状","阳盛格阴证"],"a":1,"e":"证候真假指疾病本质与现象不一致，含寒热真假的阴盛格阳、阳盛格阴，以及虚实真假的至虚有盛候、大实有羸状。上寒下热是寒与热同时并见于不同部位，属寒热错杂，本质与表现一致，不属真假范畴"},{"q":"腹部高度胀大如鼓，称为","o":["结胸","虚痞","水饮","食积","臌胀"],"a":4,"e":"臌胀以腹部高度胀大如鼓为特征，多由肝脾肾功能失调、气滞水停所致。结胸为邪热与痰水结于胸中，虚痞为自觉痞满而无外形胀大，水饮、食积虽可见腹部胀满，但均不至于高度膨隆如鼓"},{"q":"阴虚证中少见","o":["心阴虚","肺阴虚","肝阴虚","脾阴虚","肾阴虚"],"a":3,"e":"阴虚证以心、肺、肝、肾阴虚最为常见，各有其典型表现。脾主运化，其虚多以脾气虚、脾阳虚显现，脾阴虚缺乏公认的独立证候，临床少见。心阴虚见心悸失眠，肺阴虚见干咳，肝阴虚见目涩胁痛，肾阴虚见腰膝酸软潮热"},{"q":"濡脉的脉象特征是","o":["浮大无力","沉细而软","浮细而软","极细极软","脉细如线"],"a":2,"e":"濡脉为浮细而软，轻取即得、细软无力，主诸虚与湿证。浮大无力为虚脉，沉细而软为弱脉，极细极软为微脉，脉细如线为细脉，诸脉或脉位不同，或脉形有别，均与濡脉的浮细而软相异"},{"q":"下列哪项与弦脉所主病症无关","o":["肝胆病","诸痛证","痰饮证","宿食","虚劳"],"a":3,"e":"弦脉端直以长、如按琴弦，主肝胆病、诸痛证、痰饮、疟疾，虚劳、胃气衰败亦可见。宿食内停多见滑脉或紧脉，以嗳腐吞酸、脘腹胀满为候，与弦脉所主无直接关联，故为无关项"},{"q":"妊娠后期出现音哑或失音者，称为","o":["金实不鸣","夺气","金破不鸣","子瘖","恶阻"],"a":3,"e":"妊娠后期因胎儿增大、气机阻滞，胞脉不通，声音不能外达而致音哑或失音，称为子瘖，分娩后多自行恢复。金实不鸣为外邪壅肺之实证失音，金破不鸣为肺肾阴虚之虚证失音，夺气为气虚声低，恶阻为妊娠呕吐"},{"q":"真寒假热的面色是","o":["满面通红","红黄隐隐","两颧潮红","两颧泛红如妆","面色萎黄"],"a":3,"e":"真寒假热为阴寒内盛、虚阳浮越，见面色苍白而两颧泛红如妆，红艳游移、时隐时现。满面通红为实热，红黄隐隐为常色，两颧潮红为阴虚内热，面色萎黄为脾胃气虚，均非虚阳浮越之象"},{"q":"胃气不足，胃阴枯竭，可形成","o":["有根苔","腐苔","剥脱苔","滑苔","腻苔"],"a":2,"e":"舌苔由胃气胃阴上蒸而成，胃气不足、胃阴枯竭则苔失所养而剥脱，甚者全剥如镜面。腐苔为阳热有余、蒸腾胃中腐浊，滑苔为寒湿内盛，腻苔为湿浊痰饮内蕴，有根苔示胃气尚存，均非胃阴枯竭所成"},{"q":"情绪抑郁，胸闷不畅而发出长吁或短叹声的是","o":["呃逆","太息","嗳气","喷嚏","喘息"],"a":1,"e":"太息为情绪抑郁、胸闷不畅时长吁短叹，是肝郁气滞的表现，叹气后胸闷可暂舒。呃逆为胃气上逆、喉间呃呃连声，嗳气为胃中气体上出，喷嚏为肺气上冲，喘息为呼吸急促，均与情志抑郁无关"},{"q":"以吐血、衄血，面红目赤，胁肋灼痛，口干口苦，烦躁失眠，大便秘结，小便短黄，舌红苔黄，脉弦数为主要表现的证是","o":["肝胆湿热证","肝风内动证","肝阳上亢证","肝火炽盛证","寒滞肝脉证"],"a":3,"e":"肝火炽盛为火热内郁于肝，见面红目赤、胁肋灼痛、口干口苦、烦躁失眠、便秘尿黄，火伤血络则吐血衄血，舌红苔黄、脉弦数。肝胆湿热以黄疸、阴痒带下为要，肝阳上亢兼腰膝酸软，肝风内动以动风为征，寒滞肝脉见少腹冷痛"},{"q":"肾阳不足所致腰痛的特点为","o":["冷痛绵绵不休","刺痛固定不移","重痛活动受限","隐痛喜按","疼痛游走不定"],"a":0,"e":"肾阳不足，腰部失于温煦，故腰痛冷痛绵绵不休、喜温喜按，兼畏寒肢冷。刺痛固定不移为瘀血，重痛活动受限为湿邪困阻，隐痛喜按多为气血虚，疼痛游走不定为风邪，均非肾阳虚腰痛特点"},{"q":"四肢抽搐，角弓反张，颈项强直，两目上视者，多属","o":["风中脏腑","肝风内动","风中经络","中风脱证","中风闭证"],"a":1,"e":"肝风内动以抽搐、角弓反张、颈项强直、两目上视为特征，由热极、阳亢、血虚或阴虚动风所致。风中脏腑、中经络及中风闭证、脱证以卒然昏倒、口眼歪斜、半身不遂为主，虽有兼风，但非以抽掣强直为主要表现"},{"q":"腹部肿块，时聚时散，按之无形，痛无定处，为","o":["癥积","瘕聚","虫积","燥屎","蓄水"],"a":1,"e":"瘕聚属聚证，为气机郁滞、聚散无常，故肿块时聚时散、按之无形、痛无定处。癥积属积证，为瘀血内停、有形可征、推之不移、痛有定处，虫积、燥屎、蓄水虽成块，但各有排便或积水特征，非时聚时散"},{"q":"命名痰、悬、支、溢四饮的依据是","o":["饮邪的性质","饮停的部位","饮邪的多少","饮停的先后","饮停的原因"],"a":1,"e":"痰饮、悬饮、支饮、溢饮之名，依饮邪停聚的部位而定：痰饮停胃肠，悬饮停胸胁，支饮停胸膈肺胃，溢饮溢于四肢肌肤。饮邪性质均为水湿，多少、先后、原因皆非命名依据"},{"q":"三部举按均有力的脉象是","o":["滑脉","紧脉","实脉","弦脉","洪脉"],"a":2,"e":"实脉三部九候举按皆有力，为邪气盛而正气不虚。滑脉如盘走珠、流利圆滑，紧脉绷急弹指，弦脉端直以长，洪脉浮大有力而来盛去衰，四者虽有力，但或非三部皆然，或兼形态特征，均非举按俱有力"},{"q":"下列各项，不属湿热蕴脾证的临床表现的是","o":["纳呆厌食","呕恶口苦","口甜或口黏","便溏不爽","面色晦黄"],"a":4,"e":"湿热蕴脾见纳呆厌食、呕恶口苦、口甜口黏、便溏不爽、身热困重，黄疸鲜明如橘。面色晦黄属寒湿困脾，为阴黄，由寒湿郁滞、阳气不宣所致，与湿热的鲜明色泽有别"},{"q":"下列各项，属于“体征”的是","o":["头晕头重","恶心欲吐","神疲乏力","手指麻木","大便腥臭"],"a":4,"e":"体征是医者客观检查所得，大便腥臭可经闻诊嗅知，属客观所见。头晕头重、恶心欲吐、神疲乏力、手指麻木均为患者自觉不适，属症状，须由患者陈述，非医者直接察知"},{"q":"下列哪项不属于心阳虚证的常见症状","o":["心悸","心痛","心烦","气短","自汗"],"a":2,"e":"心阳虚以心失温养、胸阳不振为要，见心悸、心痛、气短、自汗、畏寒肢冷、舌淡胖。心烦为心阴虚或心火亢盛、热扰心神的表现，不属心阳虚常见症状"},{"q":"脉来急速，一息七八至者为","o":["促脉","疾脉","动脉","洪脉","紧脉"],"a":1,"e":"疾脉脉来急速，一息七八至以上，主阳极阴竭、元气将脱。促脉为数而时止、止无定数，动脉为脉短如豆、滑数有力，洪脉浮大来盛去衰，紧脉绷急有力，均非一息七八至"},{"q":"与地方水土失调密切相关的是","o":["乳蛾","发颐","痄腮","瘿瘤","瘰疬"],"a":3,"e":"瘿瘤为颈前肿块，多因地域水土偏颇、饮食缺碘，致痰气凝结于颈前，与地方水土失调关系最密。乳蛾、发颐、痄腮为外感风热或疫毒，瘰疬多由痰火郁结，均不以水土为主要成因"},{"q":"咳吐脓血腥臭痰，或吐脓痰如米粥者，属","o":["肺痿","肺痨","肺胀","肺痈","热痰"],"a":3,"e":"肺痈为热毒壅肺、血肉腐坏成脓，以咳吐脓血腥臭痰、或吐脓痰如米粥为特征，兼发热胸痛。肺痿为肺叶痿弱、咳吐浊唾涎沫，肺痨见干咳咯血潮热，肺胀见喘息胀满，热痰仅痰黄稠，均无腥臭脓血"},{"q":"吸气时间延长，多因吸气困难所致，常见于","o":["哮喘","肺胀","悬饮","痰饮停肺、急喉风、白喉","鼓胀、胸腔积液"],"a":3,"e":"吸气困难、吸气时间延长属吸气性呼吸困难，因上呼吸道狭窄或梗阻所致，常见于痰饮停肺、急喉风、白喉及喉部异物。哮喘、肺胀为呼气性呼吸困难，鼓胀、胸腔积液多致混合性呼吸困难，均非单纯吸气延长"},{"q":"黄燥苔常见于","o":["虚热证","湿热证","实热证","假热证","表热证"],"a":2,"e":"黄燥苔为里热炽盛、津液受损之象，主实热证，兼口渴、便秘、脉数。湿热证多见黄腻苔，虚热证见舌红少苔，表热证苔薄黄，假热证见真寒假热之舌象，均非黄而燥"},{"q":"以皮肤瘙痒，肢体麻木，屈伸不利，肌肉瞤动，爪甲不荣，面白无华，舌质淡白，脉细或弱为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","肝胆湿热证"],"a":0,"e":"血虚生风由血液亏虚、筋脉失养而动风，见皮肤瘙痒、肢体麻木、屈伸不利、肌肉瞤动、爪甲不荣，兼面白无华、舌淡白、脉细弱。肝阳化风以眩晕欲仆、头摇肢颤为主，阴虚风动手足蠕动兼潮热，热极生风见高热抽搐"},{"q":"症见咳喘痰多色白，甚至喉中哮鸣，伴形寒肢冷，舌淡苔白腻，脉濡缓者，应辨证为","o":["饮停胸胁证","风寒犯肺证","寒湿困脾证","肾不纳气证","寒痰阻肺证"],"a":4,"e":"寒痰阻肺为寒邪与痰浊壅肺，见咳喘痰多色白、喉中哮鸣、形寒肢冷、舌淡苔白腻、脉濡缓。风寒犯肺必兼恶寒发热无汗等表证，饮停胸胁以胸胁胀满、咳引痛为要，肾不纳气见呼多吸少"},{"q":"阴虚火旺的舌象可见","o":["舌灰黑而干燥","舌红苔黄","舌红苔灰黑而腻","舌红苔黄腻","舌绛苔少"],"a":4,"e":"阴虚火旺为阴液亏少、虚火内扰，舌红绛而苔少或剥，兼潮热盗汗、五心烦热。舌灰黑而干燥为热极伤津，舌红苔黄为实热，舌红苔灰黑而腻为湿热，舌红苔黄腻为湿热内蕴"},{"q":"肝阳上亢所致头痛的特点是","o":["灼痛","隐痛","窜痛","胀痛","绞痛"],"a":3,"e":"肝阳上亢为肝阳偏亢、上扰清窍，头痛多胀痛，兼眩晕、面红目赤、急躁易怒、腰膝酸软。灼痛属火热，隐痛属虚，窜痛属风，绞痛为实邪阻闭，均非肝阳上亢头痛特征"},{"q":"某些舌体病变，如舌痛、舌疮等，亦常责之于哪个脏腑","o":["心","肝","脾","肺","小肠"],"a":0,"e":"心开窍于舌，舌为心之苗，舌体病变如舌痛、舌疮、舌尖红赤多责之心火亢盛。肝开窍于目，脾开窍于口，肺开窍于鼻，小肠虽与心相表里，但舌之病变直责于心"},{"q":"口角流涎而不自知，睡则更甚，多属","o":["肾寒","肾虚","胃寒","湿热","脾虚"],"a":4,"e":"脾主运化水湿、主涎，脾虚不能收摄，故口角流涎而不自知，睡后脾气更弱则流涎更甚。肾寒多唾清稀，胃寒多泛吐清水，湿热多口黏口苦，均非睡则加重的口角流涎"},{"q":"肺气上逆的病因病机，下述哪项不对","o":["外邪犯肺","痰饮停肺","肾不纳气","肺失宣发","肺失肃降"],"a":2,"e":"肺气上逆源于肺失宣降，外邪犯肺、痰饮停肺、肺失宣发肃降均可致咳喘。肾不纳气是肾摄纳无权、气不归元，见呼多吸少、动则喘甚，病机在肾而非肺气上逆，故为不对项"},{"q":"上焦病证的临床表现是","o":["身热额红","口燥咽干","手足蠕动","发热汗出","时腹自痛"],"a":3,"e":"上焦病证属三焦辨证初期，邪犯肺卫，见发热汗出、咳嗽、口渴、脉浮数。身热颧红、口燥咽干多为阴虚或下部病变，手足蠕动属下焦虚风，时腹自痛属中焦太阴"},{"q":"洪脉主病","o":["气分热盛","湿热蕴结","外感表证","肝失疏泄","宿食积滞"],"a":0,"e":"洪脉浮大有力、来盛去衰，主气分热盛，邪热亢盛而正气尚足。湿热蕴结多为濡数或滑数，外感表证多浮脉，肝失疏泄多弦脉，宿食积滞多滑脉或紧脉"},{"q":"津液输布障碍而致舌苔干燥者可见","o":["舌红苔黄","舌红绛有芒刺","舌红绛少苔","舌青紫有瘀斑","舌淡白苔白腻"],"a":4,"e":"津液输布障碍时，湿浊内停而津液不能上承于舌，可见舌淡白苔白腻而干。舌红苔黄、舌红绛有芒刺均为热盛伤津，舌红绛少苔为阴虚，舌青紫有瘀斑为瘀血，皆非输布障碍"},{"q":"不能归属于阳证的是","o":["面红目赤","疼痛喜按","心烦不宁","脉数有力","发热口苦"],"a":1,"e":"疼痛喜按为虚证、阴证，因气血不足、脏腑失养，按之则舒。面红目赤、心烦不宁、脉数有力、发热口苦均为热盛、邪实之象，归属阳证"},{"q":"对心肝血虚证最有诊断意义的是","o":["心悸健忘、面白舌淡","头晕目眩、月经停闭","手足震颤、头晕目眩","视物模糊、爪甲不荣","失眠多梦、肢麻脉细"],"a":4,"e":"心肝血虚须兼具心血虚与肝血虚，失眠多梦为心血不足、心神失养，肢麻脉细为肝血亏虚、筋脉失养，合之最具诊断意义。心悸健忘面白偏心血虚，头晕月经停闭、视物模糊爪甲不荣偏肝血虚，手足震颤为血虚动风"},{"q":"对人体生命活动外在表现高度概括的是","o":["神","精","气","血","液"],"a":0,"e":"神是人体生命活动及其外在表现的高度概括，望神可判断脏腑精气盛衰与病情轻重。精为生命物质基础，气为动力，血与液为物质，均不似神之总括外在表现"},{"q":"叩诊腹大而胀的病人，叩之如鼓者为","o":["水臌","气胀","食积","癥积","瘕聚"],"a":1,"e":"腹大而胀、叩之如鼓为气胀，乃气机郁滞、气体充斥肠间。水臌叩之呈浊音并有移动性浊音，食积、癥积、瘕聚虽见肿块，但叩诊不呈鼓音，或仅限于局部"},{"q":"下列不属于望舌苔的是","o":["腐腻","有根无根","老嫩","黄或灰黑","剥落偏全"],"a":2,"e":"望舌苔主要察苔色与苔质，包括腐腻、有根无根、黄或灰黑、剥落偏全等。老嫩属望舌质的内容，反映脏腑虚实与正气盛衰，不属舌苔范畴"},{"q":"下列哪项与瘦薄舌形成有关","o":["脾肾阳虚","气血瘀积","心脾热盛","气血两虚、阴虚火旺","寒湿内生"],"a":3,"e":"瘦薄舌因舌体失养而成，气血两虚则舌淡瘦薄，阴虚火旺则舌红瘦薄。脾肾阳虚多见舌淡胖，气血瘀积见舌紫暗或有瘀斑，心脾热盛见舌红苔黄，寒湿内生见舌淡苔白腻"},{"q":"口干但欲漱水不欲咽者，多属","o":["风热袭表","里热亢盛","阳气虚衰","瘀血内阻","湿热内蕴"],"a":3,"e":"瘀血内阻，气血运行不畅，津液不能上承，故口干但欲漱水不欲咽。风热袭表见口渴咽痛，里热亢盛见大渴引饮，阳气虚衰见口淡不渴，湿热内蕴见口黏口苦而不欲多饮"},{"q":"可见于表邪入里的有","o":["昨起恶寒发热，现仅发热恶热","吐泻后烦渴多饮","起病即舌红苔黄","晨起头痛恶风脉浮数","发热重微恶寒"],"a":0,"e":"表邪入里是由表证转化为里证，先见恶寒发热并见，继则恶寒消失、但发热恶热，标志病位由表入里。吐泻后烦渴为津伤，起病即舌红苔黄为里证初起，脉浮数、发热重微恶寒均为表证"},{"q":"下列除哪项外为脉体较长的脉象","o":["实脉","牢脉","革脉","动脉","滑脉"],"a":3,"e":"动脉脉短如豆、滑数有力，脉体短而不长。实脉、牢脉、革脉、滑脉均脉体较长或应指充盈，其中牢脉沉而长、革脉浮而长，故动脉为脉体不长之例"},{"q":"痰阻心脉之心脉痹阻证心胸疼痛的特点是","o":["刺痛","胀痛","冷痛","灼痛","闷痛"],"a":4,"e":"痰浊阻闭心脉，气机不利，故心胸闷痛，兼胸闷、苔腻、脉滑。瘀血阻络为刺痛，寒凝心脉为冷痛，热邪壅滞为灼痛，气机郁滞为胀痛，各有其特征"},{"q":"以下不属于数脉类的是","o":["疾脉","动脉","数脉","促脉","洪脉"],"a":4,"e":"数脉类包括数、疾、促、动、滑等，均以脉率快或频率异常为要。洪脉浮大有力、来盛去衰，以脉形阔大为主，归属浮脉类，不属数脉类"},{"q":"寸口脉按寸关尺分候脏腑，右寸当候","o":["心与膻中","肝胆与膈","肺与胸中","脾胃","肾与小腹"],"a":2,"e":"寸口分候脏腑中，右寸候肺与胸中。左寸候心与膻中，左关候肝胆与膈，右关候脾胃，尺部候肾与小腹，与右寸所候不同"},{"q":"下列各项，属于寒滞胃脘证的临床表现的是","o":["消谷善饥","饥不欲食","胃痛且势剧","大便秘结","舌红苔黄"],"a":2,"e":"寒滞胃脘为寒邪犯胃、胃气凝滞，胃痛势剧、喜温恶寒、遇冷加重。消谷善饥为胃火亢盛，饥不欲食为胃阴虚，大便秘结多属实热或阴虚，舌红苔黄为热象"},{"q":"肢体筋脉迟缓，痿软无力，丧失功能，日久可致肌肉萎缩者，多见于","o":["痹证","厥证","癫证","痉证","痿证"],"a":4,"e":"痿证以肢体筋脉弛缓、痿软无力、丧失功能，日久肌肉萎缩为特征，多由肺热津伤、湿热浸淫或肝肾亏虚所致。痹证以关节疼痛麻木为主，痉证以项背强急抽搐为主，厥证以突然昏倒为主，癫证以神志异常为主"},{"q":"以手足蠕动，肢体抽搐，口咽干燥，形体消瘦，五心烦热，舌红少津，脉弦细数为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚动风证","热极生风证","寒滞肝脉证"],"a":2,"e":"阴虚动风由阴液亏虚、筋脉失养而动风，见手足蠕动、肢体抽搐，兼口咽干燥、形体消瘦、五心烦热、舌红少津、脉弦细数。血虚生风兼面白舌淡，肝阳化风兼眩晕头摇，热极生风兼高热神昏"},{"q":"苔黑而滑润，多属","o":["湿热郁蒸","阴虚火旺","热盛伤津","痰火内蕴","寒盛阳衰"],"a":4,"e":"苔黑而滑润为阳虚寒盛、水寒内停，属寒盛阳衰。湿热郁蒸多黄腻苔，阴虚火旺见舌红少苔，热盛伤津见黑苔干燥，痰火内蕴见黄腻苔，均非黑而滑润"},{"q":"气虚类证不包括下列哪项","o":["气虚证","气逆证","气脱证","气陷证","气不固证"],"a":1,"e":"气虚类证以气虚为基础，含气虚、气陷、气脱、气不固。气逆为气机升降失常、气上逆不降，属气机失调类，与气滞同类，不属气虚类证"},{"q":"脘腹胀痛，走窜不定，嗳气、肠鸣、矢气后胀痛可减，应诊断为","o":["食滞胃肠证","寒滞胃脘证","虫积肠道证","胃肠气滞证","饮停胃肠证"],"a":3,"e":"胃肠气滞为气机郁滞于胃肠，见脘腹胀痛、走窜不定，嗳气、肠鸣、矢气后气机暂通则胀痛减轻。食滞胃肠见嗳腐吞酸、泻下臭秽，寒滞胃脘见冷痛喜温，饮停胃肠见肠鸣漉漉、吐清涎"},{"q":"恶寒，身热不扬，胸闷，咳嗽，苔白腻属","o":["邪袭肺卫证","湿浊阻肺证","邪陷心包证","湿蒙心包证","邪热壅肺证"],"a":1,"e":"湿浊阻肺为湿邪困肺、肺气不利，见恶寒、身热不扬、胸闷、咳嗽、苔白腻。邪袭肺卫见发热恶寒、脉浮，邪热壅肺见咳喘痰黄，邪陷心包、湿蒙心包均以神志异常为主"},{"q":"“见微知著”的诊断原理最主要是指","o":["从轻微的表现预测严重的病变","从局部的微小变化测知整体状态","从隐蔽的症状测知明显的症状","从易忽略的体征中求得病情","运用特殊诊法诊断出病证"],"a":1,"e":"见微知著指通过局部、细微的变化测知整体状态与内在病变，如望舌、切脉以判断脏腑。从轻微表现预测严重病变、从隐蔽症状测知明显症状等说法均未切中由局部测整体这一核心"},{"q":"“寒包火”属于","o":["真虚假实","真寒假热","真热假寒","证候错杂","证候转化"],"a":3,"e":"寒包火为外有表寒、内有里热，寒与热并见于表里，属寒热错杂，即证候错杂。真虚假实、真寒假热、真热假寒均属本质与现象不符的证候真假，证候转化指寒热虚实的相互转变"},{"q":"属阳证表现的是","o":["恶寒畏冷","倦怠无力","腹痛喜按","大便溏泄","小便短赤"],"a":4,"e":"小便短赤为里热伤津，属阳证表现。恶寒畏冷、倦怠无力、腹痛喜按、大便溏泄均为功能减退、寒象或虚象，归属阴证"},{"q":"痰清稀而多泡沫，多属","o":["寒痰","风痰","湿痰","燥痰","热痰"],"a":1,"e":"风痰为痰浊夹风，见痰清稀而多泡沫，兼眩晕、肢麻、震颤。寒痰白清稀，湿痰白量多易咯，燥痰少而黏难咯，热痰黄稠，均无清稀多泡沫之特征"},{"q":"坐时常以手抱头，头倾不能昂，神情呆钝，多属","o":["肝阳化风","气虚体弱","水气凌心","精神衰败","肺气壅滞"],"a":3,"e":"坐时常以手抱头、头倾不能昂、神情呆钝，为精神衰败、精气将竭之象。肝阳化风见头摇肢颤，气虚体弱见少气懒言，水气凌心见心悸水肿，肺气壅滞见咳喘胸闷"},{"q":"以眩晕头摇，舌强语謇，肢体震颤，手足麻木，舌红，脉弦细为主要表现的证是","o":["血虚生风证","肝阳化风证","肝阳上亢证","肝火炽盛证","寒滞肝脉证"],"a":1,"e":"肝阳化风由肝阳亢极化风，见眩晕头摇、舌强语謇、肢体震颤、手足麻木，舌红、脉弦细。血虚生风兼面白舌淡，肝阳上亢以胀痛眩晕为主而无动风，寒滞肝脉见少腹冷痛"},{"q":"腹痛喜温喜按，大便清稀，肢体浮肿，口淡不渴，形寒肢冷，证属","o":["肺气虚证","脾气虚证","胃阳虚证","脾阳虚证","脾肺气虚证"],"a":3,"e":"脾阳虚为中阳不足、寒湿内生，见腹痛喜温喜按、大便清稀、肢体浮肿、口淡不渴、形寒肢冷。肺气虚见咳喘气短，脾气虚无寒象，胃阳虚以胃脘冷痛为主，脾肺气虚兼咳痰"},{"q":"弱脉与濡脉的主要区别在于","o":["脉势","脉态","脉位","节律","至数"],"a":2,"e":"濡脉浮细而软，弱脉沉细而软，二者脉形、脉势相近，主要区别在脉位浮沉。脉态、节律、至数非二者差异所在"},{"q":"小儿囟门凸出，多属于","o":["温病火邪上攻，脑髓有病","吐泻伤津，或气血不足","肾精亏虚，脑髓失充","肾气不足，发育不良","肾阴不足，虚火上炎"],"a":0,"e":"小儿囟门凸出称囟填，多因温病火邪上攻、脑髓有病。吐泻伤津或气血不足致囟陷，肾精亏虚、脑髓失充致解颅、发育不良，肾阴不足虚火上炎不以致囟凸为主"},{"q":"咳声重浊，痰多色白者，多属","o":["风寒束表","寒邪客肺","痰湿阻肺","阴虚肺燥","热邪壅肺"],"a":2,"e":"痰湿阻肺为痰湿壅肺、肺气失宣，见咳声重浊、痰多色白，兼胸闷、苔白腻。风寒束表见恶寒无汗，寒邪客肺见咳痰清稀兼表寒，阴虚肺燥见干咳少痰，热邪壅肺见痰黄稠"},{"q":"外感表证失治误治损伤人体正气为","o":["实证","虚证","虚证转实","实证转虚","真虚假实"],"a":3,"e":"外感表证本属实证，失治误治损伤正气，正气由盛转虚，形成实证转虚。虚证转实为正虚基础上邪实壅盛，真虚假实为本质虚而现象实，均非由表证误治而来"},{"q":"喉中痰鸣，咯痰黄稠量多者属","o":["肺热炽盛证","风热犯肺证","痰热壅肺证","肠热腑实证","肺阴虚证"],"a":2,"e":"痰热壅肺为痰浊与热邪互结于肺，见喉中痰鸣、咯痰黄稠量多、胸闷喘息。肺热炽盛以发热咳喘为主，风热犯肺兼表热，肠热腑实见便秘谵语，肺阴虚见干咳少痰"},{"q":"宗气外泄之时，虚里搏动应为","o":["微弱","应衣","弹手","数急","迟弱"],"a":1,"e":"虚里为宗气之外候，宗气外泄时虚里搏动亢进、动而应衣。搏动微弱为宗气内虚，弹手、数急多为邪热或气逆，迟弱为阳气不足，均非宗气外泄之应衣"},{"q":"伏脉主要表现为脉象何因素的变化","o":["脉位","脉数","脉形","脉势","脉律"],"a":0,"e":"伏脉须重按推筋着骨始得，其变化主要在脉位深沉，较沉脉更为深伏。脉数、脉形、脉势、脉律非伏脉的主要变化因素"},{"q":"下列哪项不是导致失眠的常见原因","o":["心肾不交","食滞胃脘","肝郁化火","痰湿内阻","心脾两虚"],"a":3,"e":"痰湿内阻易困脾阳，多见嗜睡、身重，非失眠常见原因。心肾不交、肝郁化火、心脾两虚、食滞胃脘均可扰动心神或胃不和而致失眠，其中痰热内扰亦致失眠，与痰湿不同"},{"q":"风水搏肺证的辨证要点是面、睑浮肿伴见","o":["卫表症状","里实症状","表虚症状","里虚症状","水湿症状"],"a":0,"e":"风水搏肺为风邪夹水湿犯肺，风邪袭表与水肿并见，辨证要点是面目浮肿伴卫表症状如恶风、发热、脉浮。里实、里虚症状及单纯水湿症状均非风水表证之辨证要点"},{"q":"下列哪项不是表里证鉴别要点","o":["寒热症状","舌象","内脏证候是否突出","脉象","汗出情况"],"a":4,"e":"表里证鉴别着重于寒热表现、舌象、脉象及内脏证候是否突出，以辨病位浅深。汗出情况可反映虚实或营卫，但不作为表里鉴别要点"},{"q":"黄腻苔多见于","o":["寒湿内结","湿热蕴结","燥热伤津","痰饮阻滞","阴虚火旺"],"a":1,"e":"黄腻苔为湿热蕴结、痰浊化热之象，主湿热证，兼口苦口黏、便溏不爽。寒湿内结多白腻苔，燥热伤津多黄燥苔，痰饮阻滞多白滑苔，阴虚火旺多舌红少苔"},{"q":"面色苍黄者，多属","o":["脾胃气虚","肝胆湿热","寒湿郁滞","脾胃湿热","肝郁脾虚"],"a":4,"e":"面色苍黄为青黄相兼，多属肝郁脾虚，肝气郁结、脾失健运。脾胃气虚见面色萎黄，寒湿郁滞见面色晦黄如阴黄，脾胃湿热见面目鲜黄，均非苍黄"},{"q":"气虚证多见哪种舌象","o":["舌淡红苔薄白","舌淡瘦苔白腻","舌淡胖苔水滑","舌淡苔薄白","舌紫黯苔少"],"a":3,"e":"气虚证气血不足、舌体失充，多见舌淡苔薄白。舌淡红苔薄白为正常舌象，舌淡胖苔水滑为阳虚水停，舌淡瘦苔白腻为脾虚湿盛，舌紫黯苔少为瘀血伤阴"},{"q":"小儿惊风的面色表现是","o":["额头色青","左颊色青","面色苍白","眉间、鼻柱、唇周色青","面黑淡黯"],"a":3,"e":"小儿惊风肝风内动，常用望指纹及面色诊断，眉间、鼻柱、唇周色青为惊风先兆。额头色青、左颊色青各有脏腑归属，面色苍白为虚寒，面黑淡黯为肾虚"},{"q":"表证的形成主要原因是","o":["外邪直中","六淫侵袭","劳倦所伤","食积","虫兽所伤"],"a":1,"e":"表证为六淫邪气侵袭肌表、卫气抗邪于外所致，以恶寒发热并见、脉浮为特点。外邪直中多直入脏腑，劳倦、食积、虫兽所伤均非表证形成的主要原因"},{"q":"鉴别假神与病情好转的最主要依据是","o":["突然神志清醒，目光转亮","言语不休，语声清亮","欲进饮食，想见亲人","面色无华，两颧泛红如妆","局部症状好转与整体病情恶化不相符合"],"a":4,"e":"假神是危重病人局部、暂时出现好转假象，如突然神清、言语不休、欲进饮食，但整体病情持续恶化，局部好转与整体恶化不相符是鉴别关键。两颧泛红如妆只是假神表现之一，不能单独作为鉴别依据"},{"q":"以下哪项为脉位沉的脉象","o":["革脉","濡脉","芤脉","牢脉","散脉"],"a":3,"e":"牢脉沉按实大弦长，脉位深沉。革脉、濡脉、芤脉、散脉均属浮脉类，轻取即得，脉位偏浮，与牢脉之沉不同"},{"q":"热证常见的面色是","o":["青色","赤色","黄色","白色","黑色"],"a":1,"e":"赤色主热证，热盛血行加速、面部络脉充盈，故面红。青色主寒、痛、瘀、惊，黄色主脾虚湿，白色主虚寒，黑色主肾虚、寒、水饮"},{"q":"青壮年头发稀疏易落，伴头皮瘙痒，多屑多脂者，多为","o":["劳心过度","精血不足","血热化燥","血虚受风","疳积"],"a":2,"e":"血热化燥，热邪伤血、头皮失润，故青壮年头发稀疏易落、头皮瘙痒、多屑多脂。精血不足见发黄干枯，血虚受风见突发斑秃，劳心过度多致脱发伴心悸失眠，疳积为小儿疳证"},{"q":"辨别疾病类别的纲领为","o":["表里","标本","寒热","虚实","阴阳"],"a":4,"e":"八纲辨证中，阴阳为辨别疾病类别的总纲，表里辨病位，寒热辨病性，虚实辨邪正。标本是辨治先后主次的概念，不属八纲"},{"q":"对诊断心脾两虚证最有诊断意义的是","o":["心悸怔忡、神疲乏力","食少腹胀、面色萎黄","心悸失眠、便溏舌淡","心烦不寐、色红少苔","失眠多梦、舌淡苔白"],"a":2,"e":"心脾两虚须兼具心血虚与脾气虚，心悸失眠为心血不足、心神失养，便溏舌淡为脾气虚弱、运化失司，合之最具意义。食少腹胀偏脾虚，心烦不寐色红少苔为阴虚火旺"},{"q":"由于地理环境影响，北方人脉象多","o":["浮数","沉实","洪数","弦滑","濡弱"],"a":1,"e":"北方地高气寒、腠理致密，气血内敛，故平脉多沉实。南方地势低湿、腠理疏松，脉多浮数或濡弱，洪数、弦滑非地域影响的典型脉象"},{"q":"蛔虫腹痛的特点是","o":["大腹隐痛","小腹胀痛","小腹刺痛","脐周腹痛","少腹冷痛"],"a":3,"e":"蛔虫寄生于小肠，扰动肠胃，故腹痛以脐周为主，时作时止，伴面黄消瘦、睡中磨牙。大腹隐痛多脾虚，小腹胀痛多气滞或膀胱，少腹冷痛多寒凝肝脉"},{"q":"关于相反的两种脉象，下列哪一项是错误的","o":["迟脉与数脉","浮脉与沉脉","洪脉与弦脉","滑脉与涩脉","紧脉与缓脉"],"a":2,"e":"对举脉象中，浮与沉、迟与数、滑与涩、紧与缓均属性质相反之配对。洪脉浮大、弦脉端直，二者并非相反，洪脉当与细脉对举，故此项错误"},{"q":"以胆怯易惊，心悸怔忡，失眠多梦，烦躁不安，口苦呕恶，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","胆郁痰扰证","肝火炽盛证"],"a":3,"e":"胆郁痰扰为痰热内扰、胆气不宁，见胆怯易惊、心悸怔忡、失眠多梦、烦躁不安、口苦呕恶，舌红苔黄腻、脉弦滑数。肝胆湿热以胁痛黄疸为主，肝火炽盛见目赤便秘，寒滞肝脉见少腹冷痛"},{"q":"尿后为余沥不尽多由于","o":["肾气不固","肾阳虚弱","瘀阻膀胱","膀胱湿热","寒凝肝脉"],"a":0,"e":"肾气不固，封藏失职，膀胱失约，故尿后余沥不尽，兼尿频、遗尿、腰膝酸软。膀胱湿热见尿频尿急尿痛，瘀阻膀胱见排尿刺痛或血尿，肾阳虚弱见夜尿多、畏寒，寒凝肝脉见少腹冷痛"},{"q":"阳虚证与气虚证的主要区别是","o":["有无少气懒言","有无神疲乏力","脉象是否无力","寒象是否明显","舌质是否淡嫩"],"a":3,"e":"气虚证仅有功能减退、少气乏力，无明显寒象；阳虚证在气虚基础上兼见畏寒肢冷等寒象，寒象是否明显是二者主要区别。少气懒言、神疲乏力、脉无力、舌淡嫩为二者共有"},{"q":"濡脉的主病是","o":["气郁，气虚","阴盛，阳极","瘀血，气滞","痰饮，食积","诸虚，湿证"],"a":4,"e":"濡脉浮细而软，主诸虚与湿证，虚证气血不足、湿证阻遏阳气皆可见。气郁气虚、瘀血气滞、痰饮食积、阴盛阳极均非濡脉所主"},{"q":"“舌赤生疮、尿赤涩灼痛”常见于哪组脏腑病变","o":["心与小肠","肾与膀胱","脾与小肠","心与膀胱","肝与膀胱"],"a":0,"e":"心开窍于舌，心火亢盛则舌赤生疮；心与小肠相表里，心火下移小肠则尿赤涩灼痛，故责之心与小肠。肾与膀胱病变多见尿频尿急或腰酸痛，脾与小肠、肝与膀胱均非此组表现"},{"q":"有形实邪阻闭气机导致的疼痛是","o":["冷痛","窜痛","绞痛","胀痛","重痛"],"a":2,"e":"绞痛为有形实邪如结石、蛔虫骤然阻闭气机，通路不通所致，痛势剧烈如绞。冷痛由寒凝，窜痛由气滞或风，胀痛由气滞，重痛由湿邪困阻"},{"q":"由于气候影响，平脉在夏天可见","o":["浮","沉","洪","弦","迟"],"a":2,"e":"夏季气候炎热，阳气外浮，气血趋向体表，平脉可见洪大，为顺应四时的生理变化。浮多与秋季或表证相关，沉多冬季，弦多春季，迟多冬季或寒"},{"q":"半表半里证的寒热特点是","o":["但寒不热","但热不寒","寒热往来","发热重恶寒轻","恶寒重发热轻"],"a":2,"e":"半表半里证邪正相争于表里之间，正胜则热、邪胜则寒，故寒热往来，为少阳病特征。但寒不热为里寒，但热不寒为里热，发热重恶寒轻为表热，恶寒重发热轻为表寒"},{"q":"肾阳不足所致腰痛的特点是","o":["冷痛绵绵不休","刺痛固定不移","重痛活动受限","隐隐作痛喜按","疼痛游走不定"],"a":0,"e":"肾阳不足，腰部失于温煦，故腰痛冷痛绵绵不休、喜温喜按，兼畏寒肢冷。刺痛固定不移为瘀血，重痛活动受限为湿困，隐痛喜按多为气血虚，疼痛游走不定为风邪"},{"q":"舌淡胖大，多为","o":["脾肾阳虚，水湿内停","脾胃湿热","痰热内蕴","心脾热盛","血络郁闭"],"a":0,"e":"舌淡胖大由阳气亏虚、水湿内停、舌体失于温化所致，多为脾肾阳虚。脾胃湿热见舌红苔黄腻，痰热内蕴见舌红苔黄腻，心脾热盛见舌尖红赤，血络郁闭见舌紫暗"},{"q":"日晡潮热可见于","o":["湿温病","热入营血","阳明经证","阳明腑证","气虚证"],"a":3,"e":"日晡潮热为午后申时热势加剧，因阳明腑实、燥屎内结、邪热内盛，属阳明腑证，兼腹满硬痛、便秘谵语。湿温病身热不扬，热入营血见身热夜甚，阳明经证见大热大汗，气虚证见气虚发热"},{"q":"病历书写一律使用阿拉伯数字书写日期和时间，采用（）小时制进行记录","o":["6","12","18","24","48"],"a":3,"e":"病历书写规范要求日期和时间一律使用阿拉伯数字，采用24小时制记录，如14时30分，以避免上午下午混淆。6、12、18、48小时制均不符合规定"},{"q":"导致头发色黄干枯，稀疏易落的主要原因是","o":["精血不足","血虚受风","肾精亏损","疳积","血热化燥"],"a":0,"e":"精血不足，发失所养，故头发色黄干枯、稀疏易落，兼面色萎黄、头晕。血虚受风见突发斑秃，肾精亏损见发脱齿摇，疳积为小儿疳证，血热化燥见脱发伴瘙痒多脂"},{"q":"绞痛一般不见于","o":["头颅部","心胸部","腰腹部","脘腹部","胁肋部"],"a":0,"e":"绞痛多因有形实邪阻闭空腔脏器，常见于心胸、胁肋、脘腹、腰腹等处。头颅部疼痛以胀痛、刺痛、跳痛、隐痛多见，无空腔绞痛之机制，故一般不见绞痛"},{"q":"脉象“有根”主要是指","o":["不浮不沉","柔和有力，节律一致","不快不慢","沉取应指有力，尺部尤显","一息四~五至"],"a":3,"e":"脉有根指沉取应指有力、尺部尤显，反映肾气充足、生机尚存。不浮不沉、不快不慢、一息四五至为平脉特征，柔和有力、节律一致为有胃气"},{"q":"心血虚证与心阴虚证皆可见到的症状是","o":["面色淡白","颧红","失眠","舌淡","脉细数"],"a":2,"e":"心血虚与心阴虚均见心神失养，故共有失眠、心悸、多梦。面色淡白、舌淡为血虚，颧红、脉细数为阴虚，二者据此相区别"},{"q":"身热不扬的表现，多由于","o":["脾气虚损","阴经郁热","外感风热","湿遏热伏","阳明腑实"],"a":3,"e":"身热不扬为湿遏热伏，湿邪郁遏，热不得外达，初按不热、稍久烫手，兼胸闷、苔腻。脾气虚损见气虚发热，外感风热见发热恶风，阳明腑实见日晡潮热"},{"q":"下列脉象中脉位浮的是","o":["迟脉","牢脉","濡脉","伏脉","弱脉"],"a":2,"e":"濡脉浮细而软，脉位偏浮，轻取即得。迟脉重在至数，牢脉、伏脉、弱脉均脉位沉，重按乃得，与濡脉之浮相反"},{"q":"以胁肋胀痛，纳呆腹胀，口苦厌油，泛恶欲呕，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","胆郁痰扰证","肝阴虚证"],"a":1,"e":"肝胆湿热为湿热蕴结肝胆，见胁肋胀痛、纳呆腹胀、口苦厌油、泛恶欲呕，舌红苔黄腻、脉弦滑数，或见黄疸。寒滞肝脉见少腹冷痛，肝郁气滞苔薄白，胆郁痰扰以惊悸为主，肝阴虚见目涩胁痛"},{"q":"热证转寒的临床意义是","o":["阳气偏盛","正气耗伤","痰湿凝聚","实证入内","寒包火证"],"a":1,"e":"热证转寒多因高热或久病耗伤正气，阳气受损、机能衰退，病情由热转寒，提示正气耗伤、病势危重。阳气偏盛致热证，痰湿凝聚成痰饮，均非转寒之机"},{"q":"亡阴证的典型表现有","o":["冷汗质稀","肢厥肤冷","呼吸气微","面赤如妆","脉微欲绝"],"a":3,"e":"亡阴证阴液暴脱，虚火内扰，见面赤如妆、身热、汗热而黏、烦躁、脉细数疾。冷汗质稀、肢厥肤冷、呼吸气微、脉微欲绝均为亡阳证，阳气暴脱之象"},{"q":"鉴别实寒证与虚寒证主要看","o":["寒重还是热重","脉之迟数","脉之有力无力","舌红还是舌白","肢体痛与不痛"],"a":2,"e":"实寒与虚寒均见寒象，鉴别关键在于脉之有力无力：实寒脉有力，虚寒脉无力。寒重热重、迟数、舌色、肢体痛与不痛均非区分虚实寒热的核心依据"},{"q":"下列哪项是太阴病“腹满”的病机","o":["腑气不通，气机壅滞","湿郁化热，气机逆乱","纳运失常，胃失和降","寒湿内生，气机阻滞","水饮不化，气机壅滞"],"a":3,"e":"太阴病属脾阳虚弱、寒湿内生，寒湿困阻中焦、气机阻滞，故腹满而吐、食不下、自利，腹满喜温喜按。腑气不通为阳明腑实，纳运失常胃失和降偏胃病，水饮不化偏饮停"},{"q":"根据五轮学说，眼睑属于","o":["心","肝","脾","肺","肾"],"a":2,"e":"五轮学说中，眼睑属肉轮，归脾，脾主肌肉；两角为血轮属心，白睛为气轮属肺，黑睛为风轮属肝，瞳仁为水轮属肾"},{"q":"以颈部瘿瘤、瘰疬、胸胁、少腹胀满疼痛、走窜不定，舌苔薄白，脉弦为主要表现的证是","o":["肝阴虚证","肝风内动证","肝郁气滞证","寒滞肝脉证","肝胆湿热证"],"a":2,"e":"肝郁气滞，气机郁滞于胸胁，故胸胁、少腹胀满疼痛、走窜不定；气郁痰结于颈前则成瘿瘤、瘰疬，舌苔薄白、脉弦。肝阴虚见目涩潮热，寒滞肝脉见少腹冷痛，肝胆湿热见口苦苔黄腻"},{"q":"下列哪项不属于正常舌象","o":["舌体柔软","舌色淡红","舌质淡嫩","舌苔均匀","薄白而湿润"],"a":2,"e":"正常舌象为淡红舌、薄白苔，舌体柔软、大小适中。舌质淡嫩为虚证舌象，多属气血不足或阳虚，不属正常舌象"},{"q":"下列脉象中，主湿的脉象多为","o":["弱脉","濡脉","弦脉","沉脉","数脉"],"a":1,"e":"濡脉浮细而软，主湿证，湿邪阻遏脉道故脉细软。弱脉主气血虚，弦脉主肝胆病痛证痰饮，沉脉主里证，数脉主热证"},{"q":"腹部肿块，推之不移，痛有定处者为","o":["瘕聚","癥积","食积","鼓胀","痞满"],"a":1,"e":"癥积为瘀血等有形实邪内停，故腹部肿块推之不移、痛有定处，病在血分。瘕聚无形、时聚时散，食积见嗳腐，鼓胀以腹大如鼓为特征，痞满为自觉痞塞"},{"q":"风寒犯肺证咳痰的特点是","o":["干咳少痰","痰稀色白","咳脓血痰","咳痰黄稠","咳痰带血"],"a":1,"e":"风寒犯肺，风寒束表、肺气失宣，见咳嗽、痰稀色白，兼鼻塞流清涕、恶寒。干咳少痰为阴虚或燥邪，脓血痰为肺痈，痰黄稠为热邪壅肺，痰带血为阴虚火旺或肺痨"},{"q":"“寸关尺分候脏腑”理论首见于","o":["《黄帝内经》","《难经》","《脉经》","《濒湖脉学》","《脉诀汇辨》"],"a":0,"e":"寸关尺分候脏腑理论首见于《黄帝内经》，《素问·脉要精微论》以上附上、中附上、尺分候胸中、膈腹及肾，即寸关尺之分。《难经》在此基础上明确三部为寸关尺，《脉经》《濒湖脉学》《脉诀汇辨》均为后世脉学著作"},{"q":"寒证一般不起因于","o":["外感寒邪","过食生冷","阳气不足","七情内伤","久病体弱"],"a":3,"e":"寒证多由外感寒邪、过食生冷、阳气不足或久病体弱，致寒邪内盛或阳气亏虚。七情内伤多致气机郁滞、化火伤阴，一般不作寒证起因"},{"q":"与阳虚关系最密切的舌色是","o":["淡白舌","淡紫舌","红绛舌","淡红舌","青紫舌"],"a":0,"e":"阳虚则阳气不足、气血不能上荣，舌色淡白，兼舌体胖嫩。淡紫舌主阳虚寒凝或瘀血，红绛舌主热，淡红舌为正常，青紫舌主瘀血"},{"q":"滑苔的形成机制是","o":["胃津、肾液上潮","寒湿内侵","热盛伤津","湿遏阳气","瘀阻"],"a":1,"e":"滑苔苔面水分过多、扪之湿滑，由寒湿内侵、水湿内停、阳气不化所致。胃津肾液上潮为正常苔，热盛伤津苔燥，湿遏阳气多腻苔，瘀阻见舌紫暗"},{"q":"耳轮干枯焦黑者多属","o":["麻疹先兆","肾阴亏虚","肾阳不足","肾精亏损","血瘀日久"],"a":3,"e":"肾开窍于耳，耳轮干枯焦黑为肾精亏损、耳失所养，兼腰酸、齿摇。麻疹先兆见耳尖发红，肾阴亏虚见耳轮红，肾阳不足见耳色淡白，血瘀日久见耳色青紫"},{"q":"肾精不足证不会出现下列哪项症状","o":["齿松发脱","腰酸膝软","健忘恍惚","耳鸣耳聋","阳强早泄"],"a":4,"e":"肾精不足见齿松发脱、腰酸膝软、健忘恍惚、耳鸣耳聋，小儿五迟五软，成人早衰。阳强早泄为阴虚火旺、相火妄动，不属肾精不足"},{"q":"囟门未闭的小儿温病火邪上攻，可表现为","o":["囟填","囟陷","解颅","巨颅","方颅"],"a":0,"e":"囟填指囟门凸起，因温病火邪上攻、脑髓有病。囟陷为吐泻伤津或气血不足，解颅为肾精亏虚、发育不良，巨颅、方颅多属先天或佝偻病"},{"q":"按脉时需重按推筋着骨始得的脉象是","o":["沉脉","牢脉","弱脉","伏脉","革脉"],"a":3,"e":"伏脉须重按推筋着骨始得，甚至按之不见，主邪闭、厥病、痛极。沉脉重按即得但不必推筋着骨，牢脉沉而实大弦长，弱脉沉细软，革脉浮而中空"}];
